insert into public.innovation_categories (id, nazwa, url, kolejnosc) values
  ('dla-seniorow', 'Dla seniorów', 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow', 1),
  ('dla-dzieci-mlodziezy-i-rodziny', 'Dla dzieci, młodzieży i rodziny', 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny', 2),
  ('dla-osob-o-ograniczonej-mobilnosci', 'Dla osób o ograniczonej mobilności', 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci', 3),
  ('dla-osob-z-niepelnosprawnoscia-sensoryczna', 'Dla osób z niepełnosprawnością sensoryczną', 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna', 4),
  ('dla-zdrowia-i-medycyny', 'Dla zdrowia i medycyny', 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-zdrowia-i-medycyny', 5),
  ('dla-rynku-pracy', 'Dla rynku pracy', 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-rynku-pracy', 6),
  ('dla-cudzoziemcow', 'Dla cudzoziemców', 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-cudzoziemcow', 7),
  ('dla-osob-w-kryzysie-bezdomnosci', 'Dla osób w kryzysie bezdomności', 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-w-kryzysie-bezdomnosci', 8),
  ('dla-osob-z-niepelnosprawnoscia-intelektualna', 'Dla osób z niepełnosprawnością intelektualną', 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna', 9),
  ('inne', 'Inne', null, 10);
insert into public.innovations (id, nazwa, kategoria_id, etykieta, sprawdzona_przez_rops, opis_krotki, problem, dla_kogo, kto_moze_wdrozyc, czy_dziala, autor_instytucja, materialy, url, slowa_kluczowe, przyklady_zapytan, spoza_biblioteki, do_matchmakingu, program, zrodlo, pewnosc, opublikowana) values
  ('bawita', 'BaWita', 'dla-seniorow', 'IWS', true, 'Drewniana tablica manipulacyjna z siedmioma ruchomymi elementami, służąca do ćwiczenia pamięci, sprawności rąk i planowania dnia u osób z zaburzeniami otępiennymi.', 'Coraz więcej seniorów z otępieniem, a mało narzędzi rehabilitacyjnych przeznaczonych dla dorosłych.', array['osoby starsze z demencją we wczesnym stadium', 'osoby po udarze lub wylewie wymagające rehabilitacji pamięci']::text[], array['placówki wsparcia dziennego seniorów', 'DPS', 'miejskie dzienne domy pomocy społecznej', 'warsztaty terapii zajęciowej', 'osoby indywidualne']::text[], 'Test potwierdził poprawę pamięci proceduralnej, małej motoryki, mowy oraz funkcjonowania społecznego.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_IN_BaWita_v15_www.pdf","film":"https://www.youtube.com/watch?v=o7UhDlebLJo","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/bawita.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,bawita', array['demencja', 'otępienie', 'alzheimer', 'pamięć', 'rehabilitacja', 'udar', 'senior', 'terapia zajęciowa', 'zaburzenia pamięci', 'ćwiczenia manualne', 'choroba otępienna']::text[], array['W naszym DPS mieszka kilka osób z początkami demencji i brakuje nam prostych pomocy do ćwiczenia pamięci.', 'Mama po udarze ma kłopoty z pamięcią i rękami, szukam czegoś do ćwiczeń w domu.']::text[], false, true, null, null, null, true),
  ('senior-cuder', 'Senior CUDER', 'dla-seniorow', 'MIIS', true, 'Gra karciana dla seniorów, która poprzez rozmowę o ciele, umyśle, duchowości, emocjach i relacjach wzmacnia motywację, dbanie o zdrowie i więzi z rodziną oraz sąsiadami.', 'Pogarszająca się kondycja, samotność, trudne emocje i osłabione relacje seniorów z otoczeniem.', array['osoby starsze samodzielne', 'osoby starsze wymagające opieki', 'rodziny i opiekunowie seniorów']::text[], array['kluby seniora', 'centra aktywności seniora', 'domy opieki', 'ZOL', 'domy dziennego pobytu', 'sanatoria', 'NGO', 'osoby indywidualne']::text[], 'Gra służy wspólnemu spędzaniu czasu, budowaniu relacji i pogłębionej refleksji nad życiem; brak twardych danych liczbowych.', 'Fundacja Wspierająca Wychowanie ARCHEZJA', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/05_CUDER.pdf","film":"https://www.youtube.com/watch?v=o5TP10ZStNA","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/seniorcuder.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,senior-cuder', array['samotność', 'senior', 'gra', 'integracja', 'relacje', 'jakość życia', 'motywacja', 'klub seniora', 'depresja', 'rozmowa', 'nowe znajomości', 'emocje']::text[], array['Seniorzy w naszym klubie są samotni i mało ze sobą rozmawiają, potrzebujemy narzędzia do zajęć grupowych.', 'Babcia mieszka sama, jest smutna i wycofana, jak jej pomóc odbudować kontakt z rodziną?']::text[], false, true, null, null, null, true),
  ('merkury', 'Merkury', 'dla-seniorow', 'IWS', true, 'Platforma internetowa z symulatorem bankomatu, parkomatu, paczkomatu i kasy samoobsługowej, na której senior może bezpiecznie przećwiczyć obsługę urządzeń w domu.', 'Seniorzy boją się korzystać z urządzeń samoobsługowych z powodu niskich kompetencji cyfrowych.', array['seniorzy bojący się obsługi bankomatu, paczkomatu i kas samoobsługowych', 'osoby starsze o niskich kompetencjach cyfrowych']::text[], array['NGO', 'dzienne domy pomocy społecznej', 'kluby seniora']::text[], 'Pozwala oswoić się z obsługą urządzeń i zmniejsza obawy przed ich używaniem w życiu codziennym.', 'Stowarzyszenie Edukacji Pozaformalnej „Meritum”', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_IN_Merkury_v4_www.pdf","film":"http://www.youtube.com/watch?v=BK6a8fjELR0&t=48s","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/merkury.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,merkury', array['kompetencje cyfrowe', 'wykluczenie cyfrowe', 'senior', 'bankomat', 'paczkomat', 'parkomat', 'kasa samoobsługowa', 'technologia', 'strach przed technologią', 'edukacja seniorów', 'symulator']::text[], array['Starsi mieszkańcy boją się wypłacać pieniądze z bankomatu i odbierać paczki z paczkomatu.', 'Chcemy w klubie seniora uczyć obsługi kas samoobsługowych, ale bez stresu dla uczestników.']::text[], false, true, null, null, null, true),
  ('organizator-kompleksowej-opieki-w-miejscu-zamieszkania', 'Organizator kompleksowej opieki w miejscu zamieszkania', 'dla-seniorow', 'MIWS', true, 'Program pilnej, wielokierunkowej pomocy w domu dla osób niesamodzielnych po wyjściu ze szpitala i ich rodzin: organizacja opieki, sprzętu i wsparcia dostosowanych do możliwości bliskich.', 'Rodzina nie wie, jak zorganizować opiekę, sprzęt i pomoc, gdy z dnia na dzień w domu pojawia się chory wymagający stałego wsparcia.', array['osoby niesamodzielne po pobycie w szpitalu', 'seniorzy po nagłym pogorszeniu zdrowia', 'rodziny i opiekunowie nieformalni']::text[], array['podmioty organizujące pielęgniarstwo opieki długoterminowej', 'JST', 'OPS']::text[], 'Wdrożenie pomaga rodzinie poradzić sobie z opieką nad chorym i zmniejsza stres opiekunów.', 'Centrum Opieki Domowej S.C.', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/01_model_COD.pdf","film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/organizatorkompleksowejopieki.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,organizator-kompleksowej-opieki-w-miejscu-zamieszkania', array['opieka domowa', 'wypis ze szpitala', 'osoba leżąca', 'opiekun rodzinny', 'niesamodzielność', 'opieka długoterminowa', 'sprzęt rehabilitacyjny', 'pielęgniarka', 'usługi opiekuńcze', 'senior', 'po szpitalu']::text[], array['Tata wraca ze szpitala po udarze, nie wiemy jak zorganizować opiekę i sprzęt w domu.', 'W gminie brakuje pomocy dla rodzin, które nagle muszą opiekować się leżącym seniorem po hospitalizacji.']::text[], false, true, null, null, null, true),
  ('przenosne-modularne-lazienki', 'Przenośne, modularne łazienki', 'dla-seniorow', 'IWS', true, 'Przenośna łazienka składana z modułów, którą można ustawić w mieszkaniu bez łazienki, bez przebudowy lokalu i bez zmiany kosztów zużycia wody i prądu.', 'Mieszkańcy lokali bez łazienki nie mogą jej zainstalować, np. z powodu nieuregulowanej własności mieszkania.', array['osoby ubogie', 'mieszkańcy lokali bez łazienki', 'osoby, które nie mogą wykonać remontu z powodów formalnych']::text[], array['urząd gminy', 'OPS', 'PCPR', 'NGO']::text[], 'Poprawia komfort i dobrostan psychiczny użytkowników, a koszty eksploatacji pozostają bez zmian.', 'OK NON-PROFIT Sp. z o.o.', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_ModularneLazienki_v4_www.pdf","film":"https://www.youtube.com/watch?v=Pl5bkpxEqgs","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/przenosnelazienki.zip","zasady_wykorzystania":null,"inne":["https://rops.krakow.pl/mpliki/IS/USUGA_WRALIWA/Instrukcja_zoenia_moduowej_azienki.pdf","https://rops.krakow.pl/mpliki/IS/USUGA_WRALIWA/za._1_Ograniczenie_dostpnosci_architektonicznej_azienek.pdf"]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,przenosne-modularne-lazienki', array['łazienka', 'brak łazienki', 'toaleta', 'higiena', 'ubóstwo', 'mieszkanie', 'lokal bez łazienki', 'warunki mieszkaniowe', 'nieuregulowana własność', 'kamienica', 'wc na zewnątrz']::text[], array['Mamy w gminie starsze osoby mieszkające bez łazienki i bez możliwości remontu, bo lokal ma nieuregulowaną własność.', 'Starszy sąsiad myje się w misce, bo w mieszkaniu nie ma łazienki, a nie stać go na przebudowę.']::text[], false, true, null, null, null, true),
  ('terapeuta-przestrzeni', 'Terapeuta przestrzeni', 'dla-seniorow', null, false, 'Usługa dostosowania mieszkania seniora do jego ograniczeń niskim kosztem, połączona z treningiem poruszania się w nowej przestrzeni i wsparciem psychologicznym dla seniora i bliskich.', 'Senior czuje, że nie radzi sobie sam w domu, co obniża jakość życia i zwiększa ryzyko trafienia do placówki całodobowej.', array['seniorzy mieszkający samodzielnie lub z rodziną', 'osoby starsze chcące zostać w swoim domu']::text[], array['OPS', 'miejskie dzienne domy pomocy społecznej', 'DPS', 'centra aktywności seniorów', 'NGO']::text[], 'W teście wzrosła samodzielność seniorów, zwłaszcza samotnych; zmiany były tanie, ale potrzebne jest wsparcie psychologiczne.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/terapeutaprzestrzeni.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,terapeuta-przestrzeni', array['adaptacja mieszkania', 'dostosowanie mieszkania', 'samodzielność', 'senior', 'ergonomia', 'upadki', 'bariery w domu', 'pozostanie w domu', 'niepełnosprawność ruchowa', 'opieka domowa', 'likwidacja progów']::text[], array['Starsza pani mieszka sama i coraz gorzej radzi sobie w domu, chcemy jej pomóc zostać w mieszkaniu zamiast iść do DPS.', 'Jak tanio przystosować mieszkanie osoby starszej, żeby nie upadała i była bardziej samodzielna?']::text[], false, true, null, null, null, true),
  ('talerze-zdrowia', 'Talerze zdrowia', 'dla-seniorow', null, false, 'Zestaw trzech obrotowych tarcz z produktami i książka z prostymi przepisami, które uczą seniorów i osoby z niepełnosprawnością intelektualną układać zbilansowane posiłki.', 'Seniorom i osobom z niepełnosprawnością intelektualną brakuje umiejętności i prostego narzędzia do komponowania zdrowych posiłków.', array['seniorzy', 'osoby z niepełnosprawnością intelektualną', 'osoby chcące nauczyć się zdrowego żywienia']::text[], array['miejskie dzienne domy pomocy społecznej', 'DPS', 'centra aktywności seniora', 'warsztaty terapii zajęciowej', 'rodzina i opiekunowie']::text[], 'Rozwiązanie tanie i proste; w ankietach wszyscy testujący uznali, że ułatwia przygotowanie posiłków i zwiększa ilość warzyw.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/talerzezdrowia.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,talerze-zdrowia', array['zdrowe odżywianie', 'dieta', 'posiłki', 'gotowanie', 'senior', 'niepełnosprawność intelektualna', 'edukacja żywieniowa', 'zbilansowana dieta', 'przepisy', 'samodzielność', 'warzywa']::text[], array['Podopieczni z niepełnosprawnością intelektualną nie potrafią sami przygotować zdrowego obiadu, szukam prostej pomocy dydaktycznej.', 'Starsi ludzie w naszym klubie jedzą byle co i chcemy zrobić warsztaty o zdrowym jedzeniu.']::text[], false, true, null, null, null, true),
  ('therapy-set', 'Therapy Set', 'dla-seniorow', null, false, 'Zestaw siedmiu pomocy terapeutycznych dla seniorów, także leżących, możliwych do wykonania przez mieszkańców DPS na warsztatach terapii, wraz ze stroną z instrukcjami i scenariuszami zajęć.', 'Część seniorów, zwłaszcza leżących i niemobilnych, ma ograniczony dostęp do terapii zajęciowej.', array['osoby starsze leżące i niemobilne', 'mieszkańcy DPS', 'seniorzy w ośrodkach dziennych', 'opiekunowie seniorów']::text[], array['DPS', 'ZOL', 'hospicja', 'hospicja domowe', 'NGO', 'warsztaty terapii zajęciowej']::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/therapyset.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,therapy-set', array['terapia zajęciowa', 'osoba leżąca', 'dps', 'senior', 'fizjoterapia', 'rehabilitacja przy łóżku', 'niemobilni', 'hospicjum', 'pomoce terapeutyczne', 'aktywizacja', 'opieka długoterminowa']::text[], array['W DPS mamy mieszkańców leżących, którzy nie mogą uczestniczyć w zajęciach terapeutycznych, potrzebujemy pomocy do pracy przy łóżku.', 'Szukamy tanich pomocy do terapii zajęciowej dla seniorów w domu opieki.']::text[], false, true, null, null, null, true),
  ('sciezka-treningu-umyslu', 'Ścieżka treningu umysłu', 'dla-seniorow', null, false, 'Plenerowa ścieżka z 12 stacjami ćwiczeń poznawczych (pamięć, logika, koncentracja, refleks), każde zadanie w trzech poziomach trudności, do ustawienia np. w parku lub na bulwarze.', 'Seniorzy mają ograniczony dostęp do form rehabilitacji i zapobiegania pogarszaniu się funkcji poznawczych.', array['seniorzy z pierwszymi objawami otępienia', 'osoby z niepełnosprawnością intelektualną', 'osoby z obniżoną sprawnością manualną']::text[], array['JST', 'zarządcy parków i bulwarów', 'DPS', 'instytucje dla osób z niepełnosprawnością intelektualną']::text[], 'Terapeuci i testujący ocenili ją bardzo dobrze; tablice trzeba jednak zrobić wodo- i mrozoodporne.', 'Politechnika Krakowska', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/sciezkatreninguumyslu.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,sciezka-treningu-umyslu', array['trening umysłu', 'pamięć', 'funkcje poznawcze', 'demencja', 'senior', 'park', 'ścieżka', 'koncentracja', 'profilaktyka otępienia', 'niepełnosprawność intelektualna', 'aktywność na świeżym powietrzu']::text[], array['Chcemy w parku miejskim zrobić miejsce, gdzie starsi mieszkańcy mogą ćwiczyć pamięć i koncentrację.', 'Jak zapobiegać pogarszaniu się pamięci u seniorów, którzy nie chodzą do żadnego ośrodka?']::text[], false, true, null, null, null, true),
  ('edu-gra-hahaha', 'Edu gra HaHaHa', 'dla-seniorow', null, false, 'Niekonkurencyjna gra planszowa z 53 kartami ćwiczeń jogi śmiechu (rozgrzewka, śmiech, integracja, oddech), która integruje grupę i podnosi poziom energii.', 'Brakuje narzędzi do podtrzymywania dobrej kondycji psychicznej seniorów i osób z niepełnosprawnościami oraz łagodnej formy rehabilitacji, jaką jest joga śmiechu.', array['osoby starsze o ograniczonej mobilności', 'osoby z niepełnosprawnością intelektualną']::text[], array['NGO', 'warsztaty terapii zajęciowej', 'szkoły specjalne', 'podmioty pracujące z seniorami']::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/edugra.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,edu-gra-hahaha', array['joga śmiechu', 'śmiech', 'gra planszowa', 'integracja', 'kondycja psychiczna', 'senior', 'niepełnosprawność', 'nastrój', 'zajęcia grupowe', 'rozładowanie stresu', 'dobre samopoczucie']::text[], array['Szukam pomysłu na wesołe zajęcia integracyjne dla seniorów i podopiecznych WTZ, które poprawią im nastrój.', 'W klubie seniora uczestnicy są przygnębieni, chcemy czegoś lekkiego, co podniesie energię grupy.']::text[], false, true, null, null, null, true),
  ('obu-obuwie-po-domu', 'Obu – obuwie po domu', 'dla-seniorow', null, false, 'Wełniane obuwie domowe dla seniorów: antypoślizgowe, dopasowane do stopy, antybakteryjne i łatwe do założenia, projektowane tak, by zmniejszać ryzyko upadków w domu.', 'Seniorzy często upadają w domu, m.in. przez śliskie podłogi i złe obuwie; upadki kończą się złamaniami, a lęk przed nimi ogranicza ruch.', array['osoby po 65. roku życia z zaburzeniami sprawności ruchowej', 'seniorzy z problemami stóp (np. haluksy) lub wzroku']::text[], array['producenci obuwia', 'dzienne domy pomocy', 'DPS', 'sanatoria', 'ośrodki rehabilitacyjne', 'osoby prywatne']::text[], 'Obuwie zwiększa mobilność i bezpieczeństwo, seniorzy chodzą pewniej; sprawdza się w domu, szpitalu i sanatorium.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/obuobuwie.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,obu-obuwie-po-domu', array['upadki', 'obuwie', 'kapcie', 'bezpieczeństwo seniora', 'złamania', 'antypoślizgowe', 'senior', 'haluksy', 'profilaktyka upadków', 'strach przed upadkiem', 'mobilność']::text[], array['Nasi starsi podopieczni często się przewracają w domu na śliskich podłogach, jak temu zapobiec?', 'Szukam bezpiecznych kapci dla babci, która boi się chodzić po mieszkaniu po upadku.']::text[], false, true, null, null, null, true),
  ('centrum-antydepresyjne', 'Centrum antydepresyjne', 'dla-seniorow', null, false, 'Wsparcie seniorów z depresją w ich domach z użyciem dogoterapii i felinoterapii, obejmujące też bliskich, by zmniejszyć ryzyko epizodów depresyjnych i zachowań samobójczych.', 'Samotni seniorzy na wsi z ryzykiem depresji i prób samobójczych mają niewielki dostęp do metod pomocy.', array['samotni seniorzy w depresji', 'osoby starsze wymagające opieki w domu', 'opiekunowie i otoczenie seniora']::text[], array['JST', 'gminy organizujące usługi opiekuńcze', 'NGO', 'podmioty ekonomii społecznej']::text[], null, 'Gmina Miechów', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/centrumantydepresyjne.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,centrum-antydepresyjne', array['depresja', 'samotność', 'senior', 'wieś', 'myśli samobójcze', 'dogoterapia', 'felinoterapia', 'zwierzęta w terapii', 'opieka domowa', 'usługi opiekuńcze', 'zdrowie psychiczne']::text[], array['Na wsi mamy samotnych starszych ludzi z objawami depresji i nikt do nich nie dociera z pomocą.', 'Jak w gminie zapobiegać samobójstwom wśród seniorów mieszkających samotnie?']::text[], false, true, null, null, null, true),
  ('zeglowanie-w-wyobrazni-czyli-sposob-na-strachy-na-wodzie', 'Żeglowanie w wyobraźni - czyli sposób na strachy na wodzie', 'dla-seniorow', null, false, 'Aplikacja wirtualnej rzeczywistości z goglami i kontrolerami, w której seniorzy 60+ i młodzi z niepełnosprawnością ruchową oswajają lęk przed wodą i uczą się żeglować; są materiały dla trenerów.', 'Osoby z niepełnosprawnością ruchową nie mają dostępu do żeglarstwa, a seniorzy boją się wejść na jacht.', array['seniorzy 60+ o ograniczonej mobilności', 'dzieci i młodzież z niepełnosprawnością ruchową', 'osoby z lękiem przed wodą']::text[], array['organizatorzy turystyki żeglarskiej i wodnej', 'ośrodki opieki nad seniorami', 'instytucje wspierające osoby z niepełnosprawnością ruchową']::text[], 'Testerzy i żeglarze ocenili ją dobrze; VR dodatkowo podnosi kompetencje cyfrowe użytkowników.', 'Fundacja Ekologia i Żagle', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/zeglowaniewwyobrazni.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,zeglowanie-w-wyobrazni-czyli-sposob-na-strachy-na-wodzie', array['żeglarstwo', 'wirtualna rzeczywistość', 'vr', 'lęk przed wodą', 'niepełnosprawność ruchowa', 'senior', 'aktywność', 'hobby', 'kompetencje cyfrowe', 'sport dla niepełnosprawnych', 'nowoczesne technologie']::text[], array['Chcemy zorganizować dzieciom na wózkach doświadczenie żeglowania, chociaż nie mogą wejść na jacht.', 'Starsi uczestnicy naszego klubu boją się wody, ale marzą o rejsie, jak ich do tego przygotować?']::text[], false, true, null, null, null, true),
  ('stworzenie-narzedzia-ulatwiajacego-seniorom-prawidlowe-regulowanie-spraw-spadkowych', 'Stworzenie narzędzia ułatwiającego seniorom prawidłowe regulowanie spraw spadkowych', 'dla-seniorow', null, false, 'Aplikacja pokazująca, kto dziedziczy z mocy ustawy, jakie są formy testamentu, i pomagająca przygotować wzór testamentu lub sprawdzić, czy potrzebny jest testament notarialny.', 'Starsze osoby mają trudny dostęp do informacji i specjalistów, by prawidłowo sporządzić testament i rozporządzić majątkiem.', array['seniorzy', 'osoby ciężko i terminalnie chore']::text[], array['hospicja', 'NGO opiekujące się chorymi terminalnie', 'osoby prywatne']::text[], 'Testerzy uznali ją za potrzebną, ale w obecnej wersji nie zadziałała: niezrozumiałe terminy, błędy w dokumencie, brak polskich znaków.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/narzedziespadkowe.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,stworzenie-narzedzia-ulatwiajacego-seniorom-prawidlowe-regulowanie-spraw-spadkowych', array['testament', 'spadek', 'dziedziczenie', 'prawo spadkowe', 'senior', 'porady prawne', 'aplikacja', 'nieodpłatna pomoc prawna', 'hospicjum', 'choroba terminalna', 'majątek']::text[], array['Starsza mieszkanka chce spisać testament, ale nie wie jak i nie stać jej na prawnika.', 'W hospicjum pacjenci pytają, jak uregulować sprawy spadkowe, brakuje nam prostego narzędzia do pomocy.']::text[], false, true, null, null, null, true),
  ('mobilne-centrum-pomocy-dla-osob-starszych', 'Mobilne centrum pomocy dla osób starszych', 'dla-seniorow', null, false, 'Mobilna usługa dojeżdżająca do domów seniorów na wsi: coaching senioralny oraz porady prawnika, dietetyka, rehabilitanta i specjalisty od budżetu domowego, dobrane do lokalnych potrzeb.', 'Starsi mieszkańcy wsi wycofują się z życia, czują się samotni i niepotrzebni, mają kłopoty z załatwianiem spraw urzędowych i dojazdem do miasta.', array['niesamodzielni seniorzy na wsi', 'osoby starsze zagrożone izolacją społeczną']::text[], array['samorządy lokalne', 'GOPS', 'NGO']::text[], null, 'Stowarzyszenie na Rzecz Zrównoważonego Rozwoju Społeczno-Gospodarczego „Klucz” oddział w Pałecznicy', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/mobilnecentrumpomocy.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,mobilne-centrum-pomocy-dla-osob-starszych', array['wieś', 'senior', 'izolacja społeczna', 'samotność', 'dojazd', 'coaching', 'mobilna pomoc', 'porady prawne', 'dietetyk', 'rehabilitacja', 'apatia', 'załatwianie spraw urzędowych']::text[], array['Starsi ludzie z odległych wsi nie dojeżdżają do ośrodka w mieście i zostają bez żadnego wsparcia.', 'Seniorzy w naszej gminie są przygnębieni i izolowani, chcemy oferty, która dotrze do nich w domu.']::text[], false, true, null, null, null, true),
  ('kody-qr-na-pomoc-seniorom', 'Kody QR na pomoc seniorom', 'dla-seniorow', null, false, 'Naszywki i naklejki z unikalnym kodem QR na ubraniu seniora z zaburzeniami pamięci; po zeskanowaniu telefonem osoba pomagająca widzi podstawowe informacje o seniorze.', 'Seniorzy z zaburzeniami pamięci lub otępieniem mają trudności z samodzielnym poruszaniem się poza domem i łatwo się gubią.', array['seniorzy z zanikami pamięci i demencją', 'osoby starsze z chorobami przewlekłymi']::text[], array['NGO', 'służby ratownictwa medycznego', 'POZ', 'jednostki pomocy społecznej', 'centra aktywności seniorów']::text[], 'Użyteczność oceniono wysoko, ale potrzebne są poprawki w bezpieczeństwie danych i trwałości oraz ponowne testy.', 'Fundacja Internationaler Bund Polska', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/kodyqr.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,kody-qr-na-pomoc-seniorom', array['kod qr', 'zaginięcie seniora', 'demencja', 'alzheimer', 'zaburzenia pamięci', 'bezpieczeństwo', 'zagubiony senior', 'identyfikacja', 'naklejka', 'naszywka', 'senior']::text[], array['Dziadek z demencją wychodzi z domu i się gubi, szukam sposobu, żeby przechodnie mogli mu pomóc i znaleźć rodzinę.', 'Jak oznaczyć osoby z chorobą Alzheimera w naszym klubie, żeby ratownicy szybko wiedzieli, kim są?']::text[], false, true, null, null, null, true),
  ('e-rzecznik-konsumenta-seniora', 'E-rzecznik konsumenta seniora', 'dla-seniorow', null, false, 'Prosta aplikacja z szybką poradą prawną z zakresu praw konsumenta dla seniorów, np. jak złożyć reklamację, odstąpić od umowy i egzekwować swoje prawa.', 'Brakuje narzędzi pomocy konsumenckiej dla starszych osób, które są szczególnie narażone na nieuczciwe praktyki sprzedawców.', array['seniorzy jako konsumenci', 'osoby starsze narażone na nieuczciwą sprzedaż']::text[], array['NGO konsumenckie', 'rzecznicy konsumentów przy urzędach gmin, miast i starostwach', 'centra aktywności seniorów', 'dzienne domy pomocy społecznej']::text[], 'Testerzy ocenili aplikację wysoko, ale część seniorów nie ufa aplikacjom i woli kontakt osobisty.', 'Stowarzyszenie Ochrony Konsumentów Aquila', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/erzecznik.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,e-rzecznik-konsumenta-seniora', array['prawa konsumenta', 'reklamacja', 'oszustwa', 'naciągacze', 'pokazy handlowe', 'odstąpienie od umowy', 'senior', 'porada prawna', 'aplikacja', 'nieuczciwa sprzedaż', 'oszukani seniorzy']::text[], array['Starsi mieszkańcy dali się namówić na drogie produkty na pokazie i nie wiedzą, jak wycofać się z umowy.', 'Seniorzy w klubie pytają, jak złożyć reklamację i gdzie szukać pomocy prawnej bez wychodzenia z domu.']::text[], false, true, null, null, null, true),
  ('sciezka-motosensoryczna', 'Ścieżka motosensoryczna', 'dla-seniorow', 'MIIS', true, 'Zestaw stanowisk ćwiczeń małej motoryki w przestrzeni miejskiej z piktogramami i aplikacją z filmami, pozwalający ćwiczyć przy okazji spaceru i oswajać z miastem osoby o obniżonej sprawności.', 'Osoby o obniżonej sprawności boją się przestrzeni publicznych i rezygnują z wychodzenia; rehabilitacja kończy się poza ośrodkami terapii.', array['osoby starsze', 'osoby z niepełnosprawnością ruchową']::text[], array['gminy', 'powiaty', 'placówki medyczne i opiekuńcze z terenami zielonymi', 'podmioty z udostępnionym terenem']::text[], 'Lokalizacja przy domu pomaga oswoić się z otoczeniem i przenieść te doświadczenia dalej, w stronę oferty miasta.', 'Politechnika Krakowska', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/Moj_folder/MIIS/07_model_MOTO-SENSORYCZNY.pdf","film":"https://www.youtube.com/watch?v=4DKP0XK440U","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/sciezkamotosensoryczna.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,sciezka-motosensoryczna', array['rehabilitacja', 'ćwiczenia', 'przestrzeń publiczna', 'senior', 'niepełnosprawność ruchowa', 'lęk przed wyjściem z domu', 'fizjoterapia', 'mała motoryka', 'ścieżka zdrowia', 'park', 'profilaktyka sprawności']::text[], array['Chcemy zbudować w gminie miejsce, gdzie seniorzy i osoby z problemami z poruszaniem się mogą ćwiczyć w drodze do sklepu.', 'Starsi mieszkańcy boją się wychodzić z domu i tracą sprawność, jak ich zachęcić do ruchu na zewnątrz?']::text[], false, true, null, null, null, true),
  ('korytarz-wspomnien', 'Korytarz wspomnień', 'dla-seniorow', null, false, 'Zaaranżowany korytarz DPS ze zdjęciami mieszkańców i opiekunów oraz przyciskami odtwarzającymi nagrania, dzięki którym seniorzy z zaburzeniami pamięci przypominają sobie fakty ze swojego życia.', 'Mało narzędzi, także do pracy grupowej, dla osób z chorobami otępiennymi.', array['seniorzy z zaburzeniami pamięci', 'osoby z chorobami otępiennymi', 'mieszkańcy DPS']::text[], array['DPS']::text[], 'Test nie wykazał poprawy pamięci ani integracji, ale instalacja urozmaica dzień i ma walor terapeutyczny.', 'Fundacja Jesień na Letniej', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/korytarzwspomnien.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,korytarz-wspomnien', array['wspomnienia', 'pamięć', 'demencja', 'dps', 'reminiscencja', 'senior', 'zdjęcia', 'terapia wspomnieniami', 'choroba otępienna', 'dom pomocy społecznej', 'aranżacja przestrzeni']::text[], array['W DPS mamy mieszkańców z demencją, którzy zapominają o swojej przeszłości, szukamy sposobu na pracę ze wspomnieniami.', 'Jak urządzić przestrzeń w domu opieki, żeby pomagała osobom z zaburzeniami pamięci?']::text[], false, true, null, null, null, true),
  ('wirtualne-izby-pamieci', 'Wirtualne izby pamięci', 'dla-seniorow', null, false, 'Model pracy z seniorami łączący warsztaty fotograficzne, rozpoznawanie przedmiotów sztuki użytkowej i opowiadanie historii z budową wirtualnej galerii; zawiera podręcznik i pięć tutoriali.', 'Wykluczenie społeczne seniorów: izolacja, słabe więzi międzypokoleniowe i niskie kompetencje cyfrowe.', array['seniorzy zagrożeni izolacją', 'osoby starsze o niskich kompetencjach cyfrowych']::text[], array['centra aktywności seniora', 'grupy wsparcia seniorów', 'NGO', 'instytucje kultury']::text[], 'Test wykazał niską przydatność: seniorzy poprawili obsługę telefonu i zdjęcia, ale bez eksperta nie wskazywali wartościowych przedmiotów.', 'Stowarzyszenie Czas Przestrzeń Tożsamość', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/wirtualneizby.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-seniorow,wirtualne-izby-pamieci', array['wykluczenie cyfrowe', 'izolacja', 'senior', 'relacje międzypokoleniowe', 'fotografia', 'galeria online', 'warsztaty', 'kompetencje cyfrowe', 'opowiadanie historii', 'dziedzictwo', 'telefon']::text[], array['Chcemy w centrum seniora zorganizować warsztaty, na których starsi nauczą się robić zdjęcia telefonem i pokazywać swoje historie online.', 'Jak wciągnąć samotnych seniorów w działania z młodszymi pokoleniami i nauczyć ich obsługi internetu?']::text[], false, true, null, null, null, true),
  ('paszport-pacjenta-z-choroba-rzadka', 'Paszport pacjenta z chorobą rzadką', 'dla-zdrowia-i-medycyny', 'Inkubator Dostępności', true, 'Elektroniczny paszport z chipem NFC i aplikacją web, w którym zapisane są najważniejsze informacje o chorobie rzadkiej, lekach i lekarzach oraz standardy postępowania, zawsze do okazania lekarzowi.', 'Standardy leczenia chorób rzadkich nie są powszechnie znane lekarzom, którzy nie zajmują się tymi chorobami, co grozi błędami w leczeniu.', array['pacjenci z chorobami rzadkimi', 'rodzice dzieci z chorobami rzadkimi']::text[], array['lekarze', 'fizjoterapeuci', 'centra referencyjne', 'organizacje pacjentów', 'rodzice i pacjenci']::text[], 'Pacjenci, rodzice i lekarze ocenili paszport pozytywnie, doceniając precyzyjne opisy chorób przygotowane przez specjalistów.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Paszport_pacjenta_z_choroba_rzadka.pdf","film":"https://www.youtube.com/watch?v=7QedTbxzsPk","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/paszportpacjenta.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-zdrowia-i-medycyny,paszport-pacjenta-z-choroba-rzadka', array['choroba rzadka', 'paszport pacjenta', 'dokumentacja medyczna', 'chip nfc', 'lekarz', 'standardy leczenia', 'dystrofia mięśniowa', 'zespół marfana', 'zespół williamsa', 'rodzice chorych dzieci', 'opieka zdrowotna']::text[], array['Mój syn ma chorobę rzadką i na każdej wizycie muszę od nowa tłumaczyć lekarzom, na czym polega i jak go leczyć.', 'Pacjenci z rzadkimi chorobami w naszej organizacji potrzebują prostego sposobu, by w nagłym wypadku medycy znali ich historię.']::text[], false, true, null, null, null, true),
  ('himalaje-autyzmu', 'Himalaje autyzmu', 'dla-zdrowia-i-medycyny', 'Inkubator Dostępności', true, 'Czterostopniowa metoda przygotowania osoby ze spektrum autyzmu do wizyty w przychodni, szpitalu czy punkcie pobrań, oparta na scenariuszach postępowania i zmniejszająca stres.', 'Osoby z autyzmem i trudnymi zachowaniami (także agresywnymi) mają utrudniony dostęp do badań i leczenia.', array['dorosłe osoby ze spektrum autyzmu', 'osoby neuroatypowe z trudnymi zachowaniami', 'ich asystenci i rodziny']::text[], array['placówki medyczne', 'szpitale', 'NGO', 'podmioty zatrudniające asystentów osób z niepełnosprawnością', 'rodziny']::text[], 'Uznana za realną i skuteczną; pozwala zaplanować wizytę tak, by zmniejszyć stres, i uczy opiekunów przygotowania do procedur.', 'Chrześcijańskie Stowarzyszenie Osób Niepełnosprawnych, ich Rodzin i Przyjaciół „Ognisko”', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Himalaje_Autyzmu.pdf","film":"https://www.youtube.com/watch?v=q31uQ435YAo","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/himalajeautyzmu.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-zdrowia-i-medycyny,himalaje-autyzmu', array['autyzm', 'spektrum autyzmu', 'wizyta u lekarza', 'badania', 'agresja', 'autoagresja', 'niepełnosprawność', 'asystent osoby niepełnosprawnej', 'trudne zachowania', 'pobranie krwi', 'szpital', 'neuroatypowość']::text[], array['Dorosły podopiecznego z autyzmem nie pozwala się badać i wpada w agresję w gabinecie, jak go przygotować do wizyty?', 'Jako asystent osoby z niepełnosprawnością szukam metody, by spokojnie zaprowadzić ją na pobranie krwi.']::text[], false, true, null, null, null, true),
  ('gra-o-zdrowie', 'Gra o zdrowie', 'dla-zdrowia-i-medycyny', 'Inkubator Dostępności', true, 'Terapeutyczna gra planszowa, w której gracze wcielają się w role z rynku pracy (pracownik, pracodawca, kandydat) i ćwiczą wejście lub powrót do zatrudnienia po kryzysie psychicznym.', 'Mało gier terapeutycznych dla osób w kryzysie psychicznym dotyczących pracy, a powrót do zatrudnienia pomaga uniknąć nawrotu kryzysu.', array['osoby w kryzysie psychicznym', 'pacjenci po psychozie lub z zaburzeniami nastroju wracający do pracy']::text[], array['oddziały dzienne', 'ŚDS', 'kluby pacjenta', 'szkoły', 'OHP', 'urzędy pracy']::text[], 'Doceniona za prostotę i możliwość grania w częściach; zwiększyła wiedzę o rynku pracy i umiejętność radzenia sobie z trudnościami.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Gra_o_zdrowie.pdf","film":"https://www.youtube.com/watch?v=YRzg98fveHc","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/graozdrowie.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-zdrowia-i-medycyny,gra-o-zdrowie', array['kryzys psychiczny', 'psychoza', 'depresja', 'powrót do pracy', 'rynek pracy', 'gra terapeutyczna', 'zdrowie psychiczne', 'zatrudnienie', 'środowiskowy dom samopomocy', 'aktywizacja zawodowa', 'zaburzenia nastroju']::text[], array['Nasi podopieczni po kryzysie psychicznym boją się wracać do pracy, szukamy zajęć, które ich do tego przygotują.', 'Potrzebujemy narzędzia dla ŚDS, które w łagodny sposób pokaże osobom z chorobami psychicznymi, jak działa rynek pracy.']::text[], false, true, null, null, null, true),
  ('telerehabilitacja-oddechowa', 'Telerehabilitacja oddechowa', 'dla-zdrowia-i-medycyny', null, false, 'Model zdalnej rehabilitacji oddechowej z materiałami wideo i schematami ćwiczeń, który pozwala prowadzić terapię pod okiem specjalisty oraz ćwiczyć samodzielnie w domu.', 'Brakuje bezpiecznego, ujednoliconego dostępu do zdalnej rehabilitacji oddechowej, zwłaszcza dla osób mało mobilnych i z odległych miejscowości.', array['osoby z problemami układu oddechowego', 'seniorzy o ograniczonej mobilności', 'mieszkańcy terenów oddalonych', 'osoby z niepełnosprawnością']::text[], array['przychodnie rehabilitacyjne', 'podmioty wspierające osoby z dysfunkcjami oddechowymi', 'opiekunowie pacjentów']::text[], 'Grupa testująca oceniła ją pozytywnie, a testy końcowe pokazały poprawę u wszystkich pacjentów.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/telerehabilitacja.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-zdrowia-i-medycyny,telerehabilitacja-oddechowa', array['rehabilitacja oddechowa', 'telerehabilitacja', 'zdalna rehabilitacja', 'choroby płuc', 'duszność', 'po covidzie', 'ćwiczenia w domu', 'senior', 'wieś', 'fizjoterapia', 'dojazd do przychodni']::text[], array['Mieszkańcy odległych wsi mają problemy z oddychaniem, a do rehabilitacji nie mają jak dojechać.', 'Szukam sposobu na prowadzenie rehabilitacji oddechowej online dla starszych pacjentów po chorobie płuc.']::text[], false, true, null, null, null, true),
  ('inteligentny-organizer-do-lekow', 'Inteligentny organizer do leków', 'dla-zdrowia-i-medycyny', null, false, 'Organizer na leki z czujnikami i światełkami przypominającymi o porze dawki oraz aplikacją, w której opiekun ustawia godziny i dostaje powiadomienia o zażyciu lub pominięciu leku.', 'Opiekunowie rodzinni mają trudność z kontrolowaniem, czy starszy bliski regularnie bierze leki.', array['seniorzy przyjmujący leki na stałe', 'opiekunowie rodzinni i nieformalni']::text[], array['osoby prywatne', 'apteki', 'firmy farmaceutyczne']::text[], 'Wysoko użyteczny dla opiekunów, lecz prototyp miewał awarie, a montaż i obsługa sprawiały trudność; potrzebna asysta techniczna.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/inteligentnyorganizer.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-zdrowia-i-medycyny,inteligentny-organizer-do-lekow', array['leki', 'tabletki', 'przypominanie o lekach', 'organizer na leki', 'opiekun', 'senior', 'zapominanie', 'dozownik leków', 'powiadomienia', 'opieka zdalna', 'przyjmowanie leków']::text[], array['Mama zapomina brać tabletki, a ja mieszkam daleko i chcę mieć pewność, że je zażyła.', 'Szukam sposobu, żeby opiekunowie seniorów mogli zdalnie kontrolować przyjmowanie leków przez podopiecznych.']::text[], false, true, null, null, null, true),
  ('drogowskazy-ajkum', 'Drogowskazy AJKUM', 'dla-zdrowia-i-medycyny', null, false, 'System nawigacji krok po kroku po szpitalu lub centrum onkologicznym oparty na sieci punktów kontrolnych (check pointów), bez instalowania czegokolwiek na telefonie pacjenta.', 'Pacjenci onkologiczni z osłabioną percepcją gubią się w skomplikowanych budynkach medycznych i nie mogą znaleźć właściwych pomieszczeń.', array['pacjenci onkologiczni', 'osoby z obniżoną percepcją przez chorobę lub wiek', 'pacjenci bez osoby towarzyszącej']::text[], array['centra leczenia onkologicznego', 'szpitale', 'przychodnie']::text[], 'Test częściowo potwierdził skuteczność prowadzenia pacjentów, ale zasięg i czas testu były zbyt małe, by wyciągnąć jednoznaczne wnioski.', 'Fundacja Ajkum', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/drogowskazyajkum.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-zdrowia-i-medycyny,drogowskazy-ajkum', array['nawigacja w szpitalu', 'orientacja w budynku', 'pacjent onkologiczny', 'rak', 'szpital', 'zagubienie', 'dezorientacja', 'oznakowanie', 'poruszanie się po szpitalu', 'onkologia', 'przychodnia']::text[], array['Pacjenci w naszym szpitalu onkologicznym błądzą po korytarzach i potrzebują ciągłej pomocy personelu.', 'Jak ułatwić chorym i starszym osobom odnalezienie gabinetów w dużym, skomplikowanym budynku przychodni?']::text[], false, true, null, null, null, true),
  ('cold-box', 'Cold Box', 'dla-zdrowia-i-medycyny', null, false, 'Mały, wodoodporny, bateryjny pojemnik chłodzący utrzymujący 4–7 stopni, do noszenia przy sobie insuliny i innych leków wymagających schłodzenia.', 'Osoby przyjmujące leki wymagające chłodzenia mają kłopot z ich przechowywaniem i podróżowaniem.', array['osoby z cukrzycą', 'osoby przyjmujące leki wymagające stałego chłodzenia']::text[], array['osoby prywatne', 'apteki', 'przychodnie']::text[], 'Testerzy chętnie z niego korzystali, ale urządzenie jest jeszcze za duże, by wygodnie nosić je w torebce lub plecaku.', 'Fundacja Mars', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/coldbox.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-zdrowia-i-medycyny,cold-box', array['insulina', 'cukrzyca', 'chłodzenie leków', 'lodówka na leki', 'podróż', 'przechowywanie leków', 'diabetyk', 'pojemnik termiczny', 'leki w podróży', 'choroba przewlekła']::text[], array['Mój syn ma cukrzycę i potrzebuje nosić insulinę w odpowiedniej temperaturze na wycieczkach.', 'Pacjenci przyjmujący leki wymagające chłodzenia nie mogą wyjeżdżać, bo nie mają jak ich bezpiecznie przewozić.']::text[], false, true, null, null, null, true),
  ('pacjent-pro', 'Pacjent Pro', 'dla-zdrowia-i-medycyny', null, false, 'Aplikacja towarzysząca pacjentowi oddziału psychiatrycznego od przyjęcia do wypisu: informuje o zajęciach, wizytach i terapii, motywuje do udziału i pomaga zmniejszyć niepokój.', 'Pacjenci oddziału ogólnopsychiatrycznego są bardzo zaniepokojeni, a brakuje atrakcyjnych, multimedialnych form komunikacji i terapii.', array['pacjenci oddziałów psychiatrycznych', 'osoby z niepełnosprawnością intelektualną lub zaburzeniami poznawczymi w szpitalu']::text[], array['szpitale psychiatryczne', 'centra zdrowia psychicznego']::text[], 'Pomaga pacjentom zaadaptować się na oddziale, motywuje do terapii, obniża niepokój i poprawia funkcjonowanie.', 'SPZOZ Państwowy Szpital dla Nerwowo i Psychicznie Chorych w Rybniku', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/pacjentpro.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-zdrowia-i-medycyny,pacjent-pro', array['szpital psychiatryczny', 'oddział psychiatryczny', 'pacjent', 'niepokój', 'aplikacja', 'zdrowie psychiczne', 'hospitalizacja', 'terapia', 'adaptacja na oddziale', 'komunikacja z pacjentem', 'psychiatria']::text[], array['Pacjenci przyjmowani na nasz oddział psychiatryczny są zagubieni i niespokojni, szukamy sposobu na lepszą informację i motywację do zajęć.', 'Chcemy w szpitalu psychiatrycznym wprowadzić nowoczesne narzędzie do kontaktu z pacjentami i obniżenia ich lęku.']::text[], false, true, null, null, null, true),
  ('oncotriada', 'Oncotriada', 'dla-zdrowia-i-medycyny', null, false, 'Metoda wsparcia kobiet tuż po diagnozie nowotworowej: równoległa konsultacja psychoonkologa i spotkanie z wolontariuszką, która przeszła chorobę i jest w remisji.', 'Osoby po usłyszeniu diagnozy onkologicznej, przed leczeniem szpitalnym, nie dostają odpowiedniego wsparcia i przeżywają silny niepokój.', array['pacjentki w początkowej fazie diagnozy onkologicznej', 'osoby w kryzysie po usłyszeniu diagnozy nowotworowej']::text[], array['poradnie psychologiczne i psychoonkologiczne', 'szpitale onkologiczne', 'NGO wspierające chorych na raka', 'psychoonkolodzy', 'wolontariusze w remisji']::text[], 'Częściowo; trudno było pozyskać uczestniczki, a najlepiej zadziałały spotkania z wolontariuszką z tym samym typem nowotworu.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/oncotriada.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-zdrowia-i-medycyny,oncotriada', array['rak', 'nowotwór', 'diagnoza onkologiczna', 'psychoonkologia', 'wsparcie psychologiczne', 'wolontariusz', 'remisja', 'lęk', 'choroba nowotworowa', 'kryzys po diagnozie', 'grupa wsparcia']::text[], array['Kobiety, które dopiero dowiedziały się o nowotworze, zostają same z lękiem przed rozpoczęciem leczenia.', 'Chcemy w fundacji połączyć świeżo zdiagnozowane pacjentki z osobami, które pokonały chorobę, i z psychoonkologiem.']::text[], false, true, null, null, null, true),
  ('agencja-pracy-incydentalnej', 'Agencja pracy incydentalnej', 'dla-rynku-pracy', null, false, 'Model zlecania krótkich prac na zasadach nierejestrowanej działalności, bez stałych godzin, regularności i skomplikowanych papierów, dopasowywanych do możliwości osób w głębokim kryzysie.', 'Osoby w wielowymiarowym kryzysie nie są w stanie wrócić na rynek pracy przy standardowych umowach i sztywnym wymiarze czasu.', array['osoby w kryzysie bezdomności lub psychicznym', 'osoby długotrwale bezrobotne', 'osoby z przeszłością kryminalną', 'osoby z niepełnosprawnością']::text[], array['agencje pracy', 'NGO zajmujące się aktywizacją zawodową osób w kryzysie']::text[], 'Pokazuje legalną drogę zarobku, ale w teście pracę podjęły tylko 3 osoby, głównie z obawy o utratę świadczeń.', 'Fundacja Pestka', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/agencjapracy.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-rynku-pracy,agencja-pracy-incydentalnej', array['bezrobocie', 'bezdomność', 'praca dorywcza', 'praca zlecona', 'aktywizacja zawodowa', 'długotrwale bezrobotni', 'wykluczenie', 'nierejestrowana działalność', 'praca bez umowy', 'kryzys', 'powrót do pracy']::text[], array['Osoby w kryzysie bezdomności nie są w stanie podjąć etatu, ale chciałyby dorobić od czasu do czasu legalnie.', 'Jak zorganizować prostą, elastyczną pracę dla długotrwale bezrobotnych, którzy nie radzą sobie ze stałymi godzinami?']::text[], false, true, null, null, null, true),
  ('niewypaleni', 'NIEwypaleni', 'dla-rynku-pracy', null, false, 'Trzydniowy warsztat i broszura w tekście łatwym do czytania (ETR), które uczą osoby z niepełnosprawnością intelektualną rozpoznawać wypalenie zawodowe i dbać o motywację do pracy.', 'Osoby z niepełnosprawnością intelektualną trudno utrzymują pracę i szybciej się wypalają zawodowo.', array['osoby z niepełnosprawnością intelektualną pracujące lub szukające pracy']::text[], array['organizacje wspierające osoby z niepełnosprawnością intelektualną', 'pracodawcy zatrudniający takie osoby']::text[], 'Ma potencjał, ale potrzebne są dłuższe testy na większej grupie i regularne wsparcie, a nie jednorazowy warsztat.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/niewypaleni.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-rynku-pracy,niewypaleni', array['wypalenie zawodowe', 'niepełnosprawność intelektualna', 'utrzymanie pracy', 'tekst łatwy do czytania', 'etr', 'warsztat', 'motywacja do pracy', 'zatrudnienie wspomagane', 'praca', 'broszura', 'aktywizacja zawodowa']::text[], array['Nasi podopieczni z niepełnosprawnością intelektualną często rezygnują z pracy po kilku miesiącach, jak im pomóc ją utrzymać?', 'Szukam materiałów w prostym języku, które wyjaśnią osobom z niepełnosprawnością intelektualną, czym jest wypalenie w pracy.']::text[], false, true, null, null, null, true),
  ('konsultant-etr', 'Konsultant ETR', 'dla-rynku-pracy', null, false, 'Model pracy konsultanta tekstów łatwych do czytania i rozumienia: profil kompetencji, kwestionariusz doboru kandydatów i program szkoleń, dający osobom z niepełnosprawnością intelektualną nową rolę zawodową.', 'Trudno aktywizować zawodowo osoby z niepełnosprawnością intelektualną oraz znaleźć i przygotować konsultantów tekstów ETR.', array['osoby z niepełnosprawnością intelektualną', 'rodziny osób z niepełnosprawnością intelektualną']::text[], array['szkoły', 'szkoły specjalne', 'urzędy wojewódzkie', 'miasta i gminy', 'podmioty publikujące teksty ETR']::text[], 'Może być bardzo skuteczny dla wysoko funkcjonujących osób z niepełnosprawnością intelektualną, a skonsultowane teksty zwiększają grono czytelników.', 'Stowarzyszenie Rodziców i Przyjaciół Osób z Zespołem Downa – Tęcza – w Krakowie', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/konsultantetr.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-rynku-pracy,konsultant-etr', array['etr', 'tekst łatwy do czytania', 'niepełnosprawność intelektualna', 'zespół downa', 'praca', 'konsultant', 'dostępność', 'prosty język', 'zatrudnienie', 'aktywizacja zawodowa', 'szkolenie']::text[], array['Urząd chce publikować informacje w prostym języku dla osób z niepełnosprawnością intelektualną i potrzebuje kogoś, kto je sprawdzi.', 'Szukam sposobu na stworzenie realnej pracy dla dorosłych z zespołem Downa.']::text[], false, true, null, null, null, true),
  ('mobilna-gielda-pracy', 'Mobilna giełda pracy', 'dla-rynku-pracy', null, false, 'Model wydarzeń rynku pracy (giełda, doradztwo zawodowe, pośrednictwo, spotkania z pracodawcami) organizowanych mobilnie blisko domu, we wsiach i małych miastach, dla kobiet nieaktywnych zawodowo.', 'Kobiety ze wsi i małych miejscowości, nieaktywne zawodowo, mają utrudniony dostęp do rynku pracy i nie widzą szans na zatrudnienie.', array['kobiety nieaktywne zawodowo ze wsi', 'mieszkanki małych miejscowości']::text[], array['gminy', 'OPS', 'powiatowe urzędy pracy', 'lokalne NGO', 'pracodawcy', 'agencje zatrudnienia']::text[], 'Ocena neutralna; wzrosła motywacja uczestniczek, ale mało pracodawców przyszło i kobiety nie miały z czego wybierać.', 'Gmina Charsznica, Gminny Ośrodek Pomocy Społecznej w Charsznicy', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/mobilnagielda.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-rynku-pracy,mobilna-gielda-pracy', array['bezrobocie', 'kobiety', 'wieś', 'aktywizacja zawodowa', 'giełda pracy', 'doradztwo zawodowe', 'nieaktywność zawodowa', 'praca', 'pracodawcy', 'urząd pracy', 'małe miejscowości', 'dojazd do pracy']::text[], array['Kobiety z naszych wsi nie pracują, bo nie mają dojazdu do urzędu pracy ani kontaktu z pracodawcami.', 'Jak gmina może zorganizować doradztwo zawodowe i spotkania z pracodawcami blisko miejsca zamieszkania mieszkanek?']::text[], false, true, null, null, null, true),
  ('oddawacze', 'Oddawacze', 'dla-rynku-pracy', null, false, 'Ekologiczna aplikacja do przekazywania używanych rzeczy, w której odbiorca wpłaca niewielką kwotę na cel charytatywny wskazany przez osobę oddającą, dzięki czemu wspiera się też lokalne organizacje.', 'Osoby o niskich dochodach mają utrudniony dostęp do trwałych rzeczy codziennego użytku, a lokalne organizacje mają mało środków; do tego dochodzi zaśmiecanie środowiska.', array['osoby ubogie', 'mieszkańcy chcący oddać zbędne rzeczy', 'lokalne organizacje charytatywne']::text[], array['lokalne NGO', 'miasta', 'gminy']::text[], 'W małej skali test potwierdził zainteresowanie oddawaniem i przyjmowaniem rzeczy oraz chęć współpracy fundacji, ale pełnych efektów nie pokazał.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/oddawacze.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-rynku-pracy,oddawacze', array['ubóstwo', 'używane rzeczy', 'wymiana', 'za darmo', 'dary', 'ekologia', 'charytatywność', 'aplikacja', 'recykling', 'pomoc rzeczowa', 'biedni', 'second hand']::text[], array['W gminie wielu mieszkańców oddałoby niepotrzebne rzeczy, a inni ich potrzebują, brakuje nam prostego sposobu na przekazywanie.', 'Chcemy zebrać pieniądze dla naszej fundacji przy okazji wymiany używanych przedmiotów między mieszkańcami.']::text[], false, true, null, null, null, true),
  ('szlakiem-ludzi-bezdomnych', 'Szlakiem ludzi bezdomnych', 'dla-osob-w-kryzysie-bezdomnosci', null, false, 'Mobilny Punkt Higieniczny: ogrzewana przyczepa sanitarna z prysznicem, umywalką, szafką na czystą bieliznę i środkami higieny, dostępna dla osób w kryzysie bezdomności.', 'Osoby w kryzysie bezdomności nie mają jak dbać o higienę, co sprzyja chorobom.', array['osoby w kryzysie bezdomności']::text[], array['gminy miejskie', 'gminy miejsko-wiejskie', 'gminy wiejskie']::text[], 'Testujący ocenili przyczepę wyłącznie pozytywnie; po skorzystaniu niektórzy wynajęli pokój lub wrócili do schroniska.', 'Miejski Ośrodek Pomocy Społecznej w Stalowej Woli', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/szlakiemludzibezdomnych.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-w-kryzysie-bezdomnosci,szlakiem-ludzi-bezdomnych', array['bezdomność', 'higiena', 'prysznic', 'przyczepa sanitarna', 'łaźnia', 'osoby bezdomne', 'mycie', 'streetworking', 'zima', 'pomoc doraźna', 'mobilny punkt', 'choroby']::text[], array['W naszym mieście bezdomni nie mają gdzie się umyć i zmienić bielizny, zwłaszcza zimą.', 'Gmina nie ma schroniska z łazienką, szukamy mobilnego rozwiązania higienicznego dla osób na ulicy.']::text[], false, true, null, null, null, true),
  ('wiejski-program-pomocy-osobom-w-kryzysie-bezdomnosci-sciezka-feniksa', 'Wiejski program pomocy osobom w kryzysie bezdomności - Ścieżka Feniksa', 'dla-osob-w-kryzysie-bezdomnosci', null, false, 'Długofalowy, wiejski program wychodzenia z bezdomności oparty na terapii pracą z recyklingu i lokalnych materiałów, na zasobach gminy oraz na odejściu od schronisk i noclegowni na rzecz integracji.', 'Małe, zwłaszcza wiejskie gminy nie mają długofalowych i całościowych rozwiązań dla osób w kryzysie bezdomności.', array['osoby w kryzysie bezdomności', 'osoby z problemem uzależnienia na wsi']::text[], array['gminy', 'GOPS', 'NGO wspierające osoby w kryzysie bezdomności']::text[], 'W teście 9 z 11 uczestników utrzymało abstynencję, wzrosła motywacja i sprawczość, a 5 osób chciało zamieszkać na wsi; wysokie ryzyko wdrożenia.', 'Stowarzyszenie Ku Dobrej Nadziei', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/sciezkafeniksa.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-w-kryzysie-bezdomnosci,wiejski-program-pomocy-osobom-w-kryzysie-bezdomnosci-sciezka-feniksa', array['bezdomność', 'wieś', 'uzależnienie', 'alkohol', 'trzeźwość', 'terapia pracą', 'reintegracja', 'deinstytucjonalizacja', 'recykling', 'małe gminy', 'wychodzenie z bezdomności', 'gospodarstwo']::text[], array['W naszej wiejskiej gminie jest kilku bezdomnych z problemem alkoholowym, a najbliższe schronisko jest bardzo daleko.', 'Chcemy zamiast noclegowni zaproponować bezdomnym pracę i mieszkanie w lokalnej społeczności.']::text[], false, true, null, null, null, true),
  ('komix-zyciowy', 'koMIX życiowy', 'dla-dzieci-mlodziezy-i-rodziny', 'IWS', true, 'Terapeutyczna gra planszowa dla nastolatków z pieczy zastępczej i placówek opiekuńczo-wychowawczych. Karty i zadania pomagają rozpoznawać emocje, oswajać je i rozmawiać o trudnych tematach związanych z dojrzewaniem.', 'Młodzież z placówek ma kłopot z rozumieniem i radzeniem sobie z emocjami, a opiekunowie nie mają narzędzi do edukacji emocjonalnej.', array['nastolatki z placówek opiekuńczo-wychowawczych', 'młodzież w okresie dojrzewania', 'wychowankowie pieczy zastępczej']::text[], array['placówka opiekuńczo-wychowawcza', 'szkoła', 'psycholog', 'pedagog', 'NGO']::text[], 'Wspiera rozwój emocjonalny, ułatwia dzielenie się trudnościami w bezpiecznej atmosferze, integruje grupę i buduje zaufanie.', 'Fundacja „Mam dom”', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_IN_KoMIX_v6_www.pdf","film":"https://www.youtube.com/watch?v=hohm7FnsukY","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/komix.zip","zasady_wykorzystania":null,"inne":["https://rops.krakow.pl/mpliki/IS/UW/Instrukcja_koMIX_yciowy.pdf","https://rops.krakow.pl/mpliki/IS/UW/KOMIX_YCIOWY_opisy_alternatywne_awersow_i_rewersow_kart.pdf"]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,komix-zyciowy', array['gra planszowa', 'emocje', 'edukacja emocjonalna', 'nastolatki', 'młodzież', 'dojrzewanie', 'piecza zastępcza', 'dom dziecka', 'placówka opiekuńczo-wychowawcza', 'zajęcia grupowe', 'trudne emocje', 'wychowankowie']::text[], array['Wychowankowie naszego domu dziecka nie potrafią mówić o swoich emocjach i szukamy gry lub narzędzia do pracy grupowej', 'Jak pomóc nastolatkom z pieczy zastępczej oswoić złość i smutek oraz porozmawiać o dojrzewaniu?']::text[], false, true, null, null, null, true),
  ('patryk-i-kropka', 'Patryk i Kropka', 'dla-dzieci-mlodziezy-i-rodziny', 'IWS', true, 'Opowiadanie napisane w standardzie ETR (łatwy do czytania tekst) o przygodach nastolatków Patryka i Kropki. Pokazuje typowe trudności wieku nastoletniego i uczy zachowań społecznych młodzież z niepełnosprawnością intelektualną.', 'Brakuje książek dopasowanych do możliwości czytelniczych młodzieży z lekką i umiarkowaną niepełnosprawnością intelektualną.', array['młodzież z niepełnosprawnością intelektualną', 'uczniowie z lekką i umiarkowaną niepełnosprawnością intelektualną']::text[], array['biblioteka', 'szkoła integracyjna', 'WTZ', 'terapeuta', 'nauczyciel wspomagający']::text[], 'Rozwija czytanie, uczy m.in. bezpieczeństwa w sieci i zachowania w miejscach publicznych oraz rozumienia emocji innych.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_IN_PatrykIKropka_v5_www.pdf","film":"https://youtu.be/JfmyToWVuOs","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/patrykikropka.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,patryk-i-kropka', array['łatwy tekst', 'ETR', 'easy to read', 'niepełnosprawność intelektualna', 'książka', 'lektura', 'młodzież', 'czytanie', 'umiejętności społeczne', 'biblioteka', 'uczeń z niepełnosprawnością', 'edukacja włączająca']::text[], array['Szukam lektury w prostym języku dla uczniów z niepełnosprawnością intelektualną do biblioteki szkolnej', 'Jak zachęcić nastolatków z umiarkowaną niepełnosprawnością intelektualną do czytania i uczyć ich zasad zachowania w internecie?']::text[], false, true, null, null, null, true),
  ('edki-kredki-terapeutyczne', 'Edki - kredki terapeutyczne', 'dla-dzieci-mlodziezy-i-rodziny', 'IWS', true, 'Zestaw kredek o specjalnym kształcie dla dzieci ze spastyczną ręką. Kształt zachęca do prostowania dłoni, palców i nadgarstka zamiast zaciskania, więc rysowanie staje się formą terapii i ćwiczeniem prawidłowego chwytu.', 'Dzieci ze spastycznością ręki mają trudność z rysowaniem i pisaniem, a zwykłe przybory nie wspierają rehabilitacji dłoni.', array['dzieci ze spastycznością kończyny górnej', 'dzieci z porażeniem mózgowym', 'uczniowie z problemami z chwytem']::text[], array['rehabilitant', 'fizjoterapeuta', 'przedszkole', 'szkoła', 'rodzice']::text[], 'Wspomaga fizjoterapię dłoni, pozwala tworzyć, wzmacnia poczucie sprawczości i uczy poprawnego chwytu pisarskiego.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_IN_Edki_v6_www.pdf","film":"https://www.youtube.com/watch?v=ev173g-d_vA&t=5s","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/terapeutycznekredki.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,edki-kredki-terapeutyczne', array['kredki', 'spastyczność', 'porażenie mózgowe', 'rehabilitacja dłoni', 'chwyt pisarski', 'rysowanie', 'terapia przez zabawę', 'dziecko niepełnosprawne ruchowo', 'fizjoterapia', 'przybory szkolne', 'pisanie', 'niepełnosprawność ruchowa']::text[], array['Moje dziecko ma spastyczną rękę i nie potrafi utrzymać kredki, czym je wspierać w rysowaniu?', 'Szukamy pomocy do rehabilitacji dłoni dla przedszkolaków z porażeniem mózgowym']::text[], false, true, null, null, null, true),
  ('rodzina-adopcyjna-dorasta', 'Rodzina adopcyjna dorasta', 'dla-dzieci-mlodziezy-i-rodziny', 'IWS', true, 'Interaktywne materiały online dla rodziców adopcyjnych nastolatków. Tłumaczą zachowania i emocje dorastającego dziecka oraz własne reakcje rodziców, z ćwiczeniami i wiedzą do przerabiania we własnym tempie.', 'Rodzice adopcyjni przeżywają stres i frustrację w okresie dojrzewania dziecka, a dostęp do poradnictwa psychologicznego jest utrudniony.', array['rodzice adopcyjni', 'rodziny adopcyjne z nastolatkami', 'adoptowane nastolatki']::text[], array['ośrodek adopcyjny', 'NGO', 'psycholog', 'terapeuta', 'OPS']::text[], 'Daje rodzicom wiedzę o trudnościach i emocjach w rodzinach adopcyjnych i pomaga lepiej rozumieć przeżycia swoje i dziecka.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_RodzinaAdopcyjna_v5_www.pdf","film":"https://www.youtube.com/watch?v=HZzYekiW_nY","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/rodzinaadopcyjna.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,rodzina-adopcyjna-dorasta', array['adopcja', 'rodzina adopcyjna', 'rodzice adopcyjni', 'nastolatek', 'bunt', 'dojrzewanie', 'poradnictwo', 'trudności wychowawcze', 'dziecko adoptowane', 'wsparcie rodziców', 'stres rodzicielski', 'kurs online']::text[], array['Jako rodzic adoptowanego nastolatka nie radzę sobie z jego zachowaniem i nie mam dostępu do psychologa', 'Gdzie rodziny adopcyjne mogą znaleźć wsparcie w okresie buntu dziecka?']::text[], false, true, null, null, null, true),
  ('puzzle-3d', 'Puzzle 3D', 'dla-dzieci-mlodziezy-i-rodziny', 'Inkubator Dostępności', true, 'Wydrukowane w 3D układanki-zwierzątka dla niewidomych i niedowidzących dzieci. Ćwiczą dotyk i wyobraźnię przestrzenną, a także pomagają w nauce Braille''a oraz dzielenia wyrazów na litery.', 'Brakuje atrakcyjnych pomocy edukacyjnych dla niewidomych dzieci, które rozwijałyby jednocześnie różne umiejętności.', array['dzieci niewidome', 'dzieci niedowidzące', 'uczniowie z niepełnosprawnością wzroku']::text[], array['szkoła specjalna', 'nauczyciel', 'NGO', 'rodzice', 'biblioteka']::text[], 'Dzieci i nauczyciele w szkole dla niewidomych ocenili puzzle pozytywnie, doceniając przestrzenność i przyjazny temat zwierząt.', 'Społeczna 21 Sp. z o.o.', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Wykorzystanie_druku_3D_w_tworzeniu_zabawek_dla_dzieci_niewidomych.pdf","film":"https://www.youtube.com/watch?v=T_OM-4WqGzE","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/wykorzystaniedruku3d.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,puzzle-3d', array['puzzle', 'druk 3D', 'niewidome dziecko', 'niewidomy', 'niedowidzący', 'Braille', 'zabawki edukacyjne', 'percepcja dotykowa', 'pomoce dydaktyczne', 'niepełnosprawność wzroku', 'układanka', 'nauka czytania']::text[], array['Szukam zabawek edukacyjnych dla niewidomego dziecka, które uczą dotykiem', 'Jak w szkole dla niewidomych wspierać naukę liter i Braille''a w formie zabawy?']::text[], false, true, null, null, null, true),
  ('hop-hop-mobilny-plac-zabaw', 'Hop hop - mobilny plac zabaw', 'dla-dzieci-mlodziezy-i-rodziny', 'Inkubator Dostępności', true, 'Zestaw lekkich mebli-zabawek, z których dzieci budują tunele, ścieżki sensoryczne i tory przeszkód, plus zbiór scenariuszy ćwiczeń do domowej rehabilitacji z poradami dla opiekunów. Działa w domu i na dworze.', 'Sprawność ruchowa dzieci maleje, rosną trudności psychoruchowe, a brakuje codziennej, łatwo dostępnej terapii w wieku przedszkolnym.', array['dzieci przedszkolne i wczesnoszkolne z niepełnosprawnością ruchową', 'dzieci z zaburzeniami napięcia mięśniowego', 'dzieci z zaburzeniami integracji sensorycznej']::text[], array['fizjoterapeuta', 'terapeuta SI', 'przedszkole', 'rodzice', 'NGO']::text[], 'Dzieci, rodzice i terapeuci ocenili zestaw dobrze: mały, a pozwala na wiele ćwiczeń, łatwo łączyć elementy i bawić się grupowo.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/HOP_HOP_MOBILNY_PLAC_ZABAW.pdf","film":"https://www.youtube.com/watch?v=kE9lpr4OJPQ","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/hophop.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,hop-hop-mobilny-plac-zabaw', array['plac zabaw', 'rehabilitacja domowa', 'integracja sensoryczna', 'sprawność ruchowa', 'tor przeszkód', 'ćwiczenia dla dzieci', 'przedszkolak', 'napięcie mięśniowe', 'terapia przez zabawę', 'meblozabawki', 'niepełnosprawność ruchowa', 'fizjoterapia dziecięca']::text[], array['Dziecko ma obniżone napięcie mięśniowe, jak prowadzić codzienne ćwiczenia w domu w formie zabawy?', 'Szukamy pomocy do terapii integracji sensorycznej dla przedszkolaków z niepełnosprawnością ruchową']::text[], false, true, null, null, null, true),
  ('mobilny-pomocnik-dydaktyczno-sensoryczny-dla-uczniowstudentow-ze-spektrum-autyzmu', 'Mobilny pomocnik dydaktyczno-sensoryczny dla uczniów/studentów ze spektrum autyzmu', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Rozkładana przesłona-teczka z narzędziami ułatwiającymi naukę osobom z autyzmem: czasomierz wizualny, karty komunikatów typu „potrzebuję przerwy”, zakładka do czytania, obciążony długopis. Uzupełnia ją zestaw sensoryczny (koc, słuchawki, gumowa podkładka).', 'Osoby w spektrum autyzmu mają trudności w nauce w szkole i na uczelni, co obniża ich oceny.', array['dzieci i młodzież z autyzmem', 'studenci z autyzmem', 'uczniowie z orzeczeniem o kształceniu specjalnym']::text[], array['szkoła', 'uczelnia', 'nauczyciel', 'terapeuta', 'rodzice', 'NGO']::text[], 'Usprawnił naukę osób z ASD, co przełożyło się na lepsze oceny; użytkownicy docenili dopasowanie narzędzi.', 'Fundacja ASDreamer', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/mobilnypomocnik.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,mobilny-pomocnik-dydaktyczno-sensoryczny-dla-uczniowstudentow-ze-spektrum-autyzmu', array['autyzm', 'spektrum autyzmu', 'ASD', 'neuroatypowość', 'przeciążenie sensoryczne', 'nauka w szkole', 'student z autyzmem', 'pomoce sensoryczne', 'czasomierz wizualny', 'słuchawki wyciszające', 'dostosowanie edukacji', 'trudności w nauce']::text[], array['Uczeń z autyzmem nie radzi sobie na lekcjach przez hałas i bodźce, czego może używać w klasie?', 'Jak pomóc studentowi ze spektrum autyzmu w nauce i komunikowaniu, że potrzebuje przerwy?']::text[], false, true, null, null, null, true),
  ('przewodnik-dla-osob-z-asd-moje-potrzeby-gdzie-i-jak-je-realizowac', 'Przewodnik dla osób z ASD "Moje potrzeby - gdzie i jak je realizować?"', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Obrazkowo-tekstowy przewodnik po codziennych sprawach załatwianych poza domem. Zawiera plan krok po kroku, skrypty tego, co powiedzieć, oraz symbole do komunikacji alternatywnej, dla młodzieży i dorosłych z autyzmem.', 'Osoby z ASD mają niskie kompetencje społeczne i nie wiedzą, jak się zachować i co powiedzieć w sytuacjach poza domem.', array['młodzież i dorośli z autyzmem', 'osoby z zespołem Aspergera', 'osoby z ASD umiejące czytać']::text[], array['szkoła specjalna', 'szkoła z klasami specjalnymi', 'placówka wsparcia osób z ASD', 'NGO']::text[], 'Zwiększył samodzielność, poczucie sprawczości i umiejętność decydowania u osób testujących przewodnik.', 'Fundacja ASDreamer', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/przewodnikasd.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,przewodnik-dla-osob-z-asd-moje-potrzeby-gdzie-i-jak-je-realizowac', array['autyzm', 'ASD', 'zespół Aspergera', 'samodzielność', 'kompetencje społeczne', 'skrypty społeczne', 'plan aktywności', 'AAC', 'komunikacja alternatywna', 'piktogramy', 'załatwianie spraw', 'przewodnik']::text[], array['Mój syn z autyzmem nie wie, jak zrobić zakupy czy załatwić sprawę w urzędzie, szukam materiałów krok po kroku', 'Jak uczyć dorosłą osobę z zespołem Aspergera zachowań w miejscach publicznych za pomocą piktogramów?']::text[], false, true, null, null, null, true),
  ('bez-presji-z-depresji', 'Bez presji z depresji', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Zestaw kart pracy i ćwiczeń psychoedukacyjnych dla uczniów wracających do szkoły po długiej nieobecności z powodu terapii lub leczenia psychiatrycznego. Obejmuje też rodziców, nauczycieli i klasę, by stworzyć wokół dziecka sieć wsparcia.', 'Dzieci z problemami psychicznymi mają trudność z powrotem do szkoły i życia społecznego po dłuższej nieobecności.', array['uczniowie 10-13 lat po leczeniu psychiatrycznym lub terapii', 'dzieci z depresją, lękami i kryzysami psychicznymi', 'rodzice, nauczyciele i rówieśnicy takich dzieci']::text[], array['szkoła', 'poradnia psychologiczno-pedagogiczna', 'ośrodek interwencji kryzysowej', 'szpital psychiatryczny z oddziałem dziecięcym']::text[], 'Test wykazał lepsze samopoczucie uczniów i większą pewność nauczycieli oraz rodziców we wspieraniu; potrzebne spójne działania wielu stron.', 'Instytut HR', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/bezpresji.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,bez-presji-z-depresji', array['depresja', 'depresja dziecięca', 'zdrowie psychiczne', 'powrót do szkoły', 'leczenie psychiatryczne', 'lęki', 'kryzys psychiczny', 'psychoedukacja', 'karty pracy', 'uczeń po hospitalizacji', 'nauczyciele', 'nastolatek']::text[], array['Uczennica wraca do klasy po pobycie na oddziale psychiatrycznym, jak przygotować szkołę i rówieśników?', 'Jak wspierać dziecko z depresją i lękami w powrocie do nauki po długiej nieobecności?']::text[], false, true, null, null, null, true),
  ('bez-stresu-do-sukcesu-terapia-neurologiczna-przyjazna-dziecku', 'Bez stresu do sukcesu - terapia neurologiczna przyjazna dziecku', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Model fizjoterapii neurologicznej małych dzieci łączący metodę NDT Bobath z dogoterapią i obecnością psychologa dziecięcego. Dodatkowe bodźce uspokajają dziecko na początku zajęć, dzięki czemu terapia jest szybsza i skuteczniejsza.', 'Brakuje kompleksowych terapii dla dzieci do 3 lat, które działałyby także na psychikę i zwiększały skuteczność rehabilitacji.', array['niemowlęta i dzieci od 6 miesiąca do 3 lat z niepełnosprawnością lub jej ryzykiem', 'dzieci z zaburzeniami rozwoju odmawiające ćwiczeń', 'dzieci z zaburzeniami układu nerwowego']::text[], array['placówka fizjoterapeutyczna', 'ośrodek wczesnego wspomagania rozwoju', 'oddział rehabilitacyjny', 'rodzice']::text[], 'Dziewięcioro na dziesięcioro dzieci i opiekunów potwierdziło skuteczność; fizjoterapeuta mógł dłużej pracować manualnie bez uspokajania dziecka.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/bezstresudosukcesu.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,bez-stresu-do-sukcesu-terapia-neurologiczna-przyjazna-dziecku', array['fizjoterapia', 'rehabilitacja niemowląt', 'NDT Bobath', 'dogoterapia', 'wczesne wspomaganie', 'opóźniony rozwój', 'niepełnosprawność dziecka', 'terapia neurologiczna', 'małe dziecko', 'psycholog dziecięcy', 'porażenie mózgowe', 'napięcie mięśniowe']::text[], array['Roczne dziecko płacze na rehabilitacji i nie współpracuje, jak zrobić terapię mniej stresującą?', 'Szukamy modelu łączącego fizjoterapię z dogoterapią dla małych dzieci z zaburzeniami neurologicznymi']::text[], false, true, null, null, null, true),
  ('uwaznione-rodzienstwo', 'Uważnione rodzeństwo', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Model postępowania rodziców z pozostałymi dziećmi w rodzinie, w której jest dziecko z niepełnosprawnością. Zestaw prostych narzędzi pokazuje, z czym może się mierzyć rodzeństwo, jak unikać negatywnych skutków i jak sobie radzić.', 'Brakuje kompleksowego wsparcia i standardów pomocy dla rodzin, w których rodzi się dziecko z niepełnosprawnością, zwłaszcza dla jego rodzeństwa.', array['rodzice dzieci z niepełnosprawnością', 'rodzeństwo dzieci z niepełnosprawnością']::text[], array['ośrodek wsparcia', 'poradnia psychologiczna', 'ośrodek wczesnego wspomagania rozwoju', 'NGO']::text[], 'Według twórców i testerów to skuteczna odpowiedź na brak informacji dla rodziców, szczególnie na początku drogi z niepełnosprawnością dziecka.', 'Fundacja Początek Świata', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/uwaznionerodzenstwo.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,uwaznione-rodzienstwo', array['rodzeństwo', 'rodzeństwo niepełnosprawnego dziecka', 'niepełnosprawność w rodzinie', 'wsparcie rodziców', 'zdrowe dziecko', 'zazdrość', 'rodzina', 'poradnictwo rodzinne', 'psycholog', 'rodzice niepełnosprawnych dzieci', 'relacje w rodzinie', 'wychowanie']::text[], array['Nasz starszy syn czuje się pomijany odkąd urodziła się jego niepełnosprawna siostra, jak z nim rozmawiać?', 'Szukam wsparcia dla rodzeństwa dzieci z niepełnosprawnością w naszej poradni']::text[], false, true, null, null, null, true),
  ('brzuszkole-brzuszek-zostaje-w-przedszkolu', 'Brzuszkole - brzuszek zostaje w przedszkolu', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Ilustrowany materiał edukacyjny z zaleceniami o diecie i zdrowym stylu życia dla dzieci 4-7 lat, wręczany w gabinetach lekarskich podczas bilansów zdrowia. Tekst jest dla opiekunów, a rysunki przyciągają uwagę dzieci.', 'Nadwaga i otyłość u dzieci w wieku przedszkolnym i wczesnoszkolnym oraz brak rzetelnej wiedzy rodziców o żywieniu.', array['dzieci 4-7 lat z nadwagą lub ryzykiem otyłości', 'rodzice i opiekunowie dzieci przedszkolnych']::text[], array['przychodnia', 'pediatra', 'przedszkole', 'NGO']::text[], 'Zwiększa wiedzę rodziców o zdrowym żywieniu i zainteresowanie dzieci tematem; kluczowe jest wsparcie pediatry.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/brzuszkole.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,brzuszkole-brzuszek-zostaje-w-przedszkolu', array['otyłość', 'nadwaga', 'otyłość dziecięca', 'zdrowe odżywianie', 'dieta dziecka', 'przedszkolak', 'bilans zdrowia', 'pediatra', 'profilaktyka', 'zdrowy styl życia', 'żywienie dzieci', 'materiały edukacyjne']::text[], array['Dużo dzieci w naszym przedszkolu ma nadwagę, jak edukować rodziców o zdrowym jedzeniu?', 'Lekarz rodzinny szuka ulotki dla rodziców czterolatków o diecie i otyłości']::text[], false, true, null, null, null, true),
  ('to-nie-koniec-swiata-to-poczatek-swiata', 'To nie koniec świata - to początek świata', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Spójny zestaw materiałów dla rodzin wychowujących dziecko z niepełnosprawnością: karty pracy dla rodziców i rodzeństwa, informator, podcasty oraz materiały dla terapeutów pracujących z takimi rodzinami.', 'Trudności w funkcjonowaniu rodziny, w której jedno lub więcej dzieci ma niepełnosprawność.', array['rodziny dzieci z niepełnosprawnością', 'rodzice i rodzeństwo niepełnosprawnych dzieci', 'terapeuci pracujący z rodzinami']::text[], array['NGO', 'ośrodek wsparcia', 'OPS', 'poradnia', 'terapeuta']::text[], 'Pomaga rodzicom i rodzeństwu lepiej rozumieć wyzwania opieki, a terapeutom poszerza kompetencje w pracy z rodziną.', 'Fundacja Linka', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/toniekoniecswiata.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,to-nie-koniec-swiata-to-poczatek-swiata', array['niepełnosprawność dziecka', 'rodzice', 'rodzeństwo', 'podcast', 'informator dla rodziców', 'karty pracy', 'diagnoza dziecka', 'wsparcie rodziny', 'terapeuta rodzinny', 'trudności wychowawcze', 'opieka nad dzieckiem z niepełnosprawnością', 'poradnik']::text[], array['Właśnie dowiedzieliśmy się, że nasze dziecko jest niepełnosprawne, gdzie znajdziemy materiały dla rodziców i rodzeństwa?', 'Jakie narzędzia mogą wykorzystać terapeuci do pracy z rodzinami dzieci z niepełnosprawnością?']::text[], false, true, null, null, null, true),
  ('jezykolamacz', 'Językołamacz', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Aplikacja z rozszerzoną rzeczywistością wspierająca naukę mowy po polsku u dzieci z autyzmem w wieku 3-10 lat, z instrukcją i scenariuszami zajęć do użycia w domu lub w gabinecie terapeuty.', 'Dzieci z autyzmem mają trudności w komunikacji, mały zasób słów i kłopot z wyrażaniem potrzeb wobec opiekunów i rówieśników.', array['dzieci z autyzmem 3-10 lat', 'dzieci z opóźnionym rozwojem mowy', 'niemówiące dzieci w spektrum']::text[], array['szkoła specjalna', 'szkoła integracyjna', 'logopeda', 'pedagog', 'placówka terapeutyczna', 'rodzice']::text[], 'Rodzice testujący w domu oraz nauczyciele i terapeuci ocenili aplikację wysoko; telefon lub tablet ułatwia dotarcie do dzieci.', 'Stowarzyszenie Edukacja Praktyczna TKK', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/jezykolamacz.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,jezykolamacz', array['autyzm', 'mowa', 'rozwój mowy', 'niemówiące dziecko', 'aplikacja', 'rozszerzona rzeczywistość', 'AR', 'logopeda', 'komunikacja', 'słownictwo', 'tablet', 'terapia mowy']::text[], array['Mój czteroletni syn z autyzmem prawie nie mówi, czy jest aplikacja, która pomoże w nauce słów?', 'Logopeda szuka narzędzia na tablet do pracy z dziećmi ze spektrum, które mają mały zasób słownictwa']::text[], false, true, null, null, null, true),
  ('piosenki-uczestniczace', 'Piosenki uczestniczące', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Autorskie piosenki dydaktyczne z gestami i książeczkami, dopasowane do dzieci niemówiących lub z trudnościami w komunikacji. Pozwalają im aktywnie uczestniczyć w zabawach muzycznych, z których wcześniej były wykluczone.', 'Dzieci niemówiące lub z niepełną komunikacją mają ograniczony dostęp do narzędzi integracji i wspólnej edukacji.', array['dzieci 1-3 lat niemówiące', 'dzieci z trudnościami w komunikacji', 'małe dzieci z niepełnosprawnością']::text[], array['żłobek', 'przedszkole', 'poradnia specjalistyczna', 'placówka opiekuńcza', 'rodzice']::text[], 'Poprawia koncentrację, wzmacnia więzi w grupie i wspiera rozwój mowy; sprawdza się też w domu, a dzieci chętnie pokazywały gesty i śpiewały.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/piosenkiuczestniczace.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,piosenki-uczestniczace', array['piosenki', 'muzyka', 'muzykoterapia', 'niemówiące dziecko', 'opóźniony rozwój mowy', 'gesty', 'śpiewnik', 'zabawy muzyczne', 'żłobek', 'przedszkole', 'komunikacja', 'małe dzieci']::text[], array['Dziecko w żłobku jeszcze nie mówi, jak włączyć je do wspólnych zabaw muzycznych?', 'Szukam piosenek z gestami do pracy z maluchami z trudnościami w komunikacji']::text[], false, true, null, null, null, true),
  ('moj-pomocny-virtual-world', 'Mój pomocny Virtual World', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Aplikacja na telefon z ukraińskojęzycznym wirtualnym towarzyszem i czatbotem. Tłumaczy zasady życia w polskiej szkole i podaje przydatne polskie wyrażenia, żeby dzieci czuły się bezpieczniej w nowym otoczeniu.', 'Trudności adaptacyjne ukraińskich dzieci w polskiej szkole.', array['uczniowie z Ukrainy', 'dzieci ukraińskie w polskiej szkole', 'młodzież z Ukrainy']::text[], array['szkoła podstawowa', 'szkoła średnia', 'NGO', 'gmina']::text[], 'Powstała działająca aplikacja na Androida, film i opis, lecz z ograniczoną funkcjonalnością (gotowe pytania i odpowiedzi); wymaga dopracowania.', 'Stowarzyszenie Edukacja Praktyczna T.K.K.', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/virtualworld.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,moj-pomocny-virtual-world', array['Ukraina', 'uczeń z Ukrainy', 'uchodźcy', 'cudzoziemcy', 'adaptacja w szkole', 'język polski', 'czatbot', 'aplikacja', 'tłumacz', 'dzieci uchodźców', 'bariera językowa', 'szkoła']::text[], array['W naszej szkole jest kilkoro dzieci z Ukrainy, które nie znają języka i się boją, czym je wesprzeć?', 'Szukamy aplikacji po ukraińsku, która wytłumaczy uczniom zasady w polskiej szkole']::text[], false, true, null, null, null, true),
  ('mobilna-pomoc-terapeutyczna', 'Mobilna pomoc terapeutyczna', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Model pracy z rodzinami, u których podejrzewa się kryzys, zwłaszcza przemoc domową, a które nie są objęte pomocą społeczną. Pracownicy socjalni docierają do nich wspólnie ze specjalistami od poradnictwa.', 'Brak pomocy dla osób doświadczających przemocy, które nie trafiły jeszcze do długoterminowego systemu wsparcia.', array['rodziny w kryzysie', 'osoby doświadczające przemocy domowej', 'rodziny niezgłaszające potrzeby pomocy']::text[], array['OPS', 'GOPS', 'gmina wiejska', 'JST']::text[], 'Mechanizm nie został skutecznie przetestowany i nie zarekomendowano go do samodzielnego użycia; przydatne mogą być narzędzia diagnozy rodziny.', 'Gmina Proszowice (Gminny Ośrodek Pomocy Społecznej w Proszowicach)', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/mobilnapomoc.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,mobilna-pomoc-terapeutyczna', array['przemoc domowa', 'przemoc w rodzinie', 'kryzys rodziny', 'pracownik socjalny', 'praca terenowa', 'wieś', 'mała gmina', 'diagnoza rodziny', 'poradnictwo', 'pomoc mobilna', 'niebieska karta', 'wsparcie rodziny']::text[], array['Podejrzewamy przemoc w rodzinach na wsi, ale nikt nie prosi o pomoc, jak do nich dotrzeć?', 'GOPS chce wyjść do rodzin w kryzysie, które nie są w systemie pomocy społecznej']::text[], false, true, null, null, null, true),
  ('marimbaza', 'MarimBaza!', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Model warsztatów łączących muzykę z rozwojem kompetencji społecznych. Młodzież z ośrodków szkolno-wychowawczych i socjoterapii od podstaw przygotowuje wydarzenie muzyczne i własnoręcznie buduje marimby.', 'Trudno pracować z młodzieżą wykluczoną społecznie i edukacyjnie; brakuje nowoczesnych narzędzi o pośrednim działaniu terapeutycznym.', array['młodzież z ośrodków szkolno-wychowawczych', 'młodzież z ośrodków socjoterapii', 'młodzież zagrożona wykluczeniem']::text[], array['specjalny ośrodek szkolno-wychowawczy', 'ośrodek socjoterapii', 'świetlica środowiskowa', 'placówka wsparcia dziennego', 'NGO']::text[], 'Młodzież rozwinęła kompetencje społeczne i manualne, zyskała poczucie własnej wartości i wpływu na projekt.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/marimbaza.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,marimbaza', array['muzyka', 'warsztaty muzyczne', 'socjoterapia', 'młodzież', 'wykluczenie społeczne', 'kompetencje społeczne', 'poczucie własnej wartości', 'świetlica', 'marimba', 'praca w grupie', 'młodzież trudna', 'zajęcia artystyczne']::text[], array['W świetlicy środowiskowej mamy młodzież z niską samooceną, szukam warsztatów, które wzmocnią współpracę w grupie', 'Jaki pomysł na zajęcia dla wychowanków ośrodka socjoterapii rozwijające umiejętności społeczne i manualne?']::text[], false, true, null, null, null, true),
  ('nasz-wspolny-rodzinny-swiat-poznaje-ucze-reaguje', 'Nasz wspólny, rodzinny świat - poznaję, uczę, reaguję', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Model wsparcia rodzin składający się z zespołu szybkiego reagowania, który kieruje do właściwych specjalistów, oraz rodzinnej gry planszowej pomagającej poznać relacje w rodzinie i ułatwiającej diagnozę problemów.', 'Rodziny dzieci z niepełnosprawnością mają kłopot z uzyskaniem diagnozy i doświadczają zaburzonych relacji rodzinnych.', array['rodziny dzieci z niepełnosprawnością lub zaburzeniami', 'rodziny w kryzysie wychowawczym']::text[], array['ośrodek wsparcia rodziny', 'OPS', 'NGO', 'poradnia psychologiczna']::text[], 'Wspólna gra zbliżała członków rodzin, poprawiała komunikację i wzmacniała więzi.', 'Stowarzyszenie Pro Psyche Na Rzecz Zdrowia Psychicznego', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/naszwspolnyrodzinnyswiat.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,nasz-wspolny-rodzinny-swiat-poznaje-ucze-reaguje', array['gra planszowa', 'gra rodzinna', 'relacje rodzinne', 'komunikacja w rodzinie', 'diagnoza', 'niepełnosprawność dziecka', 'zespół szybkiego reagowania', 'kryzys rodziny', 'terapia rodzinna', 'zdrowie psychiczne', 'trudności wychowawcze', 'więzi']::text[], array['Rodzice niepełnosprawnego dziecka nie potrafią się dogadać i nie wiedzą, gdzie uzyskać diagnozę, od czego zacząć?', 'Szukam gry lub narzędzia, które pomoże poprawić komunikację w rodzinie w kryzysie']::text[], false, true, null, null, null, true),
  ('mpatyk', 'mPatyk', 'dla-dzieci-mlodziezy-i-rodziny', null, false, 'Edukacyjna, inkluzywna gra planszowa, w której gracze wcielają się w osoby z niepełnosprawnościami i mierzą się z ich codziennymi wyzwaniami. Zestawia perspektywę osób sprawnych i niepełnosprawnych, budując empatię i akceptację.', 'Brak zrozumienia potrzeb i trudności osób z różnymi rodzajami niepełnosprawności.', array['dzieci i młodzież', 'uczniowie szkół', 'młodzież z ośrodków wychowawczych', 'osoby z niepełnosprawnością']::text[], array['szkoła', 'młodzieżowy ośrodek wychowawczy', 'ośrodek wsparcia osób z niepełnosprawnościami', 'NGO']::text[], 'Zwiększa wiedzę o życiu z niepełnosprawnością i empatię graczy; samo czytanie zadań i szukanie rozwiązań ma wartość edukacyjną.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/mpatyk.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,mpatyk', array['gra planszowa', 'niepełnosprawność', 'empatia', 'edukacja włączająca', 'akceptacja', 'różnorodność', 'młodzież', 'uczniowie', 'zmiana perspektywy', 'lekcja wychowawcza', 'inkluzja', 'uwrażliwianie']::text[], array['Jak w klasie uwrażliwić uczniów na codzienne trudności osób niepełnosprawnych?', 'Szukamy gry edukacyjnej o niepełnosprawności dla młodzieży w ośrodku wychowawczym']::text[], false, true, null, null, null, true),
  ('czas-na-aktywnosc', 'Czas na aktywność!', 'dla-dzieci-mlodziezy-i-rodziny', 'MIIS', true, 'Internetowa platforma z uproszczonym, obrazkowo-dźwiękowym interfejsem dla dorosłych osób z zespołem Downa. Pomaga im samodzielnie wybierać wydarzenia kulturalne i towarzyskie w mieście, z pomocą wolontariuszy-asystentów.', 'Bierność społeczna osób z niepełnosprawnością intelektualną po szkole; rzadko samodzielnie korzystają z oferty miasta, bazują na zajęciach z placówek.', array['dorośli z zespołem Downa', 'osoby z niepełnosprawnością intelektualną 18-25 lat']::text[], array['ŚDS', 'WTZ', 'szkoła', 'NGO']::text[], 'Trafnie odpowiada na potrzeby grupy i pozwala samodzielnie organizować czas wolny oraz budować więzi.', 'Stowarzyszenie Rodziców i Przyjaciół Dzieci z Zespołem Downa TĘCZA w Krakowie', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/03_CzasNaAktywnosc.pdf","film":"https://www.youtube.com/watch?v=QgkpdYndqNU","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/czasnaaktywnosc.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-dzieci-mlodziezy-i-rodziny,czas-na-aktywnosc', array['zespół Downa', 'niepełnosprawność intelektualna', 'platforma internetowa', 'czas wolny', 'aktywność społeczna', 'wolontariusz', 'asystent', 'samodzielność', 'dorośli z niepełnosprawnością', 'wydarzenia kulturalne', 'bierność', 'uproszczony interfejs']::text[], array['Nasz syn z zespołem Downa po szkole siedzi w domu, jak zachęcić go do samodzielnych wyjść i zajęć?', 'Jak ŚDS lub WTZ może pomóc podopiecznym organizować czas wolny w mieście?']::text[], false, true, null, null, null, true),
  ('bajkala', 'Bajkala', 'dla-cudzoziemcow', null, false, 'Drewniana lampka LED z odtwarzaczem odtwarzającym bajki polskie, razem z książeczką i słowniczkiem po polsku oraz rosyjsku lub czeczeńsku. Ma pomóc dzieciom czeczeńskim poznawać polską kulturę i język.', 'Bariery kulturowe, językowe, prawne i psychologiczne utrudniają integrację migrantów czeczeńskich, zwłaszcza dzieci.', array['dzieci czeczeńskie w Polsce', 'dzieci migrantów', 'rodziny czeczeńskie']::text[], array['ośrodek dla cudzoziemców', 'szkoła podstawowa', 'NGO', 'biblioteka']::text[], 'Zwiększyła motywację do słuchania polskich bajek i kompetencje językowe; potrzebna większa skala i więcej treści.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/bajkala.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-cudzoziemcow,bajkala', array['Czeczeni', 'Czeczenia', 'dzieci migrantów', 'uchodźcy', 'bajki', 'nauka polskiego', 'integracja', 'język rosyjski', 'adaptacja kulturowa', 'lampka', 'książeczka', 'dziecko cudzoziemskie']::text[], array['W szkole mamy czeczeńskie dzieci, które słabo znają polski, jak je oswoić z naszą kulturą?', 'Szukam materiałów dwujęzycznych dla dzieci migrantów do nauki polskiego przez bajki']::text[], false, true, null, null, null, true),
  ('dialog-ponad-kulturami', 'Dialog ponad kulturami', 'dla-cudzoziemcow', null, false, 'Ustandaryzowany model mediacji transgranicznych w sprawach porwań rodzicielskich lub groźby porwania w parach z różnych kultur. Łączy rozwiązania prawne, psychologiczne, międzykulturowe i negocjacyjne i może być stosowany przed sądem, w trakcie i po procesie.', 'Uprowadzenia rodzicielskie i konflikty rodziców z różnych krajów o miejsce pobytu dziecka i władzę rodzicielską.', array['pary rodziców z różnych kultur w konflikcie', 'dzieci zagrożone porwaniem rodzicielskim', 'rodziny międzykulturowe']::text[], array['mediator', 'prawnik', 'ośrodek pomocy rodzinie', 'centrum praw kobiet', 'szkoła', 'NGO']::text[], 'Wysoka skuteczność; testerzy często kontynuowali mediację po projekcie, a część podjęła terapię psychologiczną.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/dialogponadkulturami.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-cudzoziemcow,dialog-ponad-kulturami', array['mediacje', 'mediacja', 'porwanie rodzicielskie', 'uprowadzenie dziecka', 'rozwód', 'małżeństwo mieszane', 'rodzina międzykulturowa', 'władza rodzicielska', 'opieka nad dzieckiem', 'konflikt rodziców', 'cudzoziemiec', 'sąd rodzinny']::text[], array['Obcokrajowiec z żoną Polką spierają się o to, gdzie ma mieszkać dziecko, i boją się, że ktoś je wywiezie za granicę', 'Szukam mediatora do konfliktu rodziców z różnych krajów o władzę rodzicielską']::text[], false, true, null, null, null, true),
  ('wortal-informacyjny', 'Wortal informacyjny', 'dla-cudzoziemcow', null, false, 'Portal w języku dari z praktycznymi informacjami o życiu w Polsce dla uchodźców z Afganistanu, podzielony na tematy jak zdrowie i edukacja, z kontekstem kulturowym. Zawiera też wskazówki dla lekarzy i urzędników, jak rozmawiać z Afgańczykami.', 'Wykluczenie uchodźców z Afganistanu przez barierę językową i kulturową, która utrudnia integrację.', array['uchodźcy z Afganistanu', 'osoby mówiące w dari', 'lekarze i urzędnicy pracujący z Afgańczykami']::text[], array['NGO', 'centrum pomocy cudzoziemcom', 'urząd', 'placówka medyczna', 'JST']::text[], 'Afgańczycy lepiej rozumieją polskie realia, a polscy specjaliści poznali afgańską kulturę, co poprawiło spotkania i integrację.', 'Fundacja HumanDoc', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/wortalinformacyjny.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-cudzoziemcow,wortal-informacyjny', array['Afganistan', 'Afgańczycy', 'uchodźcy', 'dari', 'portal informacyjny', 'integracja', 'bariera językowa', 'różnice kulturowe', 'zdrowie', 'urzędy', 'cudzoziemcy', 'tłumaczenia']::text[], array['Do naszego ośrodka zgłaszają się Afgańczycy, którzy nie znają polskiego, gdzie znajdą informacje w swoim języku?', 'Lekarze nie rozumieją kulturowych zachowań pacjentów z Afganistanu, szukamy wskazówek']::text[], false, true, null, null, null, true),
  ('dialog-ponad-kulturami-1', 'Dialog ponad kulturami', 'dla-cudzoziemcow', null, false, 'Mobilny komunikator dla uchodźców z Afganistanu ewakuowanych do Polski, po polsku i w dari, z piktogramami dla osób niepiśmiennych. Zawiera praktyczne słownictwo o zdrowiu, edukacji, pracy i sprawach urzędowych.', 'Trudność w porozumiewaniu się z uchodźcami afgańskimi, którzy przybyli do Polski po ewakuacji w 2021 roku.', array['uchodźcy z Afganistanu', 'mniejszość afgańska w Polsce', 'osoby niepiśmienne z Afganistanu']::text[], array['OPS', 'placówka medyczna', 'urząd', 'szkoła', 'instytucja kultury', 'NGO', 'centrum międzykulturowe']::text[], 'Cele zrealizowano częściowo: aplikacja pozwala na podstawową komunikację osobom piśmiennym, osobom niepiśmiennym raczej nie.', 'Fundacja Human Doc', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/dialog.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-cudzoziemcow,dialog-ponad-kulturami-1', array['Afganistan', 'Afgańczycy', 'uchodźcy', 'dari', 'aplikacja', 'komunikator', 'piktogramy', 'tłumacz', 'bariera językowa', 'niepiśmienni', 'cudzoziemcy', 'słownik']::text[], array['Jak porozumieć się z Afgańczykami w urzędzie lub przychodni, gdy nie ma tłumacza?', 'Szukamy aplikacji z piktogramami dla niepiśmiennych uchodźców mówiących w dari']::text[], false, true, null, null, null, true),
  ('health-guide-pl', 'Health Guide PL', 'dla-cudzoziemcow', null, false, 'Przewodnik po polskiej podstawowej opiece zdrowotnej po angielsku i ukraińsku, w wersji drukowanej, PDF i jako aplikacja na Androida. Zbiera rozproszone informacje o prawach pacjenta, wyborze lekarza i szczepieniach dzieci.', 'Cudzoziemcy niepolskojęzyczni mają utrudniony dostęp do publicznej opieki zdrowotnej, mimo że są w niej ubezpieczeni.', array['cudzoziemcy mieszkający legalnie w Polsce', 'uchodźcy z Ukrainy', 'pracownicy i studenci z zagranicy oraz ich dzieci']::text[], array['przychodnia', 'NGO', 'JST', 'OPS', 'centrum integracji cudzoziemców']::text[], 'Bardzo wysoka skuteczność: cudzoziemcy lepiej znają swoje prawa, kalendarz szczepień i wybór lekarza, a personel ma mniej obciążeń.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/healthguide.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-cudzoziemcow,health-guide-pl', array['opieka zdrowotna', 'lekarz', 'przychodnia', 'NFZ', 'ubezpieczenie zdrowotne', 'cudzoziemiec', 'Ukraina', 'język angielski', 'język ukraiński', 'szczepienia dzieci', 'przewodnik', 'aplikacja']::text[], array['Jak wyjaśnić Ukraińcom, jak korzystać z przychodni i wybrać lekarza pierwszego kontaktu?', 'Cudzoziemcy w naszej gminie nie wiedzą, jak się leczyć w Polsce i kiedy zaszczepić dzieci']::text[], false, true, null, null, null, true),
  ('zrozum-moja-kulture-zrozum-mnie', 'Zrozum moją kulturę, zrozum mnie', 'dla-cudzoziemcow', null, false, 'Gra integracyjna dla uchodźców, migrantów i społeczności lokalnej. Pytania o kulturę, tradycje i religię dają punkty, a gracze opowiadają o własnych doświadczeniach, co buduje wzajemne zrozumienie.', 'Wykluczenie uchodźców i bariera społeczno-kulturowa między imigrantami a mieszkańcami.', array['cudzoziemcy mieszkający i pracujący w Polsce', 'uchodźcy', 'osoby wykluczone z powodu różnic kulturowych']::text[], array['szkoła', 'uczelnia', 'dom kultury', 'NGO', 'JST']::text[], 'Rozgrywka ogranicza konflikty na tle kulturowym, zmniejsza nieufność i budzi ciekawość odmienności.', 'Stowarzyszenie Czas Przestrzeń Tożsamość', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/zrozummojakulture.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-cudzoziemcow,zrozum-moja-kulture-zrozum-mnie', array['gra integracyjna', 'integracja', 'migranci', 'uchodźcy', 'imigranci', 'różnice kulturowe', 'tradycje', 'religia', 'uprzedzenia', 'nieufność', 'warsztaty międzykulturowe', 'cudzoziemcy']::text[], array['W naszej miejscowości mieszkańcy nie ufają cudzoziemcom, jak zorganizować spotkanie integracyjne?', 'Szukam gry lub warsztatu do zbliżenia migrantów i Polaków w domu kultury']::text[], false, true, null, null, null, true),
  ('urzedowy-ambaras', 'Urzędowy ambaras', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Gra planszowa ucząca dorosłe osoby z niepełnosprawnością intelektualną załatwiania spraw w urzędzie pracy, urzędzie miasta, ośrodku pomocy rodzinie i na poczcie. Zadania odpowiadają realnym sytuacjom, np. wysłanie listu poleconego.', 'Brakuje narzędzi, dzięki którym osoby z niepełnosprawnością intelektualną nauczą się samodzielnie załatwiać proste sprawy urzędowe.', array['dorośli z niepełnosprawnością intelektualną']::text[], array['WTZ', 'ŚDS', 'NGO']::text[], 'Wzrosła motywacja graczy do nauki, chcieli grać ponownie i dobrze ocenili czytelność gry.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/pelnawokanda.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,urzedowy-ambaras', array['gra planszowa', 'urząd', 'sprawy urzędowe', 'poczta', 'urząd pracy', 'niepełnosprawność intelektualna', 'samodzielność', 'dorośli', 'WTZ', 'ŚDS', 'załatwianie spraw', 'edukacja']::text[], array['Podopieczni naszego WTZ boją się urzędów i nie wiedzą, jak wysłać list polecony, jak ich tego nauczyć?', 'Szukam gry edukacyjnej o załatwianiu spraw w urzędzie dla dorosłych z niepełnosprawnością intelektualną']::text[], false, true, null, null, null, true),
  ('stop-otylosci-innowacyjna-metoda-pracy-z-osobami-niepelnosprawnymi-intelektualnie', 'Stop otyłości - innowacyjna metoda pracy z osobami niepełnosprawnymi intelektualnie', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Metoda pracy z dorosłymi z niepełnosprawnością intelektualną i otyłością II-III stopnia. Zapewnia profesjonalne wsparcie w miejscu zamieszkania, edukację i motywowanie osoby oraz jej otoczenia do trwałej zmiany nawyków, by uniknąć DPS.', 'Wysoki odsetek otyłości II i III stopnia wśród dorosłych z niepełnosprawnością intelektualną.', array['dorośli z niepełnosprawnością intelektualną i otyłością', 'ich rodziny i opiekunowie']::text[], array['WTZ', 'ŚDS', 'DPS', 'powiat', 'NGO', 'placówka środowiskowa']::text[], 'W testach poprawiły się wyniki badań, spadła waga i nastrój; trwałość efektów zagrażają złe nawyki żywieniowe w rodzinie.', 'Powiat Wielicki', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/stopotylosci.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,stop-otylosci-innowacyjna-metoda-pracy-z-osobami-niepelnosprawnymi-intelektualnie', array['otyłość', 'nadwaga', 'odchudzanie', 'dieta', 'niepełnosprawność intelektualna', 'nawyki żywieniowe', 'zdrowy styl życia', 'wsparcie środowiskowe', 'profilaktyka', 'dorośli', 'DPS', 'redukcja wagi']::text[], array['Podopieczny naszego ŚDS z niepełnosprawnością intelektualną jest bardzo otyły, jak mu pomóc schudnąć w miejscu zamieszkania?', 'Chcemy uniknąć umieszczenia otyłej osoby z niepełnosprawnością w DPS, szukamy programu wsparcia zdrowotnego']::text[], false, true, null, null, null, true),
  ('pelna-wokanda', 'Pełna wokanda', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Gra planszowa przygotowująca osoby z niepełnosprawnością intelektualną do udziału w sprawie sądowej: rozprawa, rozmowa z prawnikiem, składanie zeznań i kroki po zakończeniu. Wyjaśnia trudne pojęcia i podpowiada, gdzie szukać informacji.', 'Brak narzędzi, dzięki którym osoby z niepełnosprawnością intelektualną zrozumieją proces sądowy i przygotują się do niego.', array['dorośli z niepełnosprawnością intelektualną']::text[], array['WTZ', 'ŚDS', 'NGO']::text[], 'Utrwala wiedzę o sądzie i rozumienie sytuacji, zwiększa pewność siebie i trenuje pamięć; pełne efekty wymagają dłuższych testów.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/pelnawokanda.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,pelna-wokanda', array['sąd', 'rozprawa', 'świadek', 'zeznania', 'prawnik', 'gra planszowa', 'niepełnosprawność intelektualna', 'dostęp do sprawiedliwości', 'poradnictwo prawne', 'dorośli', 'strach przed sądem', 'przygotowanie do rozprawy']::text[], array['Nasz podopieczny z niepełnosprawnością intelektualną ma być świadkiem w sądzie i bardzo się boi, jak go przygotować?', 'Szukam materiałów, które w prosty sposób wyjaśnią osobie z niepełnosprawnością intelektualną, jak wygląda rozprawa']::text[], false, true, null, null, null, true),
  ('pelnia-zdrowia', 'Pełnia zdrowia', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Pudełko z elektroniczną planszą i kartami dla dorosłych z lekką i umiarkowaną niepełnosprawnością intelektualną. Uczy korzystania z usług medycznych i profilaktyki, m.in. dzięki tablicom objawów i kartom profilaktyki.', 'Ograniczony dostęp osób z niepełnosprawnością intelektualną do wiedzy o korzystaniu z opieki zdrowotnej.', array['dorośli z lekką i umiarkowaną niepełnosprawnością intelektualną', 'ich opiekunowie']::text[], array['WTZ', 'ŚDS', 'NGO', 'opiekunowie']::text[], 'Uczestnicy zajęć w WTZ ocenili narzędzie bardzo dobrze i poszerzyli wiedzę; wymaga dopracowania technicznego i graficznego.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/pelniazdrowia.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,pelnia-zdrowia', array['zdrowie', 'profilaktyka', 'wizyta u lekarza', 'objawy', 'opieka medyczna', 'gra edukacyjna', 'niepełnosprawność intelektualna', 'edukacja zdrowotna', 'badania profilaktyczne', 'dorośli', 'WTZ', 'karty edukacyjne']::text[], array['Podopieczni WTZ nie wiedzą, kiedy iść do lekarza i jak opisać objawy, czym ich uczyć?', 'Szukam narzędzia o profilaktyce zdrowotnej dla osób z lekką niepełnosprawnością intelektualną']::text[], false, true, null, null, null, true),
  ('niepelnosprawnosc-szansa-na-pelnosprawnosc-w-pracy-i-zyciu', 'Niepełnosprawność szansą na pełnosprawność w pracy i życiu', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Socjoterapeutyczny model zajęć dla uczniów szkół średnich z umiarkowaną niepełnosprawnością intelektualną. Pokazuje branże, w których mogą pracować, pozwala sprawdzić się w zawodach i określić mocne oraz słabe strony, by dobrać przyszłe miejsce pracy.', 'Wykluczenie, wyuczona bezradność i brak wpływu młodzieży z niepełnosprawnością intelektualną na własną ścieżkę zawodową.', array['młodzież z umiarkowaną niepełnosprawnością intelektualną', 'uczniowie szkół średnich specjalnych', 'osoby wymagające wsparcia samodzielności w dorosłości']::text[], array['WTZ', 'ŚDS', 'ZAZ', 'szkoła specjalna', 'NGO']::text[], 'Młodzież aktywnie zdobywała doświadczenie zawodowe, wzmocniła kompetencje społeczne i poznała swoje zainteresowania oraz mocne i słabe strony.', 'Stowarzyszenie „Razem przy Specjalnym Ośrodku Szkolno-Wychowawczym w Siedlcach”', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/niepelnosprawnoscszansa.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,niepelnosprawnosc-szansa-na-pelnosprawnosc-w-pracy-i-zyciu', array['praca', 'zatrudnienie', 'aktywizacja zawodowa', 'orientacja zawodowa', 'niepełnosprawność intelektualna', 'młodzież', 'szkoła specjalna', 'rynek pracy', 'wybór zawodu', 'przygotowanie do dorosłości', 'socjoterapia', 'samodzielność']::text[], array['Uczniowie ze szkoły specjalnej kończą naukę i nie wiedzą, jaką pracę mogą wykonywać, jak im pomóc wybrać zawód?', 'Szukam programu przygotowującego młodzież z umiarkowaną niepełnosprawnością intelektualną do wejścia na rynek pracy']::text[], false, true, null, null, null, true),
  ('dostepna-polska', 'Dostępna Polska', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Komplet przewodników turystycznych w formie easy to read, dostosowanych do osób z lekką i umiarkowaną niepełnosprawnością intelektualną. Opisują po dwie trasy zwiedzania w trzech polskich miastach.', 'Osoby z niepełnosprawnością intelektualną mają ograniczony dostęp do samodzielnej turystyki, bo zwykłe przewodniki są dla nich za trudne.', array['dorośli z lekką i umiarkowaną niepełnosprawnością intelektualną', 'ich rodziny']::text[], array['jednostka pomocy społecznej', 'NGO', 'ośrodek wsparcia dorosłych z niepełnosprawnością intelektualną']::text[], 'Zwiększyły dostępność turystyczną, zachęciły do samodzielnych podróży i podniosły pewność siebie użytkowników.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/dostepnapolska.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,dostepna-polska', array['turystyka', 'przewodnik', 'easy to read', 'ETR', 'łatwy tekst', 'zwiedzanie', 'wycieczki', 'niepełnosprawność intelektualna', 'dostępność', 'samodzielne podróżowanie', 'wyjazd', 'czas wolny']::text[], array['Osoby z niepełnosprawnością intelektualną chcą samodzielnie zwiedzać miasto, ale zwykłe przewodniki są dla nich niezrozumiałe', 'Szukamy przewodnika w prostym języku na wycieczkę dla uczestników ŚDS']::text[], false, true, null, null, null, true),
  ('zalatw-to-sam', 'Załatw to sam', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Planszowa gra miejska o instytucjach publicznych, która oswaja osoby z niepełnosprawnością intelektualną z poruszaniem się po urzędach i zachęca do samodzielności. W zestawie scenariusze warsztatów i zasady prowadzenia gry.', 'Niska samodzielność osób z niepełnosprawnością intelektualną, brak wiedzy o prawach i obowiązkach oraz poczucia sprawczości.', array['dorośli z lekką i umiarkowaną niepełnosprawnością intelektualną']::text[], array['WTZ', 'ŚDS', 'NGO']::text[], 'Osiągnęła założone rezultaty; gracze uznali, że poszerzyła ich wiedzę o instytucjach i urzędach.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/zalatwtosam.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,zalatw-to-sam', array['gra miejska', 'gra planszowa', 'urzędy', 'instytucje publiczne', 'samodzielność', 'trening samodzielności', 'prawa i obowiązki', 'niepełnosprawność intelektualna', 'warsztaty', 'sprawczość', 'dorośli', 'załatwianie spraw']::text[], array['Prowadzę trening samodzielności w WTZ i szukam gry, która nauczy podopiecznych poruszania się po urzędach', 'Jak zwiększyć poczucie sprawczości i znajomość swoich praw u dorosłych z niepełnosprawnością intelektualną?']::text[], false, true, null, null, null, true),
  ('go-ahead-mow-smialo', 'Go ahead - mów śmiało!', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Aplikacja z lekcjami i quizami o sytuacjach społecznych, w której użytkownik wybiera odpowiedź i widzi reakcję rozmówcy w formie mimiki. Ma rozwijać komunikację osób z niepełnosprawnością intelektualną.', 'Trudności w komunikacji i nawiązywaniu bliższych relacji u młodzieży i dorosłych z niepełnosprawnością intelektualną.', array['młodzież z niepełnosprawnością intelektualną', 'dorośli z niepełnosprawnością intelektualną']::text[], array['WTZ', 'szkoła integracyjna', 'szkoła specjalna', 'NGO']::text[], 'Nie sprawdziło się w pełni: aplikację polubiono, ale nie zauważono wyraźnego wzrostu kompetencji; wymaga umiejętności czytania ze zrozumieniem.', 'Stowarzyszenie „Radość” w Dębicy', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/goahead.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,go-ahead-mow-smialo', array['komunikacja', 'aplikacja', 'quiz', 'relacje', 'kontakty społeczne', 'niepełnosprawność intelektualna', 'umiejętności społeczne', 'mimika', 'młodzież', 'dorośli', 'nawiązywanie znajomości', 'trening komunikacji']::text[], array['Podopieczni mają trudności w rozmowie z innymi i nawiązywaniu znajomości, szukam aplikacji do ćwiczeń komunikacji', 'Jak uczyć młodzież z niepełnosprawnością intelektualną reagowania w sytuacjach społecznych?']::text[], false, true, null, null, null, true),
  ('autyzm-i-ja', 'AuTyzm i ja', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Przewodnik dla rodziców i nauczycieli o wspieraniu przedszkolaków z autyzmem oraz internetowy dzienniczek obserwacji zachowań dziecka w domu i przedszkolu, pozwalający szybciej wychwycić zmiany.', 'Trudności dzieci z autyzmem w nawiązywaniu kontaktu i interakcji oraz ograniczony dostęp do placówek edukacyjnych.', array['dzieci przedszkolne z autyzmem', 'rodzice i opiekunowie dzieci z autyzmem', 'nauczyciele przedszkolni']::text[], array['przedszkole', 'placówka wczesnej interwencji', 'szkoła']::text[], 'Pomaga rodzicom i nauczycielom wspólnie planować rozwój dziecka, a dzienniczek ułatwia dostrzeganie drobnych zmian zachowania.', 'Uniwersytet Medyczny im. K. Marcinkowskiego w Poznaniu', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/autyzmija.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,autyzm-i-ja', array['autyzm', 'spektrum autyzmu', 'przedszkole', 'dziecko z autyzmem', 'przewodnik dla rodziców', 'dzienniczek obserwacji', 'wczesna interwencja', 'kontakt wzrokowy', 'nauczyciele przedszkolni', 'diagnoza', 'wczesne wspomaganie', 'obserwacja zachowania']::text[], array['Mamy w przedszkolu dziecko z autyzmem i szukamy poradnika dla nauczycieli oraz rodziców', 'Jak prowadzić obserwację zachowań dziecka z autyzmem w domu i w przedszkolu?']::text[], false, true, null, null, null, true),
  ('podroz-poza-domem-w-wirtualnej-rzeczywistosci', 'Podróż poza domem w wirtualnej rzeczywistości', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Aplikacja VR i metoda pracy dla uczniów z niepełnosprawnością intelektualną i zaburzeniami lękowymi. W domowych, bezpiecznych warunkach pozwala ćwiczyć wychodzenie z domu i kontakty społeczne.', 'Brakuje narzędzi terapeutycznych dla osób z niepełnosprawnością intelektualną, które boją się wychodzić z domu.', array['uczniowie z niepełnosprawnością intelektualną i lękami', 'dzieci i młodzież z autyzmem', 'dzieci bojące się wychodzenia z domu']::text[], array['terapeuta', 'pedagog', 'szkoła specjalna', 'placówka opiekuńcza', 'rodzice']::text[], 'Uzupełniła terapię dzieci z autyzmem; po treningach niektóre weszły po raz pierwszy do pociągu, na dworzec czy do hotelu.', 'Stowarzyszenie Edukacja Praktyczna TKK', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/podrozpozadomem.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,podroz-poza-domem-w-wirtualnej-rzeczywistosci', array['wirtualna rzeczywistość', 'VR', 'lęk', 'lęk przed wyjściem z domu', 'zaburzenia lękowe', 'autyzm', 'niepełnosprawność intelektualna', 'terapia', 'oswajanie bodźców', 'samodzielność', 'uczeń', 'podróżowanie']::text[], array['Syn z niepełnosprawnością intelektualną panicznie boi się wyjść z domu, czy jest terapia, którą można prowadzić w domu?', 'Szukam aplikacji do oswajania dziecka z autyzmem z dworcem, pociągiem i miejscami publicznymi']::text[], false, true, null, null, null, true),
  ('ta-sciezka-terapeutyczna-sciezka-kulturowa-dla-dzieci-i-doroslych-z-autyzmem', 'TA ścieżka. Terapeutyczna ścieżka kulturowa dla dzieci i dorosłych z autyzmem.', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Aplikacja z siecią beaconów do nawigacji wewnątrz budynków, która prowadzi osobę z autyzmem po ścieżce w instytucji, pokazuje, gdzie jest, dokąd iść i jaki krok wykonać dalej.', 'Utrudniony dostęp osób neuroatypowych do miejsc użyteczności publicznej.', array['młodzież i starsze dzieci z autyzmem', 'osoby neuroatypowe']::text[], array['NGO', 'instytucja kultury', 'organizator treningów samodzielności']::text[], 'Dało poczucie bezpieczeństwa, komfortu i niezależności w poruszaniu się po miejscu publicznym; wymaga dalszego dopracowania.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/tasciezka.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,ta-sciezka-terapeutyczna-sciezka-kulturowa-dla-dzieci-i-doroslych-z-autyzmem', array['autyzm', 'neuroatypowość', 'nawigacja w budynku', 'beacony', 'aplikacja', 'muzeum', 'instytucja kultury', 'dostępność', 'orientacja w przestrzeni', 'trening samodzielności', 'miejsca publiczne', 'komfort sensoryczny']::text[], array['Jak sprawić, żeby osoba z autyzmem nie czuła się zagubiona w muzeum lub urzędzie?', 'Szukamy aplikacji do prowadzenia osób neuroatypowych po budynku krok po kroku']::text[], false, true, null, null, null, true),
  ('osa-i-eco-puzzle', 'OSA i eco puzzle', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Kompleksowy program dla rodzin z dorosłą osobą w spektrum autyzmu. Rodziny tworzą grupę samopomocową, wspólnie działają społecznie i zarobkowo (np. produkcja ekologicznych środków higienicznych) i wspierają się psychologicznie.', 'Za mało ofert wspierających aktywność zawodową, społeczną i relacje w rodzinach z dorosłą osobą z autyzmem.', array['dorosłe osoby z autyzmem', 'rodziny i bliscy osób z autyzmem', 'rodzice dorosłych osób z autyzmem']::text[], array['NGO']::text[], 'Rodzice bardzo wysoko ocenili udział; wzrosła wiedza i szanse zarobku z eko środków higienicznych; wsparcie psychologiczne dopiero zainicjowano.', 'Fundacja Silentio (pomoc osobom z autyzmem i ich rodzinom)', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/osaiecopuzzle.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,osa-i-eco-puzzle', array['autyzm', 'dorośli z autyzmem', 'grupa samopomocowa', 'rodzice', 'aktywizacja zawodowa', 'zarobkowanie', 'ekologia', 'środki czystości', 'wsparcie rodzin', 'samopomoc', 'psycholog', 'aktywność społeczna']::text[], array['Jestem mamą dorosłego syna z autyzmem, szukam grupy wsparcia i możliwości aktywności zawodowej dla niego', 'Jak zorganizować grupę samopomocową rodzin osób dorosłych ze spektrum autyzmu?']::text[], false, true, null, null, null, true),
  ('rodzinny-system-wzajemnej-pomocy', 'Rodzinny system wzajemnej pomocy', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Model włączenia dorosłych z autyzmem w wieku 20-26 lat, którzy skończyli naukę i nie pracują. Regularne zajęcia w małych grupach w domach rodzinnych rozwijają kompetencje społeczne i zawodowe oraz odciążają opiekunów.', 'Brak oferty zajęć i przygotowania do pracy dla dorosłych z autyzmem po 24. roku życia; WTZ i ŚDS nie są dopasowane i brakuje tam miejsc.', array['dorośli z autyzmem 20-26 lat bez nauki i pracy', 'osoby z autyzmem z lekkim stopniem niepełnosprawności', 'nieformalni opiekunowie i rodzice']::text[], array['nieformalne grupy rodziców i opiekunów', 'specjaliści wspierający wdrożenie']::text[], 'Zajęcia były bardzo użyteczne dla uczestników, ale nie wszystkie udało się zrealizować w opiece naprzemiennej; trudne do skalowania.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/graozdrowie.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,rodzinny-system-wzajemnej-pomocy', array['autyzm', 'dorośli z autyzmem', 'po szkole', 'brak pracy', 'WTZ', 'ŚDS', 'włączenie społeczne', 'terapia zajęciowa', 'odciążenie opiekunów', 'opieka wytchnieniowa', 'rodzice', 'kompetencje zawodowe']::text[], array['Mój dorosły syn z autyzmem skończył szkołę, nie dostał się do WTZ i siedzi w domu, co dla niego znaleźć?', 'Jak odciążyć rodziców opiekujących się dorosłą osobą z autyzmem i dać jej zajęcia?']::text[], false, true, null, null, null, true),
  ('mix-ar-i-vr-dla-koordynacji-ruchowej', 'Mix AR i VR dla koordynacji ruchowej', 'dla-osob-z-niepelnosprawnoscia-intelektualna', null, false, 'Aplikacja AR/VR do ćwiczenia motoryki małej ręki u dzieci z autyzmem, szczególnie chwytania i kontroli palców, wraz ze scenariuszami zajęć terapeutycznych. Technologia zwiększa chęć do ćwiczeń.', 'Trudności z koordynacją wzrokowo-ruchową i brak narzędzi wzmacniających motorykę małą u dzieci z autyzmem.', array['dzieci z autyzmem', 'osoby w spektrum autyzmu']::text[], array['szkoła specjalna', 'terapeuta', 'rodzice', 'wychowawca']::text[], 'Powstały produkty o minimalnej jakości; potencjał niewykorzystany, potrzebne dalsze prace zespołu specjalistów.', 'Stowarzyszenie Edukacja Praktyczna TKK', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/mixarvr.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-intelektualna,mix-ar-i-vr-dla-koordynacji-ruchowej', array['motoryka mała', 'koordynacja ruchowa', 'autyzm', 'aplikacja', 'VR', 'AR', 'rehabilitacja ręki', 'chwyt', 'ćwiczenia', 'terapia', 'grafomotoryka', 'dziecko w spektrum']::text[], array['Dziecko z autyzmem ma słabą sprawność dłoni i nie chce ćwiczyć, może pomoże aplikacja w formie gry?', 'Szukam materiałów do terapii ręki dla dzieci ze spektrum w szkole specjalnej']::text[], false, true, null, null, null, true),
  ('uniodziez', 'Uniodzież', 'dla-osob-o-ograniczonej-mobilnosci', 'MIIS', true, 'Modułowy, nieprzemakalny płaszcz przeciwdeszczowy skrojony pod osoby na wózku; elementy można dopasować do indywidualnych potrzeb, a krój jest uniwersalny, więc nosi go także osoba sprawna.', 'Brak odzieży chroniącej przed deszczem i wiatrem, dostosowanej do osób poruszających się na wózku.', array['osoby poruszające się na wózku', 'osoby z niepełnosprawnością ruchową']::text[], array['fundacja', 'pracownia projektowa', 'producent odzieży', 'NGO']::text[], 'Test: okrycie skutecznie chroni przed pogodą i zwiększa komfort wychodzenia z domu mimo deszczu.', 'Fundacja Rozwoju Wydziału Form Przemysłowych ASP w Krakowie „Rzecz Piękna”', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/09_Model_unidziez.pdf","film":"https://www.youtube.com/watch?v=hBY1SnqLXV0&t=23s","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/uniodziez.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,uniodziez', array['wózek inwalidzki', 'płaszcz przeciwdeszczowy', 'pelerynka', 'deszcz', 'odzież dla niepełnosprawnych', 'niepełnosprawność ruchowa', 'ubranie na wózek', 'ochrona przed pogodą', 'osoba na wózku', 'moda dostępna']::text[], array['Podopieczni na wózkach marzną i moczą się w drodze do ośrodka, potrzebujemy czegoś na deszcz.', 'Moja mama jeździ na wózku i nie ma w czym wyjść na dwór, gdy pada.']::text[], false, true, null, null, null, true),
  ('zakupy-na-jednym-wozku-z-dzieckiem-z-niepelnosprawnoscia-ruchowa', 'Zakupy na jednym wózku z dzieckiem z niepełnosprawnością ruchową', 'dla-osob-o-ograniczonej-mobilnosci', 'Inkubator Dostępności', true, 'Sklepowy wózek z profilowanym siedziskiem, stabilizatorami głowy i pleców oraz pasami pięciopunktowymi, w którym rodzic może bezpiecznie wozić dziecko z niepełnosprawnością podczas zakupów.', 'Rodzice dzieci z niepełnosprawnością ruchową nie mogą zrobić zakupów bez zapewnienia osobnej opieki nad dzieckiem.', array['rodzice i opiekunowie dzieci z niepełnosprawnością ruchową', 'dzieci z mózgowym porażeniem dziecięcym']::text[], array['sklepy wielkopowierzchniowe', 'markety budowlane', 'dyskonty spożywcze']::text[], 'Rodzice, asystenci i dzieci ocenili rozwiązanie bardzo dobrze; zgłoszono drobne poprawki konstrukcyjne.', 'Fundacja Aprobata', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/LEKABEL.pdf","film":"https://www.youtube.com/watch?v=2tUImD7I-CE","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/zakupynajednymwozku.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,zakupy-na-jednym-wozku-z-dzieckiem-z-niepelnosprawnoscia-ruchowa', array['wózek sklepowy', 'zakupy z dzieckiem', 'dziecko niepełnosprawne', 'mózgowe porażenie dziecięce', 'porażenie mózgowe', 'opiekun', 'rodzic', 'supermarket', 'siedzisko dla dziecka', 'samodzielne zakupy']::text[], array['Jestem mamą dziecka z porażeniem mózgowym i nie mam jak zrobić zakupów, bo nie ma go z kim zostawić.', 'W naszym markecie nie ma wózka, do którego można bezpiecznie posadzić niepełnosprawne dziecko.']::text[], false, true, null, null, null, true),
  ('kompleksowa-pomoc-dla-osob-po-amputacji-konczyny-dolnej', 'Kompleksowa pomoc dla osób po amputacji kończyny dolnej', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Model opieki łączący fizjoterapeutę, psychologa i dietetyka: wspólny wywiad, indywidualny plan i dwa sześciodniowe turnusy rehabilitacyjne z miesięczną przerwą na pracę własną.', 'Osoby tuż po amputacji nogi nie dostają całościowego wsparcia rehabilitacyjnego, psychologicznego i żywieniowego.', array['osoby po amputacji kończyny dolnej']::text[], array['szpital', 'ośrodek rehabilitacji', 'JST', 'NGO', 'podmioty świadczące usługi opiekuńcze']::text[], 'Skraca drogę do samodzielności i lepszego chodzenia w protezie, zapobiega wykluczeniu; model można powielać.', 'Fundacja Centrum Rehabilitacji Znowu w Biegu', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/kompleksowapomocpoamputacji.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,kompleksowa-pomoc-dla-osob-po-amputacji-konczyny-dolnej', array['amputacja', 'proteza', 'po amputacji', 'rehabilitacja', 'turnus rehabilitacyjny', 'brak nogi', 'psycholog', 'dietetyk', 'fizjoterapia', 'powrót do samodzielności']::text[], array['Mieszkaniec stracił nogę i nie wiemy, gdzie szukać całościowej rehabilitacji i wsparcia psychicznego.', 'Mój tata po amputacji nogi nie radzi sobie z protezą ani psychicznie, co robić?']::text[], false, true, null, null, null, true),
  ('puzzles-ramp', 'Puzzle''s Ramp', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Gumowe klocki-puzzle, z których składa się podjazd o dowolnej wysokości; tanio i szybko likwiduje progi, krawężniki i pojedyncze schodki, na stałe lub tymczasowo.', 'Bariery architektoniczne (progi, krawężniki, stopnie) utrudniają osobom na wózkach i słabo chodzącym wejście do budynków.', array['osoby na wózku', 'osoby starsze', 'osoby chodzące o lasce lub balkoniku', 'rodzice z wózkami dziecięcymi']::text[], array['placówki użyteczności publicznej', 'firmy', 'właściciele lokali', 'JST', 'osoby prywatne']::text[], 'Testy: pozwala samodzielnie pokonać różnice wysokości rzędu kilkunastu cm; montaż prosty, bez zgód urzędowych.', 'Knowledge sp. z o.o.', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/puzzlesramp.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,puzzles-ramp', array['podjazd', 'rampa', 'próg', 'krawężnik', 'schody', 'bariery architektoniczne', 'wózek inwalidzki', 'dostępność budynku', 'wejście do sklepu', 'niskobudżetowy']::text[], array['Przed wejściem do naszego klubu seniora jest wysoki próg i osoby na wózkach nie wjadą, a nie mamy pieniędzy na remont.', 'Jak tanio zrobić podjazd przy jednym stopniu do urzędu?']::text[], false, true, null, null, null, true),
  ('chlap-pro', 'Chlap Pro', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Ochraniacz na protezę nogi chroniący przed zachlapaniem te elementy, które nie znoszą wody; powstały dwie wersje, na protezę podudzia i uda.', 'Protezy kończyn dolnych moczą się w złą pogodę, co przyspiesza zużycie ich elementów.', array['osoby z protezą uda lub podudzia']::text[], array['ośrodki wsparcia osób z niepełnosprawnościami', 'urzędy miast i gmin', 'producenci ortopedyczni']::text[], 'Testy potwierdziły przydatność i skuteczną ochronę protezy przed zamoczeniem w niepogodę.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/chlappro.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,chlap-pro', array['proteza', 'proteza nogi', 'ochraniacz', 'deszcz', 'błoto', 'kałuża', 'amputacja', 'zniszczenie protezy', 'osoba z protezą', 'wodoodporny']::text[], array['Proteza podopiecznego szybko się niszczy po deszczu, jak ją chronić?', 'Czy jest pokrowiec na protezę uda na zimę i słotę?']::text[], false, true, null, null, null, true),
  ('marina-pai', 'Marina Pai', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Zestaw do samodzielnej oceny dostępności marin i przystani: ankieta, ćwiczenia rozpoznające potrzeby, wskazówki dla zarządców i materiał edukacyjny o różnych niepełnosprawnościach.', 'Mariny i przystani są niedostosowane do osób starszych i z niepełnosprawnością, mimo że wielu żeglarzy ma 55-60 lat.', array['zarządcy i projektanci marin', 'seniorzy z trudnościami w poruszaniu się', 'osoby z niepełnosprawnością wzroku lub ruchu uprawiające żeglarstwo']::text[], array['zarządcy marin i przystani', 'JST', 'NGO', 'ośrodki sportu i rekreacji']::text[], 'Dobrze inicjuje zmiany, ale pełny efekt wymaga finansowania inwestycji i dodatkowych działań edukacyjnych.', 'Centrum Rozwoju Społeczno-Gospodarczego Przedsiębiorstwo Społeczne sp. z o.o.', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/marinapai.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,marina-pai', array['marina', 'port', 'przystań', 'żeglarstwo', 'żeglarze', 'dostępność', 'audyt dostępności', 'seniorzy', 'turystyka', 'niepełnosprawność', 'rekreacja', 'sport']::text[], array['Jak sprawdzić, czy nasza przystań żeglarska jest przyjazna dla seniorów i osób na wózkach?', 'Chcemy, żeby osoby z niepełnosprawnością mogły pływać, od czego zacząć przy porcie?']::text[], false, true, null, null, null, true),
  ('zakupy-bez-barier', 'Zakupy bez barier', 'dla-osob-o-ograniczonej-mobilnosci', 'MIIS', true, 'Dzwonek przy wejściu do sklepu przywołuje przeszkolonego pracownika, który dyskretnie pomaga klientowi: czyta etykiety, wskazuje produkty, podaje towar z wysokiej półki, prowadzi między alejkami.', 'Sklepy samoobsługowe są trudno dostępne dla osób z niepełnosprawnością i seniorów, którzy nie zrobią zakupów samodzielnie.', array['osoby niewidome', 'osoby na wózku', 'osoby z niepełnosprawnością intelektualną', 'seniorzy']::text[], array['sklepy wielkopowierzchniowe', 'urząd gminy', 'OPS', 'jednostki polityki senioralnej']::text[], 'Test wykazał wysoką skuteczność i umożliwił samodzielne zakupy, bez stygmatyzacji.', 'Gmina Kęty / Ośrodek Pomocy Społecznej w Kętach', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/02_Zakupy-bez-barier.pdf","film":"https://www.youtube.com/watch?v=v2cD6yEJQos","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/zakupybezbarier.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,zakupy-bez-barier', array['zakupy', 'sklep', 'dzwonek', 'pomoc w sklepie', 'niewidomy', 'wózek', 'senior', 'asysta', 'samodzielność', 'niepełnosprawność', 'supermarket', 'osoba starsza']::text[], array['Starsze osoby w naszej gminie nie dają rady same zrobić zakupów w markecie, jak im pomóc?', 'Niewidomy mieszkaniec boi się chodzić do sklepu, bo nikt mu nie pomoże znaleźć towaru.']::text[], false, true, null, null, null, true),
  ('nakreceni-na-aktywnosc', 'Nakręceni na aktywność', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Aplikacja webowa z mapą miejsc przyjaznych osobom z niepełnosprawnością; użytkownicy sami opisują dostępność lokali i urzędów (np. nachylenie podjazdu), tworząc wspólną mapę.', 'Brak informacji o dostępności restauracji, urzędów, muzeów i innych miejsc utrudnia planowanie wyjść i pogłębia wykluczenie.', array['osoby z niepełnosprawnością ruchową', 'opiekunowie i rodziny osób z niepełnosprawnością']::text[], array['NGO', 'ośrodki wspierające osoby z niepełnosprawnościami', 'JST']::text[], 'Testerzy ocenili aplikację pozytywnie; w trakcie testu oceniono dostępność 313 obiektów.', 'Katolickie Stowarzyszenie Osób Niepełnosprawnych i Ich Przyjaciół „KLIKA”', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/nakreceninaaktywnosc.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,nakreceni-na-aktywnosc', array['mapa dostępności', 'aplikacja', 'wózek', 'dostępne miejsca', 'restauracje', 'kawiarnie', 'urzędy', 'planowanie podróży', 'podjazd', 'niepełnosprawność', 'wykluczenie', 'wyjścia z domu']::text[], array['Nasi podopieczni na wózkach nie wiedzą, do których kawiarni i urzędów da się wjechać.', 'Czy istnieje aplikacja z oceną dostępności lokali dla osób niepełnosprawnych ruchowo?']::text[], false, true, null, null, null, true),
  ('moduly-niezaleznosci', 'Moduły niezależności', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Model dostępnej zabudowy kamperowej do aut dostawczych, z opisem technicznym komponentów i montażu; kamper przystosowany do podróży osób na wózkach oraz z dysfunkcją wzroku lub słuchu.', 'Osoby z niepełnosprawnością mają ograniczone możliwości swobodnej turystyki i podróżowania.', array['osoby na wózkach', 'osoby z niepełnosprawnością', 'seniorzy', 'osoby z czasowymi ograniczeniami zdrowotnymi', 'opiekunowie i rodziny']::text[], array['producenci kamperów i samochodów dostawczych', 'wypożyczalnie kamperów', 'biura turystyczne', 'NGO']::text[], 'Skuteczne głównie dla osób na wózkach z wyraźną niepełnosprawnością ruchu; przy innych niepełnosprawnościach i u seniorów korzyści minimalne.', 'Fundacja Polska Bez Barier', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/modulyniezaleznosci.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,moduly-niezaleznosci', array['kamper', 'samochód dostawczy', 'turystyka', 'podróże', 'wakacje', 'urlop', 'wózek inwalidzki', 'dostępny transport', 'niepełnosprawność', 'wypoczynek', 'przewóz osób z niepełnosprawnością']::text[], array['Chcemy zorganizować wyjazd wakacyjny dla osób na wózkach, ale nie ma czym ich wygodnie przewieźć i gdzie nocować.', 'Czy da się przerobić busa na kamper dostępny dla osoby niepełnosprawnej?']::text[], false, true, null, null, null, true),
  ('biustspinka', 'BiustSPINKA', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Proste, tanie urządzenie z taśmą slap, które pozwala kobiecie z ograniczoną sprawnością rąk lub ramion samodzielnie założyć, zapiąć i zdjąć biustonosz.', 'Brak pomocy ułatwiających samodzielne ubieranie się kobietom z dysfunkcją ręki.', array['kobiety z ograniczeniami ruchowymi rąk', 'kobiety po udarze lub operacji', 'kobiety po amputacji piersi', 'kobiety na wózku', 'kobiety z mózgowym porażeniem dziecięcym']::text[], array['gabinety rehabilitacyjne', 'szpitale', 'przychodnie', 'szkoły', 'sklepy z bielizną', 'oddziały rehabilitacyjne']::text[], 'Zaleta to prostota i pełna samodzielność, ale testy pokazały, że nie każdemu jest wygodne i wymaga precyzji.', 'Karpatia sp. z o.o.', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/biustspinka.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,biustspinka', array['biustonosz', 'bielizna', 'ubieranie się', 'samodzielne ubieranie', 'sprawność ręki', 'jedna ręka', 'po udarze', 'niedowład ręki', 'samodzielność', 'pomoc w ubieraniu', 'kobiety', 'rehabilitacja']::text[], array['Pacjentka po udarze nie może sama założyć stanika, jest jakieś proste urządzenie?', 'Szukam pomocy dla kobiety z niesprawną ręką, żeby sama się ubierała.']::text[], false, true, null, null, null, true),
  ('szablony-piekna', 'Szablony piękna', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Szablony krojów i tabele rozmiarów estetycznej bielizny adaptacyjnej (majtki, biustonosze) dla kobiet na wózkach, z wygodnymi zapięciami, chłonnymi wkładkami i miękkimi dzianinami.', 'Kobiety z niepełnosprawnością ruchową nie mają dostępu do ładnej bielizny, która jest przy tym funkcjonalna.', array['kobiety poruszające się na wózku', 'kobiety z niedowładem lub przykurczami kończyn']::text[], array['NGO', 'sklepy z odzieżą i bielizną', 'firmy bieliźniarskie', 'ośrodki rehabilitacji']::text[], 'U testerek zaobserwowano wszystkie zakładane efekty; wzrósł komfort i poczucie wygody, bielizna była szyta indywidualnie.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/szablonypiekna.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,szablony-piekna', array['bielizna adaptacyjna', 'bielizna dla niepełnosprawnych', 'majtki', 'biustonosz', 'wózek inwalidzki', 'niedowład', 'przykurcze', 'moda', 'odzież adaptacyjna', 'kobiety', 'zapięcia', 'samodzielne ubieranie']::text[], array['Nasze podopieczne na wózkach nie mogą kupić ładnej bielizny, którą da się samodzielnie założyć.', 'Gdzie znaleźć wzory na bieliznę dla kobiety z niedowładem rąk?']::text[], false, true, null, null, null, true),
  ('ev-modul-do-wozkow-inwalidzkich', 'EV moduł do wózków inwalidzkich', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Prototyp elektrycznego modułu dwukołowego, który dołącza się do wózka inwalidzkiego i zwiększa jego stabilność na podjazdach i chodnikach, powiększając gabaryty najwyżej o 10 procent.', 'Trudno samodzielnie poruszać się na wózku, zwłaszcza pod górę.', array['osoby poruszające się na wózku inwalidzkim']::text[], array['producenci wózków inwalidzkich', 'szpitale', 'ośrodki rehabilitacyjne']::text[], 'Użytkownicy potwierdzili, że po montażu łatwiej im jeździć po chodnikach i pod wzniesienia.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/evmodul.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,ev-modul-do-wozkow-inwalidzkich', array['wózek inwalidzki', 'napęd elektryczny', 'wózek elektryczny', 'jazda pod górę', 'podjazd', 'chodnik', 'stabilność', 'samodzielne poruszanie się', 'przystawka do wózka', 'niepełnosprawność ruchowa']::text[], array['Podopieczny nie ma siły sam wjechać wózkiem pod górę, czy można dołożyć napęd elektryczny?', 'Szukamy tańszego sposobu na zelektryfikowanie zwykłego wózka inwalidzkiego.']::text[], false, true, null, null, null, true),
  ('dostepny-stol-targowy', 'Dostępny stół targowy', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Stół targowy w czterech wariantach, z nachylonym blatem, uchwytami na torbę i laskę, tackami na monety, poręczami, dodatkowymi półkami i siedziskiem, wygodny dla seniorów i osób z niepełnosprawnością.', 'Osoby starsze i z niepełnosprawnością mają trudności z codziennymi zakupami na targowisku.', array['seniorzy', 'osoby na wózku', 'osoby o kulach lub z balkonikiem', 'osoby z zaburzeniami równowagi', 'osoby ze słabszą motoryką dłoni']::text[], array['zarządcy targowisk', 'urzędy gmin', 'jednostki edukacyjne i kulturalne']::text[], 'Wyraźnie ułatwia zakupy na targu, lecz barierą pozostaje dojazd na targowisko i brak instruktażu.', 'Gmina Miasta Dębica', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/dostepnystol.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,dostepny-stol-targowy', array['targowisko', 'bazar', 'zakupy', 'stoisko', 'senior', 'kule', 'balkonik', 'wózek', 'dostępność', 'niepełnosprawność', 'rynek', 'handel']::text[], array['Seniorzy z naszej gminy mają trudność z zakupami na targu, bo stragany są za wysokie i bez miejsca na laskę.', 'Jak przystosować targowisko dla osób na wózkach i o kulach?']::text[], false, true, null, null, null, true),
  ('cloudleg', 'Cloudleg', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Metoda wykonania realistycznie wyglądających kosmetycznych nóg dla osób na wózku po amputacji obu nóg powyżej kolan lub bez nóg od urodzenia; przycina się je do długości i mocuje elastycznymi szortami.', 'Dyskomfort wizerunkowy osób bez nóg, które nie mogą lub nie chcą używać protez funkcjonalnych.', array['osoby po amputacji nóg powyżej kolan', 'osoby bez nóg od urodzenia', 'osoby na wózku, które niedawno straciły nogi']::text[], array['placówki rehabilitacyjne', 'szpitale', 'NGO', 'producenci protez']::text[], 'Użyteczność oceniona wysoko, odpowiada potrzebom grupy; ryzykiem jest nieufność wobec zakupu protezy online.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/cloudleg.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,cloudleg', array['proteza kosmetyczna', 'sztuczne nogi', 'amputacja', 'brak nóg', 'wózek', 'wizerunek', 'akceptacja siebie', 'poczucie własnej wartości', 'po amputacji', 'proteza estetyczna']::text[], array['Mężczyzna po amputacji obu nóg nie wstydzi się wózka, ale chce wyglądać naturalnie w ubraniu, co mu polecić?', 'Młoda osoba po utracie nóg ma problem z akceptacją swojego wyglądu.']::text[], false, true, null, null, null, true),
  ('lekki-wozek-aktywny', 'Lekki wózek aktywny', 'dla-osob-o-ograniczonej-mobilnosci', null, false, null, 'Brak niedrogich, lekkich i zwrotnych wózków aktywnych, które są potrzebne do życia społecznego i zawodowego.', array['osoby z niepełnosprawnością ruchową lub neurologiczną używające wózka aktywnego']::text[], array['producenci sprzętu (np. rowerów, sprzętu sportowego)']::text[], 'Powstał częściowo działający prototyp, pomysł potwierdzono, ale potrzeba dalszych inwestycji i testów.', 'Fundacja Centrum Inicjatyw Sportowych', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/lekkiwozekaktywny.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,lekki-wozek-aktywny', array['wózek aktywny', 'lekki wózek', 'wózek inwalidzki', 'tani wózek', 'zwrotność', 'aktywność', 'niepełnosprawność ruchowa', 'sprzęt rehabilitacyjny', 'praca', 'życie społeczne']::text[], array['Klient potrzebuje lekkiego, zwrotnego wózka, ale nie stać go na drogi sprzęt.', 'Gdzie szukać tanich wózków aktywnych dla młodych osób z niepełnosprawnością?']::text[], false, true, null, null, null, true),
  ('wozek-szermierczy', 'Wózek szermierczy', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Lekki wózek sportowy z kompozytów i stopów aluminium do szermierki na wózkach, tańszy od obecnych na rynku, możliwy do obsługi samodzielnie przez zawodnika.', 'Brak taniego, lekkiego i prostego w obsłudze sprzętu do uprawiania szermierki na wózkach.', array['zawodnicy i zawodniczki szermierki na wózkach', 'amatorzy sportu na wózkach']::text[], array['kluby sportowe', 'organizacje sportowe i treningowe dla osób na wózkach', 'NGO']::text[], 'Prototyp spełnia większość założeń, ale nie jest jeszcze dojrzały na rekomendację; powstał razem z platformą szermierczą.', 'Fundacja Centrum Inicjatyw Sportowych', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/wozekszermierczy.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,wozek-szermierczy', array['szermierka', 'sport na wózkach', 'wózek sportowy', 'niepełnosprawni sportowcy', 'paraszermierka', 'klub sportowy', 'sprzęt sportowy', 'wózek inwalidzki', 'trening', 'zawody', 'sport']::text[], array['Nasz klub chce uruchomić szermierkę dla osób na wózkach, ale sprzęt jest za drogi.', 'Jak zorganizować sport dla osób niepełnosprawnych ruchowo przy małym budżecie?']::text[], false, true, null, null, null, true),
  ('dostepna-szermierka', 'Dostępna szermierka', 'dla-osob-o-ograniczonej-mobilnosci', null, false, 'Lekka, łatwa w transporcie platforma szermiercza, na której zawodnik na wózku sam mocuje wózek, zmienia pozycję i ustawia dystans, dzięki niezawodnemu systemowi mocowań.', 'Sprzęt do szermierki na wózkach jest przestarzały, ciężki, drogi w obsłudze i wymaga pomocy osób trzecich.', array['zawodnicy i zawodniczki szermierki na wózkach', 'amatorzy i zawodowcy']::text[], array['kluby sportowe', 'organizacje organizujące treningi i zawody', 'NGO']::text[], 'Prototyp spełnia większość założeń, lecz pełnej samoobsługi nie osiągnięto; potrzebny dalszy rozwój.', 'Fundacja Centrum Inicjatyw Sportowych', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/dostepnaszermierka.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,dostepna-szermierka', array['szermierka', 'sport na wózkach', 'platforma szermiercza', 'paraszermierka', 'niepełnosprawni sportowcy', 'klub sportowy', 'mocowanie wózka', 'trening', 'zawody', 'sport', 'samodzielność zawodnika']::text[], array['Chcemy założyć sekcję szermierki dla osób na wózkach, ale nie wiemy, jaki sprzęt kupić.', 'Zawodnicy na wózkach potrzebują pomocy przy każdym treningu, czy da się to usprawnić?']::text[], false, true, null, null, null, true),
  ('innotextil', 'Innotextil', 'dla-osob-o-ograniczonej-mobilnosci', 'MIIS', true, 'Sportowe legginsy z czujnikami i aplikacją, które dyskretnie monitorują ruch i na bieżąco podpowiadają, kiedy poprawić chód, wspierając samodzielną rehabilitację w domu.', 'Seniorzy i osoby po urazach kolan mają utrudniony dostęp do fizjoterapeuty i trudno im utrzymać efekty rehabilitacji.', array['seniorzy', 'osoby z ograniczeniami narządu ruchu', 'osoby po urazach kolan']::text[], array['firmy odzieżowe', 'placówki rehabilitacji seniorów', 'placówki medyczne']::text[], 'Pozwala w domu stale kontrolować poprawność ćwiczeń i chodu oraz podtrzymywać efekty rehabilitacji.', 'Akademia Sztuk Pięknych w Krakowie, Wydział Form Przemysłowych', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/06_Model_Innotextil-1.pdf","film":"https://www.youtube.com/watch?v=ScqdHaNxYa8","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/innotextil.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-o-ograniczonej-mobilnosci,innotextil', array['rehabilitacja domowa', 'chód', 'korekta chodu', 'seniorzy', 'kolano', 'uraz kolana', 'fizjoterapia', 'inteligentna odzież', 'aplikacja', 'legginsy', 'ćwiczenia w domu', 'brak fizjoterapeuty']::text[], array['Seniorzy z naszej gminy nie mają dostępu do fizjoterapeuty i przestają ćwiczyć po zabiegach.', 'Jak pomóc osobie po urazie kolana ćwiczyć poprawnie w domu?']::text[], false, true, null, null, null, true),
  ('straznik', 'Strażnik', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'Inkubator Dostępności', true, 'Aplikacja na telefon rozpoznająca dźwięk alarmów (np. czujnik czadu, alarm pożarowy) i ostrzegająca osobę niesłyszącą wibracją, latarką lub telefonem pod wskazany numer, z historią zdarzeń.', 'Osoby głuche i niedosłyszące nie słyszą sygnałów alarmowych i są narażone na niebezpieczeństwo.', array['osoby głuche', 'osoby niedosłyszące', 'osoby głuchoniewidome']::text[], array['hotele', 'pensjonaty', 'akademiki', 'osoby prywatne']::text[], 'Aplikacja skutecznie wykrywa sygnał alarmowy i powiadamia użytkownika w dostępny dla niego sposób, także budząc go.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Straznik.pdf","film":"https://www.youtube.com/watch?v=zYVr0zMAqWE","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/straznik.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,straznik', array['głuchota', 'niesłyszący', 'niedosłyszący', 'alarm pożarowy', 'czujnik czadu', 'tlenek węgla', 'bezpieczeństwo', 'aplikacja', 'wibracje', 'powiadomienia', 'hotel', 'bezpieczeństwo w domu']::text[], array['Głucha lokatorka nie usłyszy alarmu przeciwpożarowego ani czujnika czadu, jak ją zabezpieczyć?', 'Nasz hotel chce zadbać o bezpieczeństwo gości niesłyszących w nocy.']::text[], false, true, null, null, null, true),
  ('wsparcie-imprez-masowych-dla-osob-z-niepelnosprawnoscia-wzroku', 'Wsparcie imprez masowych dla osób z niepełnosprawnością wzroku', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'Inkubator Dostępności', true, 'Modułowe, mobilne maty naprowadzające z liniami prowadzącymi, polami uwagi, kontrastem i najazdami dla wózków, plus poradnik dla organizatorów, jak przygotować dostępne wydarzenie.', 'Osoby z dysfunkcją wzroku mają utrudniony dostęp do koncertów, festiwali i innych wydarzeń masowych.', array['osoby niewidome i niedowidzące', 'osoby na wózkach']::text[], array['organizatorzy imprez i koncertów', 'firmy eventowe', 'jednostki kultury', 'teatry', 'uczelnie', 'biura festiwalowe']::text[], 'Testy: duży potencjał, maty sprawdzają się w plenerze i w środku, na różnych podłożach, łatwo je czyścić.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/WSPARCIE_IMPREZ_MASOWYCH_DLA_OSOB_Z_NIEPENOSPRAWNOSCIA_WZROKU.pdf","film":"https://www.youtube.com/watch?v=3s2kYAWWVkM","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/wsparcieimprez.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,wsparcie-imprez-masowych-dla-osob-z-niepelnosprawnoscia-wzroku', array['niewidomi', 'niedowidzący', 'koncert', 'festiwal', 'impreza masowa', 'wydarzenie plenerowe', 'maty naprowadzające', 'ścieżka prowadząca', 'dostępność wydarzeń', 'wózek', 'kultura', 'organizator imprez']::text[], array['Organizujemy festyn gminny i chcemy, żeby osoby niewidome mogły bezpiecznie się po nim poruszać.', 'Jak przygotować plenerowy koncert dostępny dla osób niewidomych i na wózkach?']::text[], false, true, null, null, null, true),
  ('teleasystent', 'Teleasystent', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'MIIS', true, 'Aplikacja na smartfon do zdalnej asysty przez wideorozmowę z nawigacją na żywo: pomoc w mieście, w kontaktach z urzędami, w domu (kuchnia, łazienka) oraz wsparcie dopasowane do potrzeb osoby.', 'Brakuje asystentów osobistych, więc osoby niewidome nie dostają wsparcia wtedy i w takim zakresie, jak potrzebują.', array['osoby niewidome', 'osoby słabowidzące']::text[], array['NGO', 'instytucje pracujące z osobami niewidomymi', 'ośrodki wsparcia']::text[], 'Test wykazał wysoką skuteczność i wzmocnienie samodzielności użytkowników i ich opiekunów.', 'Chrześcijańskie Stowarzyszenie Osób Niepełnosprawnych, Ich Rodzin i Przyjaciół „OGNISKO”', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/08_model_Teleasystent.pdf","film":"https://www.youtube.com/watch?v=8xUBVF_5CWU","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/teleasystent.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,teleasystent', array['niewidomy', 'słabowidzący', 'asystent osobisty', 'zdalna pomoc', 'wideorozmowa', 'nawigacja', 'aplikacja', 'asystencja', 'samodzielność', 'brak asystentów', 'wsparcie w domu', 'orientacja w terenie']::text[], array['Niewidomi podopieczni potrzebują pomocy poza godzinami pracy asystentów, jak to zorganizować?', 'Mamy za mało asystentów osobistych dla osób niewidomych, czy da się wspierać ich zdalnie?']::text[], false, true, null, null, null, true),
  ('hear-it', 'Hear IT', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS', true, 'Internetowa platforma w polskim języku migowym dla osób głuchych chcących wejść do IT: wideosłownik pojęć programistycznych, podręczniki (Python, Java, JavaScript), kursy e-learningowe i etiudy gamingowe.', 'Osoby głuche nie mają materiałów do samodzielnej nauki programowania w swoim języku.', array['osoby głuche zainteresowane IT', 'młodzież i dorośli głusi szukający pracy']::text[], array['szkoły policealne', 'uczelnie', 'technika i licea', 'NGO aktywizujące zawodowo osoby głuche']::text[], 'Uczestnicy poznali podstawy programowania, wcześniej uważane za zbyt trudne; to skuteczny pierwszy krok na rynku pracy.', 'Stowarzyszenie Edukacji Pozaformalnej „Meritum”', '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_IN_HearIT_v6_www.pdf","film":"https://www.youtube.com/watch?v=uDLOSoCb3E8","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/hearit.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,hear-it', array['głusi', 'niesłyszący', 'polski język migowy', 'PJM', 'programowanie', 'informatyka', 'IT', 'e-learning', 'praca', 'aktywizacja zawodowa', 'edukacja', 'kurs online']::text[], array['Głusi młodzi ludzie u nas chcą się uczyć programowania, ale nie ma kursów w języku migowym.', 'Jak pomóc osobom niesłyszącym znaleźć pracę w branży IT?']::text[], false, true, null, null, null, true),
  ('gluchy-czytelnik-w-bibliotece', 'Głuchy czytelnik w bibliotece', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS', true, 'Publikacja w polskim języku migowym, przełożona też na łatwy tekst, która tłumaczy głuchym, czym jest biblioteka, dlaczego warto czytać oraz jak wspierać dziecko w czytaniu.', 'Osoby głuche są poza społecznością czytelników i korzystających z usług bibliotek.', array['osoby głuche', 'głusi rodzice dzieci w wieku szkolnym', 'dzieci słyszące głuchych rodziców (KODA)', 'dzieci głuche i słabosłyszące']::text[], array['biblioteki publiczne', 'biblioteki szkolne', 'szkoły integracyjne']::text[], 'Ułatwia dostęp do bibliotek, wyjaśnia ich działanie i zachęca do korzystania; może poprawić jakość życia rodzin.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/ROPS_Folder_IN_GuchyCzytelnik_v4_www.pdf","film":"https://www.youtube.com/watch?v=BoAC-J1Owr4","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/gluchyczytelnik.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,gluchy-czytelnik-w-bibliotece', array['głusi', 'niesłyszący', 'biblioteka', 'czytelnictwo', 'czytanie', 'polski język migowy', 'łatwy tekst', 'rodzice', 'dzieci', 'KODA', 'edukacja', 'włączenie społeczne']::text[], array['Nasza biblioteka chce zachęcić głuchych rodziców, by przyprowadzali dzieci i czytali z nimi.', 'Głusi mieszkańcy nie korzystają z biblioteki, bo nie wiedzą, jak to działa.']::text[], false, true, null, null, null, true),
  ('blue-sea-eye', 'Blue Sea Eye', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Przenośny wskaźnik kursu i wychylenia steru połączony z aplikacją czytającą dane mową oraz sygnałami dźwiękowymi, dzięki któremu osoba niewidoma może samodzielnie sterować jachtem.', 'Brak sprzętu do nawigowania łodzią przez osoby niewidome i słabowidzące, co ogranicza ich dostęp do żeglarstwa.', array['osoby niewidome', 'osoby niedowidzące', 'żeglarze z dysfunkcją wzroku']::text[], array['kluby żeglarskie', 'organizatorzy rejsów', 'NGO wspierające osoby z dysfunkcją wzroku']::text[], 'Bardzo dobrze oceniony przez testerów; pozwala sterować w sprzyjających warunkach, wymaga dalszych ulepszeń technicznych.', 'Fundacja Zobaczyć Morze', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/blueseaeye.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,blue-sea-eye', array['niewidomi', 'niedowidzący', 'żeglarstwo', 'jacht', 'rejs', 'ster', 'kompas', 'nawigacja', 'aplikacja', 'sport', 'rekreacja', 'samodzielność']::text[], array['Chcemy zorganizować rejs, na którym niewidomi sami będą prowadzić łódź.', 'Czy istnieje urządzenie pozwalające osobie niewidomej uprawiać żeglarstwo?']::text[], false, true, null, null, null, true),
  ('osoby-niewidome-i-niedowidzace-jako-nauczyciele-jezyka-polskiego', 'Osoby niewidome i niedowidzące jako nauczyciele języka polskiego', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Model nauczania polskiego dla migrantów prowadzonego przez osoby niewidome i niedowidzące: kurs dopasowany do ich potrzeb, gotowe konspekty z nagraniami i piosenkami oraz materiały dla tutorów.', 'Osobom niewidomym trudno znaleźć pracę dopasowaną do ich możliwości, a migranci mają kłopot z nauką polskiego i adaptacją zawodową.', array['osoby niewidome i niedowidzące szukające pracy', 'migranci ze Wschodu słabo mówiący po polsku']::text[], array['szkoły językowe', 'podmioty aktywizujące zawodowo osoby z dysfunkcją wzroku', 'pracodawcy zatrudniający migrantów']::text[], 'Powstał skuteczny model; nauczyciele zyskali narzędzia i lepiej prowadzą zajęcia, a migranci uczą się skuteczniej.', 'Jobian Poland sp. z o.o.', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/osobyniewidomejakonauczyciele.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,osoby-niewidome-i-niedowidzace-jako-nauczyciele-jezyka-polskiego', array['niewidomi', 'niedowidzący', 'nauczyciel', 'język polski', 'migranci', 'uchodźcy', 'Ukraińcy', 'cudzoziemcy', 'nauka polskiego', 'aktywizacja zawodowa', 'praca dla niewidomych', 'kurs językowy']::text[], array['Niewidoma mieszkanka szuka pracy, a my mamy sporo uchodźców, którzy chcą uczyć się polskiego.', 'Jak zaktywizować zawodowo osoby niewidome i jednocześnie pomóc migrantom w nauce języka?']::text[], false, true, null, null, null, true),
  ('ngoz-nawigacja-glosowa-osob-zaleznych', 'NGOZ - nawigacja głosowa osób zależnych', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'MIIS', true, 'Głosowa nawigacja po budynku oparta na nadajnikach iBeacon, która tworzy dla osoby niewidomej mapę przestrzeni i na bieżąco mówi o położeniu, trasie i mijanych pomieszczeniach.', 'Osoby niewidome i słabowidzące mają trudność z samodzielnym i bezpiecznym poruszaniem się po urzędach, muzeach, przychodniach i innych obiektach publicznych.', array['osoby niewidome', 'osoby słabowidzące']::text[], array['urzędy', 'muzea', 'teatry', 'przychodnie', 'domy kultury', 'szkoły i uczelnie']::text[], 'Skutecznie prowadzi w nowej przestrzeni, podaje trasę oraz informacje o mijanych toaletach, recepcji czy gabinetach.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/04_model-NGOZ.pdf","film":"https://www.youtube.com/watch?v=ZiGxSX-VRfg","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/ngoz.zip","zasady_wykorzystania":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Zasady_wykorzystania_innowacji_MIIS.pdf","inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,ngoz-nawigacja-glosowa-osob-zaleznych', array['niewidomi', 'słabowidzący', 'nawigacja głosowa', 'iBeacon', 'orientacja w budynku', 'urząd', 'przychodnia', 'muzeum', 'dostępność budynku', 'aplikacja', 'samodzielne poruszanie się', 'audionawigacja']::text[], array['Niewidomi petenci gubią się w naszym urzędzie i zawsze ktoś musi ich prowadzić.', 'Jak ułatwić osobie niewidomej samodzielne dotarcie do gabinetu w przychodni?']::text[], false, true, null, null, null, true),
  ('wibraap', 'Wibraap', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'Inkubator Dostępności', true, 'Kamizelka z aplikacją zamieniająca dźwięk z mikrofonu, własnych nagrań lub instrumentu elektronicznego na wibracje odczuwalne ciałem, by osoby głuche mogły odbierać i tworzyć muzykę.', 'Osoby głuche i niedosłyszące są wykluczone z wydarzeń opartych na dźwięku i nie mają narzędzi do przeżywania oraz tworzenia muzyki.', array['osoby głuche', 'osoby niedosłyszące']::text[], array['organizatorzy koncertów i spektakli', 'filharmonie', 'teatry muzyczne', 'domy kultury', 'artyści']::text[], 'Duży potencjał, testerzy chcieli zatrzymać kamizelki; sprzęt i oprogramowanie wymagają jeszcze dopracowania.', null, '{"opis_pdf":"https://rops.krakow.pl/mpliki/IS/BIBLIOTEKA_INNOWACJI_SPOECZNYCH/Wibraap.pdf","film":"https://www.youtube.com/watch?v=nmsEAH6BbR0","pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/wibraap.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,wibraap', array['głusi', 'niesłyszący', 'niedosłyszący', 'muzyka', 'koncert', 'wibracje', 'kamizelka wibracyjna', 'odczuwanie dźwięku', 'kultura', 'taniec', 'instrument muzyczny', 'wykluczenie z wydarzeń']::text[], array['Chcemy, żeby osoby niesłyszące mogły uczestniczyć w naszych koncertach i czuć muzykę.', 'Dom kultury szuka sposobu, jak włączyć osoby głuche w zajęcia muzyczne.']::text[], false, true, null, null, null, true),
  ('my-way-to-culture', 'My way to culture', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Aplikacja z nawigacją iBeacon oferująca w muzeum trzy ścieżki zwiedzania dla osób z niepełnosprawnością wzroku, słuchu i ruchu: trasa przez windy, audiodeskrypcja, tłumaczenie na polski język migowy.', 'Osoby z niepełnosprawnością mają ograniczony dostęp do oferty kultury i nie mogą samodzielnie zwiedzać muzeów.', array['osoby niewidome', 'osoby głuche', 'osoby z niepełnosprawnością ruchową']::text[], array['muzea', 'galerie', 'placówki kultury organizujące wystawy']::text[], 'Osoby z różnymi niepełnosprawnościami zyskały szerszy dostęp do kultury, większą niezależność i lepszą samoocenę.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/mywaytoculture.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,my-way-to-culture', array['muzeum', 'kultura', 'zwiedzanie', 'audiodeskrypcja', 'polski język migowy', 'PJM', 'niewidomi', 'głusi', 'wózek', 'iBeacon', 'aplikacja', 'galeria']::text[], array['Nasze muzeum chce, by niewidomi i głusi goście mogli zwiedzać samodzielnie.', 'Jak udostępnić wystawę osobom na wózkach, niewidomym i niesłyszącym jednocześnie?']::text[], false, true, null, null, null, true),
  ('glucha-ankieta', 'Głucha ankieta', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Wtyczka do systemu ankiet LimeSurvey (kod źródłowy), dzięki której osoby głuche nagrywają kamerą telefonu lub laptopa odpowiedzi wideo w polskim języku migowym.', 'Osoby głuche nie mogą wypowiedzieć się w badaniach ankietowych, a badacze nie umieją ich uwzględnić.', array['osoby głuche używające PJM', 'badacze chcący uwzględnić głuchych respondentów']::text[], array['uczelnie', 'instytuty badawcze', 'badacze', 'NGO prowadzące badania']::text[], 'Głusi mogą odpowiadać w swoim języku na komputerze i telefonie, a wtyczka jest intuicyjna, bez szkolenia.', 'Instytut Spraw Głuchych', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/gluchaankieta.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,glucha-ankieta', array['głusi', 'niesłyszący', 'polski język migowy', 'PJM', 'ankieta', 'badania', 'konsultacje społeczne', 'LimeSurvey', 'wideo', 'wtyczka', 'diagnoza potrzeb', 'głos mieszkańców']::text[], array['Robimy badanie wśród mieszkańców i chcemy, żeby mogły w nim wziąć udział osoby głuche.', 'Jak zebrać opinie głuchych w ankiecie, skoro polski jest dla nich językiem obcym?']::text[], false, true, null, null, null, true),
  ('dostepny-wniosek-dla-ggluchych', 'Dostępny wniosek dla g/Głuchych', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Trzy przetestowane wzory wniosków urzędowych o zapewnienie dostępności (w tym tłumacza PJM), zrozumiałe dla osób głuchych, które pomagają załatwić sprawę tam, gdzie nie ma od ręki tłumacza.', 'Osoby głuche nie mają szybkiej drogi do tłumacza w urzędach i muszą wypełniać dokumenty po polsku, który jest dla nich językiem obcym.', array['osoby głuche i niedosłyszące posługujące się PJM']::text[], array['urzędy i administracja publiczna', 'jednostki prywatne', 'NGO wspierające osoby głuche']::text[], 'Testerzy uznali wnioski za przydatne, ale potrzebne jest ich upowszechnienie w urzędach i dodatkowe objaśnienia znaków.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/dostepnywniosek.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,dostepny-wniosek-dla-ggluchych', array['głusi', 'niesłyszący', 'tłumacz migowy', 'polski język migowy', 'PJM', 'urząd', 'wniosek', 'załatwianie spraw urzędowych', 'formularz', 'dostępność urzędu', 'tłumacz PJM', 'administracja']::text[], array['Głuchy mieszkaniec nie potrafi sam załatwić sprawy w urzędzie i nie wie, jak zamówić tłumacza migowego.', 'Jak w naszym urzędzie ułatwić osobom niesłyszącym zgłoszenie potrzeby tłumacza PJM?']::text[], false, true, null, null, null, true),
  ('czytamoda', 'Czytamoda', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Aplikacja dodająca audiodeskrypcję do opisów ubrań w sklepach internetowych i stacjonarnych: osoba niewidoma słyszy opis fasonu, stylu i wykonania i sama wybiera ubranie.', 'Osoby z niepełnosprawnością wzroku mają trudność z wyborem ubrań i potrzebują asysty podczas zakupów.', array['osoby niewidome', 'osoby słabowidzące']::text[], array['sklepy odzieżowe stacjonarne i internetowe', 'butiki', 'centra handlowe']::text[], 'Użytkownicy kupują ubrania bez asysty i czują się lepiej, ale na razie polecana jest sklepom z mniejszym asortymentem.', 'Fundacja Arete Centrum Edukacji Twórczej', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/czytamoda.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,czytamoda', array['niewidomi', 'słabowidzący', 'audiodeskrypcja', 'ubrania', 'moda', 'zakupy odzieżowe', 'sklep internetowy', 'opis produktu', 'aplikacja', 'samodzielne zakupy', 'odzież', 'wybór ubrań']::text[], array['Niewidoma klientka nie potrafi sama wybrać ubrań w sklepie i zawsze musi zabierać asystenta.', 'Jak sprawić, by sklep odzieżowy był dostępny dla osób niewidomych?']::text[], false, true, null, null, null, true),
  ('dostepny-transport-publiczny', 'Dostępny transport publiczny', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Aplikacja mobilna na Androida (przeniesienie „Zaraz jadę” z iOS) dla osób niewidomych i słabowidzących: mapa przystanków z opisem, położenie pojazdów, wyznaczanie trasy i obsługa TalkBack.', 'Osoby z dysfunkcją wzroku mają utrudniony dostęp do komunikacji miejskiej i informacji pasażerskiej.', array['osoby niewidome', 'osoby słabowidzące', 'pasażerowie komunikacji miejskiej']::text[], array['zarządcy transportu publicznego', 'ośrodki wspierające osoby z zaburzeniami wzroku', 'NGO']::text[], 'Testerzy ocenili ją pozytywnie, część była sceptyczna; zgłoszono poprawki (aktualność danych, komunikaty, starsze Androidy).', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/dostepnytransport.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,dostepny-transport-publiczny', array['niewidomi', 'słabowidzący', 'komunikacja miejska', 'autobus', 'tramwaj', 'przystanek', 'rozkład jazdy', 'aplikacja', 'TalkBack', 'Android', 'informacja pasażerska', 'dojazd']::text[], array['Niewidomi mieszkańcy boją się jeździć autobusem, bo nie wiedzą, kiedy przyjedzie i gdzie jest przystanek.', 'Czy jest aplikacja do komunikacji miejskiej dla osób niewidomych na Androidzie?']::text[], false, true, null, null, null, true),
  ('turystyka-gorskawspinaczka-dostepna-dla-wszystkich', 'Turystyka górska/wspinaczka dostępna dla wszystkich', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Autorska metoda wspinaczki dla osób niewidomych: trening z instruktorami na sztucznej ściance, wypracowanie komunikacji prowadzący-niewidomy, a potem sprawdzenie umiejętności w górach i na skałkach.', 'Osoby z niepełnosprawnością wzroku mają ograniczony dostęp do turystyki górskiej i wspinaczki.', array['osoby niewidome i słabowidzące']::text[], array['obiekty sportowe', 'organizatorzy turystyki górskiej', 'NGO wspierające osoby z dysfunkcją wzroku']::text[], 'Wspinaczka jest wyzwaniem; potrzebna lepsza kondycja uczestników i system łączności, bo hałas na ściance utrudniał komunikację.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/turystykagorska.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,turystyka-gorskawspinaczka-dostepna-dla-wszystkich', array['niewidomi', 'wspinaczka', 'góry', 'ścianka wspinaczkowa', 'turystyka górska', 'sport', 'rehabilitacja przez wyzwanie', 'niepełnosprawność wzroku', 'instruktor', 'skałki', 'aktywność fizyczna', 'rekreacja']::text[], array['Chcemy zabrać niewidomych podopiecznych w góry i na ściankę, ale nie wiemy, jak to bezpiecznie zorganizować.', 'Jak prowadzić zajęcia wspinaczkowe dla osób z niepełnosprawnością wzroku?']::text[], false, true, null, null, null, true),
  ('zdobadz-swoje-szczyty', 'Zdobądź swoje szczyty', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Multimedialny przewodnik po czterech szlakach górskich z audiodeskrypcją, opisujący nawierzchnię, nachylenia, przeszkody, udogodnienia, dojazd i czasy przejścia dla osób z różnymi niepełnosprawnościami.', 'Osoby z niepełnosprawnościami mają ograniczony dostęp do turystyki górskiej i brakuje informacji o dostępności szlaków.', array['osoby z niepełnosprawnością ruchową', 'osoby niewidome', 'osoby niesłyszące']::text[], array['samorządy', 'PTTK', 'parki narodowe i krajobrazowe', 'organizacje turystyczne', 'NGO osób z niepełnosprawnościami']::text[], 'Testerzy bardzo dobrze ocenili przewodnik i audiodeskrypcję, a szlaki odpowiadały ich potrzebom.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/zdobadzswojeszczyty.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,zdobadz-swoje-szczyty', array['szlak górski', 'góry', 'turystyka', 'przewodnik', 'audiodeskrypcja', 'wózek', 'niewidomi', 'niesłyszący', 'dostępny szlak', 'wycieczka', 'schronisko', 'dostępność']::text[], array['Szukamy szlaków górskich, na które da się wjechać wózkiem lub pójść z osobą niewidomą.', 'Gmina turystyczna chce opisać swoje szlaki pod kątem dostępności dla niepełnosprawnych.']::text[], false, true, null, null, null, true),
  ('spotkania-kulturlove', 'Spotkania KulturLove', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Platforma internetowa (także mobilna), która łączy osoby z niepełnosprawnością z czasowymi opiekunami na wyjścia do kina, teatru i innych miejsc kultury, gdy stali opiekunowie nie mogą.', 'Osoby z niepełnosprawnościami rzadko korzystają z kultury, bo nie mają kto z nimi pójść.', array['osoby z niepełnosprawnością, zwłaszcza znaczną', 'osoby, które mają trudność z poruszaniem się w przestrzeni publicznej', 'wolontariusze']::text[], array['instytucje kultury, sportu i rekreacji', 'organizatorzy wydarzeń kulturalnych', 'NGO']::text[], 'W teście trudno było pozyskać wolontariuszy i chętnych (pandemia, obawy o zdrowie i brak zaufania do opiekunów).', 'Fundacja Aktywnej Rehabilitacji Emerytowanych Osób Niepełnosprawnych', '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/spotkaniakulturlove.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,spotkania-kulturlove', array['kultura', 'kino', 'teatr', 'wolontariusz', 'opiekun czasowy', 'asysta', 'samotność', 'wyjście z domu', 'niepełnosprawność', 'platforma internetowa', 'wolontariat', 'brak opiekuna']::text[], array['Nasi podopieczni nie chodzą do kina czy teatru, bo nie ma kto z nimi pójść.', 'Czy można znaleźć wolontariusza, który towarzyszyłby osobie niepełnosprawnej na wydarzeniu kulturalnym?']::text[], false, true, null, null, null, true),
  ('zmysly-w-ruchu-model-choreografii-dla-osob-niewidomych', 'Zmysły w ruchu. Model choreografii dla osób niewidomych.', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Publikacja elektroniczna z nagraniami dźwiękowymi: scenariusze warsztatów i zestawy ćwiczeń taneczno-choreograficznych dla osób niewidomych i słabowidzących.', 'Osoby niewidome nie mają dostępu do tańca i terapii opartych na ruchu oraz choreografii.', array['osoby niewidome', 'osoby słabowidzące', 'młodzież z internatów dla niewidomych']::text[], array['instytucje kultury', 'placówki prowadzące zajęcia ruchowe', 'internaty i szkoły dla niewidomych', 'NGO']::text[], 'Zmienia podejście do zajęć tanecznych dla niewidomych; uczestnicy mówili o potrzebie głosu i decydowania o sobie.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/zmyslywruchu.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,zmysly-w-ruchu-model-choreografii-dla-osob-niewidomych', array['taniec', 'choreografia', 'ruch', 'niewidomi', 'słabowidzący', 'warsztaty', 'terapia tańcem', 'zajęcia ruchowe', 'internat', 'kultura', 'aktywność', 'scenariusz zajęć']::text[], array['Chcemy poprowadzić zajęcia taneczne dla młodzieży niewidomej, ale nie mamy gotowych scenariuszy.', 'Szukamy pomysłu na ruchową aktywność dla niewidomych podopiecznych.']::text[], false, true, null, null, null, true),
  ('kaski-binauralne', 'Kaski binauralne', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Wyciemniony i wygłuszony kask z nagraniami binauralnymi codziennych sytuacji, które dają wrażenie przebywania w danym miejscu i pomagają szybciej rehabilitować osoby tracące wzrok.', 'Rehabilitacja osób tracących wzrok jest zbyt mało bezpośrednia i efektywna, a brakuje narzędzi ułatwiających im codzienne funkcjonowanie.', array['osoby, które niedawno straciły wzrok', 'osoby tracące wzrok', 'osoby niedowidzące']::text[], array['organizacje rehabilitujące osoby niewidome', 'ośrodki rehabilitacji', 'NGO']::text[], 'Uczestnicy uznali nagrania za dobrą formę rewalidacji; najbardziej potrzebne są nagrania o samodzielnym poruszaniu się z laską lub psem.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/kaskibinauralne.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,kaski-binauralne', array['utrata wzroku', 'ociemnienie', 'rehabilitacja', 'rewalidacja', 'niewidomi', 'nagrania binauralne', 'biała laska', 'pies przewodnik', 'lęk przed wyjściem z domu', 'orientacja przestrzenna', 'dźwięk', 'adaptacja do niewidzenia']::text[], array['Mój sąsiad niedawno stracił wzrok i boi się wychodzić z domu, jak mu pomóc?', 'Jak przygotować osobę tracącą wzrok do samodzielnego poruszania się po mieście?']::text[], false, true, null, null, null, true),
  ('wielodziedzinowy-slownik-terminow-specjalistycznych-pl-pjm', 'Wielodziedzinowy słownik terminów specjalistycznych PL-PJM', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', null, false, 'Aplikacja mobilna będąca słownikiem polski-PJM: krótkie filmy z migowaniem specjalistycznych terminów, które wspólnie rozbudowują sami głusi, na wzór wikipedii w języku migowym.', 'Brakuje trwałego, oficjalnego zbioru znaków migowych dla terminów specjalistycznych, co utrudnia komunikację osobom głuchym.', array['osoby głuche i niedosłyszące', 'tłumacze PJM', 'głusi specjaliści w różnych dziedzinach']::text[], array['uczelnie', 'NGO osób głuchych', 'tłumacze PJM', 'stowarzyszenia']::text[], 'Pomysł dobrze trafia w potrzeby, ale jest na wczesnym etapie, zawiera kilka haseł i wymaga promocji i współtworzenia przez społeczność.', null, '{"opis_pdf":null,"film":null,"pakiet_zip":"https://rops.krakow.pl/pliki/IS/bibloteka/wielodziedzinowyslownik.zip","zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/innowacje-spoleczne/biblioteka-innowacji-spolecznych/dla-osob-z-niepelnosprawnoscia-sensoryczna,wielodziedzinowy-slownik-terminow-specjalistycznych-pl-pjm', array['głusi', 'niesłyszący', 'polski język migowy', 'PJM', 'słownik', 'język migowy', 'terminologia', 'tłumacz migowy', 'aplikacja', 'znaki migowe', 'nauka', 'komunikacja']::text[], array['Głusi studenci nie mają znaków migowych na terminy specjalistyczne i tłumacz też ich nie zna.', 'Szukamy słownika migowego do spraw zawodowych i medycznych.']::text[], false, true, null, null, null, true),
  ('innowacyjna-terapia-zajeciowa-w-domu-osoby-starszej', 'Innowacyjna terapia zajęciowa w domu osoby starszej', 'dla-seniorow', 'MIIS', false, 'Usługa terapii zajęciowej w domu seniora: ergoterapia, biblioterapia, muzykoterapia, hortiterapia, terapia kulinarna, trening pamięci oraz warsztaty zapobiegania upadkom.', 'Seniorzy, którzy nie wychodzą z domu, nie mają dostępu do zajęć aktywizujących; zostaje im opieka lub placówka.', array['osoby starsze o ograniczonej sprawności, które nie dotrą do placówki', 'seniorzy zagrożeni izolacją społeczną']::text[], array['ośrodki pomocy społecznej', 'organizacje pozarządowe']::text[], 'Półroczny test pokazał poprawę samodzielności i samopoczucia uczestników oraz mniejszą potrzebę opieki instytucjonalnej.', 'Stowarzyszenie „Być”', '{"opis_pdf":"https://cdn.innowacjespoleczne.pl/Attachments/i002/123/MODEL%20Innowacyjna%20terapia%20zaj%C4%99ciowa%20w%20domu%20osoby%20starszej.pdf","film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://cdn.innowacjespoleczne.pl/Attachments/i002/123/MODEL%20Innowacyjna%20terapia%20zaj%C4%99ciowa%20w%20domu%20osoby%20starszej.pdf', array['terapia zajęciowa', 'senior', 'w domu', 'samotność', 'izolacja', 'ergoterapia', 'muzykoterapia', 'trening pamięci', 'upadki', 'aktywizacja seniorów', 'osoba leżąca', 'opieka domowa']::text[], array['Mamy w gminie seniorów, którzy nie wychodzą z domu i nikt ich nie aktywizuje, szukamy gotowej usługi.', 'Tata rzadko wychodzi, chciałabym zajęć terapeutycznych u niego w domu.']::text[], true, true, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 oraz model innowacji na innowacjespoleczne.pl (licencja CC BY 4.0)', 'pewne', true),
  ('agrotreningi-metody-pracy-z-osobami-starszymi-na-obszarach-wiejskich', 'Agrotreningi – metody pracy z osobami starszymi na obszarach wiejskich', 'dla-seniorow', 'MIIS', false, 'Zestaw metod pracy z osobami starszymi mieszkającymi na wsi, przetestowany w MIIS. Dostępny spis podaje tylko tytuł, typ (usługa) i autora; szczegółów metod brak.', 'Seniorzy na wsi mają mniej możliwości aktywizacji i wsparcia niż w mieście (wniosek z tytułu innowacji).', array['osoby starsze mieszkające na obszarach wiejskich']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['senior', 'wieś', 'obszary wiejskie', 'aktywizacja seniorów', 'metody pracy', 'trening', 'praca z seniorami', 'gospodarstwo', 'agroterapia', 'senior na wsi']::text[], array['Prowadzimy GOPS na wsi i szukamy sposobu na aktywizację starszych mieszkańców.', 'Jak zająć seniorów w małej miejscowości, gdzie nie ma klubu seniora?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł i autor; brak opisu)', 'prawdopodobne', true),
  ('dzielnicowe-centrum-asystenckie-certyfikat-zaufanego-opiekuna-w', 'Dzielnicowe Centrum Asystenckie – Certyfikat Zaufanego Opiekuna w Lokalnej Sieci Wzajemnej Pomocy', 'dla-seniorow', 'MIIS', false, 'Dzielnicowe centrum organizujące pomoc asystencką dla osób starszych w lokalnej sieci wzajemnej pomocy; opiekunowie otrzymują Certyfikat Zaufanego Opiekuna. Szczegółów modelu spis nie podaje.', 'Seniorzy potrzebują zaufanej lokalnej pomocy asystenckiej, trudno ją znaleźć i zweryfikować (wniosek z tytułu).', array['osoby starsze potrzebujące asysty', 'lokalne społeczności dzielnic']::text[], '{}'::text[], null, 'Spółdzielnia Socjalna Merchant', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['asystent', 'opiekun', 'certyfikat', 'zaufany opiekun', 'sąsiedzka pomoc', 'wzajemna pomoc', 'sieć wsparcia', 'senior', 'dzielnica', 'usługi opiekuńcze', 'lokalna sieć']::text[], array['Chcemy zorganizować w dzielnicy sieć zaufanych opiekunów dla starszych sąsiadów.', 'Jak sprawdzić, czy opiekun do seniora jest godny zaufania i jak zbudować lokalną sieć pomocy?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł i autor; brak opisu)', 'prawdopodobne', true),
  ('asystent-osoby-starszej-nowa-forma-uslug-opiekunczych', 'Asystent osoby starszej – nowa forma usług opiekuńczych', 'dla-seniorow', 'MIIS', false, 'Model nowego zawodu: asystent wspiera seniora w organizowaniu codziennego życia, współpracuje ze specjalistami i rodziną, pomaga m.in. w kontaktach rodzinnych, w czasie hospitalizacji i w ochronie przed oszustwami.', 'Wsparcie instytucjonalne nie pokrywa wszystkich potrzeb związanych ze starzeniem się.', array['osoby starsze zależne', 'rodziny seniorów']::text[], array['samorządy lokalne', 'gminne ośrodki pomocy społecznej']::text[], 'W półrocznym teście z 9 seniorami asystent pomógł rozwiązać co najmniej jeden problem każdego uczestnika.', 'Gmina Miechów', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://innowacjespoleczne.pl/innowacja/asystent-osoby-starszej-3', array['asystent seniora', 'senior', 'usługi opiekuńcze', 'opieka', 'hospitalizacja', 'oszustwa', 'kontakty z rodziną', 'samotny senior', 'wsparcie w codzienności', 'nowy zawód', 'gops']::text[], array['Samotni seniorzy w gminie nie radzą sobie z formalnościami i szpitalem, potrzebujemy kogoś, kto ich wesprze.', 'Czy da się wprowadzić w gminie asystenta osoby starszej zamiast zwykłych usług opiekuńczych?']::text[], true, true, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 oraz karta na innowacjespoleczne.pl (CC BY 4.0)', 'pewne', true),
  ('postrewalidacja-forma-wsparcia-osob-z-gleboka-wieloraka', 'Postrewalidacja – forma wsparcia osób z głęboką, wieloraką niepełnosprawnością i ich rodzin', 'dla-osob-z-niepelnosprawnoscia-intelektualna', 'MIIS', false, 'Forma wsparcia dla osób z głęboką, wieloraką niepełnosprawnością po zakończeniu etapu rewalidacji oraz dla ich rodzin. Szczegółów modelu dostępny spis nie podaje.', 'Po rewalidacji osoby z głęboką niepełnosprawnością i rodziny mogą zostać bez ciągłego wsparcia (wniosek z nazwy).', array['osoby z głęboką, wieloraką niepełnosprawnością', 'rodziny i opiekunowie']::text[], '{}'::text[], null, 'Polskie Stowarzyszenie na rzecz Osób z Niepełnosprawnością Intelektualną – Koło w Nowym Targu', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['postrewalidacja', 'głęboka niepełnosprawność', 'niepełnosprawność sprzężona', 'dorośli z niepełnosprawnością', 'rodzina', 'opiekunowie', 'wsparcie po szkole', 'rewalidacja', 'niepełnosprawność intelektualna', 'zajęcia dzienne']::text[], array['Syn z głęboką niepełnosprawnością kończy szkołę i nie wiemy, co dalej.', 'Jak wspierać dorosłe osoby z niepełnosprawnością sprzężoną po zakończeniu rewalidacji?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł i autor; brak opisu)', 'prawdopodobne', true),
  ('oii-o-intymnosci-intelektualnych-innowacyjnie', 'OII! – O Intymności Intelektualnych Innowacyjnie', 'dla-osob-z-niepelnosprawnoscia-intelektualna', 'MIIS', false, 'Rozwiązanie z obszaru intymności osób z niepełnosprawnością intelektualną (typ: usługa). Dostępny spis podaje tylko tytuł; treść i metoda nie są opisane.', 'Osoby z niepełnosprawnością intelektualną rzadko mają wsparcie w sprawach intymności (wniosek z tytułu).', array['osoby z niepełnosprawnością intelektualną']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['intymność', 'seksualność', 'edukacja seksualna', 'niepełnosprawność intelektualna', 'relacje', 'dorośli z niepełnosprawnością', 'związki', 'granice', 'bezpieczeństwo', 'dojrzewanie']::text[], array['Prowadzimy WTZ i potrzebujemy materiałów o intymności i relacjach dla uczestników z niepełnosprawnością intelektualną.', 'Jak rozmawiać z dorosłym z niepełnosprawnością intelektualną o związkach i granicach?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł; brak opisu)', 'prawdopodobne', true),
  ('model-mobilnego-spa-dla-seniorow', 'Model mobilnego SPA dla seniorów', 'dla-seniorow', 'MIIS', false, 'Pary studentów odwiedzają seniorów w domu lub placówce i wykonują zabiegi spa (m.in. masaż klasyczny, masaż gorącymi kamieniami, masaż ziołowymi stemplami, rytuały spa) w cyklu ośmiu wizyt.', 'Seniorzy mają niezaspokojoną potrzebę odpoczynku, dbania o siebie i pielęgnacji ciała.', array['seniorzy w domach i placówkach']::text[], array['uczelnie', 'szkoły policealne', 'centra aktywności seniorów']::text[], 'Poprawił jakość życia seniorów, wzmocnił więzi międzypokoleniowe i wrażliwość studentów na potrzeby osób zależnych.', 'Akademia Wychowania Fizycznego w Krakowie', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://innowacjespoleczne.pl/innowacja/model-mobilnego-spa-dla-seniorow-2', array['spa', 'masaż', 'relaks', 'senior', 'studenci', 'wolontariat', 'międzypokoleniowość', 'pielęgnacja ciała', 'wypoczynek', 'dom pomocy społecznej', 'wizyty domowe']::text[], array['Chcemy, żeby studenci odwiedzali seniorów w DPS i robili im masaże i zabiegi relaksacyjne.', 'Jak zadbać o przyjemność i dobre samopoczucie osób starszych, które nie wychodzą z domu?']::text[], true, true, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 oraz karta na innowacjespoleczne.pl (CC BY 4.0)', 'pewne', true),
  ('wiejski-uniwersytet-miedzypokoleniowy', 'Wiejski Uniwersytet Międzypokoleniowy', 'dla-seniorow', 'MIIS', false, 'Rozwiązanie łączące pokolenia na obszarach wiejskich w formie uniwersytetu (typ: usługa). Dostępny spis podaje tylko tytuł; program i metody nie są opisane.', 'Na wsi brakuje ofert edukacyjnych i integracji międzypokoleniowej (wniosek z tytułu innowacji).', array['seniorzy i młodsi mieszkańcy obszarów wiejskich']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['uniwersytet', 'wieś', 'międzypokoleniowość', 'integracja pokoleń', 'senior', 'edukacja seniorów', 'zajęcia dla seniorów', 'młodzież', 'uniwersytet trzeciego wieku', 'aktywizacja']::text[], array['Chcemy w naszej wsi połączyć starszych i młodych w jednym programie zajęć.', 'Czy jest gotowy pomysł na wiejski uniwersytet trzeciego wieku z udziałem młodzieży?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł; brak opisu)', 'prawdopodobne', true),
  ('pomost-aplikacja-wspierajaca-niezalezne-zycie-osob-starszych', 'poMOST – aplikacja wspierająca niezależne życie osób starszych', 'dla-seniorow', 'MIIS', false, 'Aplikacja (rozwiązanie teleinformatyczne) wspierająca niezależne życie osób starszych. Dostępny spis podaje tylko tytuł i typ rozwiązania; funkcje nie są opisane.', 'Seniorzy chcą jak najdłużej żyć samodzielnie i potrzebują do tego wsparcia (wniosek z tytułu).', array['osoby starsze', 'opiekunowie seniorów']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['aplikacja', 'senior', 'niezależność', 'samodzielne życie', 'technologia', 'teleopieka', 'wsparcie w domu', 'smartfon', 'aktywność', 'bezpieczeństwo seniora']::text[], array['Szukamy aplikacji, która pomoże seniorom dłużej mieszkać samodzielnie.', 'Mama mieszka sama, czy jest aplikacja, która ułatwi jej codzienne funkcjonowanie?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł; brak opisu)', 'prawdopodobne', true),
  ('dem-game-gry-do-diagnostyki-domowej-funkcji-poznawczych-seniora', 'DEM-GAME – gry do diagnostyki domowej funkcji poznawczych seniora', 'dla-seniorow', 'MIIS', false, 'Zestaw gier (rozwiązanie teleinformatyczne) pozwalający w domu oceniać funkcje poznawcze seniora. Dostępny spis podaje tylko tytuł; zasady i wyniki testów nie są opisane.', 'Brakuje prostych narzędzi do wstępnej oceny funkcji poznawczych seniora w domu.', array['osoby starsze', 'opiekunowie i rodziny seniorów']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['demencja', 'funkcje poznawcze', 'pamięć', 'gry', 'diagnostyka', 'przesiewowa ocena', 'alzheimer', 'senior', 'badanie w domu', 'zaburzenia pamięci', 'gra komputerowa']::text[], array['Babcia zapomina różne rzeczy i chcielibyśmy sprawdzić w domu, czy to coś poważnego.', 'Czy są gry pozwalające wstępnie ocenić pamięć i myślenie u seniora?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł; brak opisu)', 'prawdopodobne', true),
  ('vipande-aplikacja-ulatwiajaca-wstepna-domowa-diagnostyke', 'Vipande – aplikacja ułatwiająca wstępną, domową diagnostykę najczęstszych chorób wieku podeszłego', 'dla-zdrowia-i-medycyny', 'MIIS', false, 'Aplikacja pomagająca we wstępnej, domowej diagnostyce najczęstszych chorób wieku podeszłego. Dostępny spis podaje tylko tytuł i typ rozwiązania.', 'Trudno szybko wstępnie ocenić objawy chorób wieku podeszłego bez wizyty u lekarza.', array['osoby starsze', 'opiekunowie seniorów']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['aplikacja', 'diagnostyka', 'choroby wieku podeszłego', 'senior', 'objawy', 'badanie w domu', 'zdrowie seniora', 'telemedycyna', 'wstępna ocena', 'profilaktyka']::text[], array['Chcemy, by starsi mieszkańcy mogli w domu wstępnie sprawdzić niepokojące objawy.', 'Jak wcześnie wychwycić choroby wieku podeszłego u osób, które rzadko chodzą do lekarza?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł; brak opisu)', 'prawdopodobne', true),
  ('acs-aplikacja-mierzaca-poziom-bolu', 'ACS – aplikacja mierząca poziom bólu', 'dla-zdrowia-i-medycyny', 'MIIS', false, 'Aplikacja do pomiaru poziomu bólu pacjenta (rozwiązanie teleinformatyczne). Dostępny spis podaje tylko tytuł i typ rozwiązania.', 'Trudno obiektywnie ocenić nasilenie bólu u pacjenta, zwłaszcza osoby zależnej.', array['pacjenci z bólem', 'osoby starsze i niesamodzielne', 'opiekunowie']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['ból', 'pomiar bólu', 'skala bólu', 'aplikacja', 'pacjent', 'ocena bólu', 'opieka', 'senior', 'choroba przewlekła', 'ból przewlekły']::text[], array['Jak ocenić, jak bardzo boli osobę, która nie potrafi tego dobrze opisać?', 'Szukamy narzędzia do monitorowania bólu u podopiecznych w domu.']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł; brak opisu)', 'prawdopodobne', true),
  ('realizacja-domowej-antybiotykoterapii-dozylnej-u-chorych-na', 'Realizacja domowej antybiotykoterapii dożylnej u chorych na mukowiscydozę', 'dla-zdrowia-i-medycyny', 'MIIS', false, 'Model prowadzenia antybiotykoterapii dożylnej w domu chorego na mukowiscydozę. Dostępny spis podaje tylko tytuł i autora; szczegóły procedury nie są opisane.', 'Dożylne leczenie antybiotykiem chorych na mukowiscydozę wymaga zwykle pobytu w szpitalu.', array['chorzy na mukowiscydozę', 'rodziny i opiekunowie']::text[], '{}'::text[], null, 'Polskie Towarzystwo Walki z Mukowiscydozą', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['mukowiscydoza', 'antybiotykoterapia', 'leczenie w domu', 'dożylne', 'choroba przewlekła', 'pacjent', 'szpital', 'opieka domowa', 'choroba rzadka', 'rodzice dzieci chorych']::text[], array['Dziecko z mukowiscydozą co jakiś czas leży w szpitalu na kroplówkach, czy można to robić w domu?', 'Szukamy sposobu na leczenie dożylne przewlekle chorych w domu.']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł i autor; brak opisu)', 'prawdopodobne', true),
  ('motyle-w-klinice-program-wsparcia-pacjentek-onkologicznych-i-ich', 'Motyle w klinice – program wsparcia pacjentek onkologicznych i ich opiekunów w szpitalu i domu', 'dla-zdrowia-i-medycyny', 'MIIS', false, 'Program wsparcia dla pacjentek onkologicznych i ich opiekunów, realizowany w szpitalu i w domu. Dostępny spis podaje tylko tytuł i autora; zakres działań nie jest opisany.', 'Pacjentki onkologiczne i ich opiekunowie potrzebują wsparcia w szpitalu i po powrocie do domu.', array['pacjentki onkologiczne', 'opiekunowie chorych']::text[], '{}'::text[], null, 'Stowarzyszenie na rzecz walki z rakiem jajnika Niebieski Motyl', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['onkologia', 'rak', 'pacjentki', 'wsparcie psychiczne', 'opiekunowie', 'szpital', 'dom', 'choroba nowotworowa', 'kobiety', 'chemioterapia']::text[], array['Kobieta z rakiem i jej mąż nie wiedzą, gdzie szukać wsparcia w szpitalu i w domu.', 'Chcemy pomagać pacjentkom onkologicznym i ich rodzinom, jakie są gotowe programy?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł i autor; brak opisu)', 'prawdopodobne', true),
  ('bazalnie-w-domu-model-pracy-domowej-z-dziecmi-gleboko', 'Bazalnie w domu – model pracy domowej z dziećmi głęboko niepełnosprawnymi', 'dla-osob-z-niepelnosprawnoscia-intelektualna', 'MIIS', false, 'Model domowej pracy z dziećmi z głęboką niepełnosprawnością oparty na stymulacji bazalnej: rodzice uczą się ułożenia dziecka i dobierania bodźców zmysłowych, które pomagają mu nawiązać kontakt z własnym ciałem i światem.', 'Rodzice nie mają materiałów edukacyjnych, a opieka domowa często sprowadza się do zaspokajania podstawowych potrzeb.', array['dzieci i osoby z głęboką niepełnosprawnością', 'rodzice i opiekunowie']::text[], array['ośrodki rehabilitacyjne', 'szkoły dla dzieci z niepełnosprawnościami', 'organizacje pozarządowe', 'rodzice']::text[], 'Pilotaż w czterech rodzinach: dzieci były bardziej aktywne, rodzice nauczyli się ułożenia dziecka i zasad stymulacji bazalnej.', 'Polskie Stowarzyszenie na rzecz Osób z Niepełnosprawnością Intelektualną – Koło w Szczawnicy', '{"opis_pdf":"https://cdn.innowacjespoleczne.pl/Attachments/i002/469/Bazalnie%20w%20domu%20-%20model%20pracy%20domowej%20z%20dzie%C4%87mi%20g%C5%82%C4%99boko%20niepe%C5%82nosprawnymi.pdf","film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://innowacjespoleczne.pl/innowacja/bazalnie-w-domu-model-pracy-domowej-z-dziecmi-gleboko-niepelnosprawnymi-2', array['stymulacja bazalna', 'głęboka niepełnosprawność', 'dziecko niepełnosprawne', 'rodzice', 'praca w domu', 'rehabilitacja', 'terapia', 'bodźce zmysłowe', 'niepełnosprawność sprzężona', 'opieka domowa']::text[], array['Mam w domu dziecko z głęboką niepełnosprawnością i nie wiem, jak z nim ćwiczyć i je stymulować.', 'Szukamy gotowego programu dla rodziców dzieci z niepełnosprawnością sprzężoną.']::text[], true, true, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 oraz karta na innowacjespoleczne.pl (CC BY 4.0)', 'pewne', true),
  ('dotknij-kultury-aktywne-uczestnictwo-osob-niewidomych-i', 'Dotknij kultury – aktywne uczestnictwo osób niewidomych i słabowidzących w interpretacji dziedzictwa', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'MIIS', false, 'Rozwiązanie, w którym osoby niewidome i słabowidzące aktywnie uczestniczą w interpretacji dziedzictwa kulturowego. Dostępny spis podaje tylko tytuł i autora; formuła zajęć nie jest opisana.', 'Osoby niewidome i słabowidzące mają ograniczony dostęp do dziedzictwa kulturowego (wniosek z tytułu).', array['osoby niewidome i słabowidzące']::text[], '{}'::text[], null, 'Stowarzyszenie Willa Decjusza', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['niewidomi', 'słabowidzący', 'kultura', 'dziedzictwo', 'muzeum', 'dotyk', 'zabytki', 'dostępność kultury', 'interpretacja', 'zwiedzanie', 'wycieczki']::text[], array['Chcemy, by osoby niewidome mogły poznawać zabytki i muzeum przez dotyk.', 'Jak zorganizować w instytucji kultury zajęcia dostępne dla słabowidzących?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł i autor; brak opisu)', 'prawdopodobne', true),
  ('przez-zabawe-do-samodzielnosci', 'Przez zabawę do samodzielności – model dla dzieci z niepełnosprawnością ze spektrum autyzmu', 'dla-dzieci-mlodziezy-i-rodziny', 'MIIS', false, 'Model ułatwiający dzieciom z niepełnosprawnością ze spektrum autyzmu zdobywanie samodzielności i niezależności poprzez zabawę. Dostępny spis podaje tylko tytuł i autora.', 'Dzieci z autyzmem potrzebują wsparcia w nabywaniu samodzielności i niezależności.', array['dzieci z autyzmem', 'rodzice i terapeuci']::text[], '{}'::text[], null, 'Stowarzyszenie Dobroczynne „Res Sacra Miser”', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['autyzm', 'spektrum autyzmu', 'dziecko', 'samodzielność', 'zabawa', 'terapia', 'niezależność', 'umiejętności życiowe', 'rodzice', 'asd']::text[], array['Syn z autyzmem jest mało samodzielny, szukamy zabaw, które uczą codziennych czynności.', 'Jaki gotowy model pracy z dziećmi z ASD rozwija samodzielność?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł i autor; brak opisu)', 'prawdopodobne', true),
  ('aparat-wspomagajacy-funkcje-konczyny-gornej-dla-osob-po-przebytym', 'Aparat wspomagający funkcję kończyny górnej dla osób po przebytym udarze mózgu z utrwaloną dysfunkcją', 'dla-osob-o-ograniczonej-mobilnosci', 'MIIS', false, 'Produkt: aparat wspomagający funkcję kończyny górnej u osób po udarze mózgu z utrwaloną dysfunkcją ręki. Dostępny spis podaje tylko tytuł; budowa i wyniki testów nie są opisane.', 'Po udarze utrwalona dysfunkcja ręki ogranicza samodzielność w codziennych czynnościach.', array['osoby po udarze mózgu', 'osoby z niedowładem kończyny górnej']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['udar', 'niedowład', 'ręka', 'kończyna górna', 'rehabilitacja', 'aparat', 'ortoza', 'pomoc ortopedyczna', 'samodzielność', 'po udarze']::text[], array['Ojciec po udarze nie włada ręką, szukamy urządzenia, które pomoże mu w codziennych czynnościach.', 'Czy jest wsparcie dla niedowładnej ręki po udarze poza standardową rehabilitacją?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł; brak opisu)', 'prawdopodobne', true),
  ('pomocnik-osoby-niewidomej-opaska-na-srodki-higieniczne', 'Pomocnik osoby niewidomej – opaska na środki higieniczne', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'MIIS', false, 'Produkt: opaska na środki higieniczne przeznaczona dla osób niewidomych. Dostępny spis podaje tylko tytuł; sposób użycia i wyniki testów nie są opisane.', 'Osoby niewidome potrzebują prostych pomocy do samodzielnej higieny (wniosek z tytułu).', array['osoby niewidome']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['niewidomi', 'higiena', 'opaska', 'samodzielność', 'pomoc dla niewidomych', 'środki higieniczne', 'gadżet', 'niepełnosprawność wzroku', 'życie codzienne', 'produkt']::text[], array['Mama jest niewidoma i ma kłopot z samodzielnym korzystaniem ze środków higienicznych.', 'Szukam prostych pomocy dla osoby niewidomej w łazience.']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł; brak opisu)', 'prawdopodobne', true),
  ('finio-fitness-osob-niepelnosprawnych-intelektualnie', 'FiNIO – fitness osób niepełnosprawnych intelektualnie', 'dla-osob-z-niepelnosprawnoscia-intelektualna', 'MIIS', false, 'Produkt: FiNIO, fitness dla osób z niepełnosprawnością intelektualną. Dostępny spis podaje tylko tytuł; program ćwiczeń i wyniki testów nie są opisane.', 'Osoby z niepełnosprawnością intelektualną mają ograniczony dostęp do aktywności fizycznej dopasowanej do ich możliwości (wniosek z tytułu).', array['osoby z niepełnosprawnością intelektualną']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/mpliki/IS/ikony_PUBLIKACJE/InnMalopolska_przewodnik_po_innowacjach.pdf', array['fitness', 'ćwiczenia', 'aktywność fizyczna', 'niepełnosprawność intelektualna', 'sport', 'zdrowie', 'otyłość', 'wtz', 'zajęcia ruchowe', 'sprawność']::text[], array['W naszym WTZ chcemy zacząć zajęcia ruchowe dostosowane do osób z niepełnosprawnością intelektualną.', 'Jak zachęcić dorosłych z niepełnosprawnością intelektualną do ćwiczeń?']::text[], true, false, 'Małopolski Inkubator Innowacji Społecznych (MIIS), 2016–2019', 'Przewodnik po innowacjach społecznych (MIIS, 2019), część III „Pozostałe rozwiązania”, s. 44–46 (tytuł; brak opisu)', 'prawdopodobne', true),
  ('moje-ja-laboratorium-jazni-odzwierciedlonej', 'Moje Ja (Laboratorium Jaźni Odzwierciedlonej)', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS 2.0', false, 'Rozwiązanie zwane Laboratorium Jaźni Odzwierciedlonej, które ma poprawić rozumienie zachowań społecznych u dzieci z niepełnosprawnością wzroku. W IWS 2.0 trwają testy.', 'Dzieci z niepełnosprawnością wzroku trudniej rozumieją zachowania społeczne innych osób.', array['dzieci z niepełnosprawnością wzroku']::text[], '{}'::text[], null, 'Stowarzyszenie „Łazarz – Zakorzenieni w Tradycji”', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['niewidome dzieci', 'słabowidzące dzieci', 'zachowania społeczne', 'kompetencje społeczne', 'relacje z rówieśnikami', 'niepełnosprawność wzroku', 'terapia', 'dziecko', 'komunikacja', 'emocje']::text[], array['Syn jest niewidomy i trudno mu odczytywać zachowania rówieśników, szukamy wsparcia.', 'Jak uczyć dzieci słabowidzące rozumienia relacji społecznych?']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'prawdopodobne', true),
  ('dotykowa-puzzlowa-mapa-polski-z-uksztaltowaniem-terenu-i-wojewodztwami', 'Dotykowa puzzlowa mapa Polski z ukształtowaniem terenu i województwami', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS 2.0', false, 'Dotykowa mapa Polski w formie puzzli, z odwzorowanym ukształtowaniem terenu i podziałem na województwa. W IWS 2.0 trwają testy.', 'Osoby, które poznają świat dotykiem, mają mało pomocy do nauki geografii kraju (wniosek z cechy „dotykowa”).', array['osoby niewidome i słabowidzące (wniosek z tytułu)']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['mapa dotykowa', 'puzzle', 'geografia', 'niewidomi', 'słabowidzący', 'edukacja', 'województwa', 'ukształtowanie terenu', 'pomoc dydaktyczna', 'dotyk']::text[], array['Uczę niewidome dziecko geografii Polski, szukam mapy, którą można dotykać.', 'Szkoła specjalna potrzebuje pomocy dydaktycznej z mapą Polski dla uczniów niewidomych.']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'prawdopodobne', true),
  ('rehaoko-eyetracking-w-rehabilitacji-i-rozwoju-osob-niewidomych-i', 'Rehaoko – eyetracking w rehabilitacji i rozwoju osób niewidomych i słabowidzących', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS 2.0', false, 'Wykorzystanie technologii eyetrackingu (śledzenia ruchu oczu) w rehabilitacji i rozwoju osób niewidomych i słabowidzących. W IWS 2.0 trwają testy.', 'Rehabilitacja osób niewidomych i słabowidzących potrzebuje nowych narzędzi technologicznych (wniosek z tytułu).', array['osoby niewidome i słabowidzące']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['eyetracking', 'śledzenie wzroku', 'rehabilitacja wzroku', 'niewidomi', 'słabowidzący', 'technologia', 'terapia', 'dzieci niewidome', 'trening wzroku', 'niedowidzenie']::text[], array['Szukamy nowoczesnych narzędzi do rehabilitacji osób słabowidzących.', 'Czy technologie śledzenia wzroku pomagają w pracy z niewidomymi dziećmi?']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025); nazwa projektu z listy grantów', 'prawdopodobne', true),
  ('dostepnik-model-organizacji-spotkan-inspirowanych-ksiazkami', 'Dostępnik – model organizacji spotkań inspirowanych książkami', 'dla-osob-z-niepelnosprawnoscia-intelektualna', 'IWS 2.0', false, 'Model organizowania spotkań wokół książek w formie dostępnej dla osób z niepełnosprawnością intelektualną. W IWS 2.0 trwają testy.', 'Osoby z niepełnosprawnością intelektualną rzadko uczestniczą w spotkaniach czytelniczych i kulturze literackiej (wniosek z tytułu).', array['osoby z niepełnosprawnością intelektualną']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['spotkania z książką', 'klub książki', 'niepełnosprawność intelektualna', 'dostępna kultura', 'czytanie', 'język łatwy', 'biblioteka', 'literatura', 'etr', 'warsztaty']::text[], array['Chcemy prowadzić w bibliotece klub książki dostępny dla osób z niepełnosprawnością intelektualną.', 'Jak zorganizować spotkania wokół lektur zrozumiałe dla dorosłych z niepełnosprawnością intelektualną?']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025) (pełna nazwa: „Spotkania przy książce” w Liście rankingowej)', 'prawdopodobne', true),
  ('klocki-do-tworzenia-przenosnych-map-i-planow-dla-dzieci-z', 'Klocki do tworzenia przenośnych map i planów dla dzieci z niepełnosprawnością wzroku', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS 2.0', false, 'Zestaw klocków, z których dzieci z niepełnosprawnością wzroku układają przenośne mapy i plany. W IWS 2.0 trwają testy.', 'Dzieci z niepełnosprawnością wzroku mają mało pomocy do poznawania przestrzeni i orientacji w niej.', array['dzieci z niepełnosprawnością wzroku']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['klocki', 'mapy dotykowe', 'plan', 'orientacja w przestrzeni', 'niewidome dzieci', 'słabowidzące dzieci', 'pomoc dydaktyczna', 'nauka orientacji', 'zabawa', 'dotyk']::text[], array['Syn niewidomy uczy się orientacji w przestrzeni, szukam pomocy do układania planów.', 'Potrzebujemy w szkole klocków do tworzenia map dla dzieci niewidomych.']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'prawdopodobne', true),
  ('moc-wspolpracy-miedzypokoleniowa-samoorganizacja-w-uslugach', 'Moc współpracy – międzypokoleniowa samoorganizacja w usługach opiekuńczych', 'inne', 'IWS 2.0', false, 'Model, w którym różne pokolenia samoorganizują się w usługach opiekuńczych. Szczegółów nie opublikowano; w IWS 2.0 trwają testy.', 'Brakuje modeli usług opiekuńczych opartych na samoorganizacji i współpracy pokoleń (wniosek z tytułu).', array['osoby wymagające opieki', 'mieszkańcy różnych pokoleń']::text[], '{}'::text[], null, 'Fundacja Turkusowa Droga', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['usługi opiekuńcze', 'międzypokoleniowość', 'samoorganizacja', 'sąsiedzka pomoc', 'współpraca', 'senior', 'opieka', 'wzajemna pomoc', 'wolontariat', 'lokalna społeczność']::text[], array['Chcemy, żeby starsi i młodsi mieszkańcy sami organizowali sobie pomoc opiekuńczą.', 'Jak oprzeć usługi opiekuńcze w gminie na współpracy pokoleń?']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025); tytuł pełny z Listy rankingowej', 'prawdopodobne', true),
  ('wnioskomat', 'Wnioskomat', 'inne', 'IWS 2.0', false, 'Generator spersonalizowanych pism sądowych dla osób transpłciowych w procesie prawnej tranzycji (tytuł z listy rankingowej wniosku tej samej fundacji). W IWS 2.0 trwają testy.', 'Osoby transpłciowe w procesie prawnej tranzycji potrzebują pism sądowych; generator ma ułatwić ich przygotowanie.', array['osoby transpłciowe w procesie prawnej tranzycji']::text[], '{}'::text[], null, 'Fundacja Instytut Spraw Społecznych', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['osoby transpłciowe', 'tranzycja', 'pisma sądowe', 'generator pism', 'wniosek', 'prawo', 'zmiana płci', 'wsparcie prawne', 'dokumenty', 'narzędzie online']::text[], array['Osoba transpłciowa chce przygotować pozew o ustalenie płci i nie wie, jak napisać pismo.', 'Szukamy narzędzia, które pomoże wygenerować wniosek do sądu w sprawie tranzycji.']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025) (powiązanie „Wnioskomat” z „Generator spersonalizowanych pism sądowych…” wnioskuję po tym samym wnioskodawcy)', 'prawdopodobne', true),
  ('braille-easy-access-bar-extension-for-nvda', 'Braille Easy-Access-Bar Extension for NVDA', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS 2.0', false, 'Rozszerzenie do czytnika ekranu NVDA obsługujące „Braille Easy-Access-Bar” (urządzenie lub funkcję brajlowską). W IWS 2.0 trwają testy.', 'Osoby niewidome potrzebują wygodniejszego dostępu do komputera przez brajla (wniosek z tytułu).', array['osoby niewidome korzystające z czytnika ekranu NVDA']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['nvda', 'czytnik ekranu', 'braille', 'brajl', 'niewidomi', 'komputer', 'rozszerzenie', 'dostępność cyfrowa', 'pasek brajlowski', 'oprogramowanie']::text[], array['Niewidomy pracownik używa NVDA i szukam narzędzia ułatwiającego pracę z brajlem.', 'Jak poprawić dostępność komputera dla osób niewidomych korzystających z brajla?']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'prawdopodobne', true),
  ('tonobok-system-do-obslugi-bok-przez-osoby-niewidome', 'TonoBok – system do obsługi BOK przez osoby niewidome', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS 2.0', false, 'System, który umożliwia osobom niewidomym obsługę biura obsługi klienta (BOK); nazwa TonoBok odpowiada tytułowi „System do obsługi BOK-u przez osoby niewidome”. W IWS 2.0 trwają testy.', 'Osoby niewidome mają utrudniony dostęp do pracy w obsłudze klienta (wniosek z tytułu).', array['osoby niewidome', 'pracodawcy']::text[], '{}'::text[], null, 'Tono Praca Sp. z o.o.', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['biuro obsługi klienta', 'bok', 'niewidomi', 'praca', 'zatrudnienie', 'obsługa klienta', 'call center', 'aktywizacja zawodowa', 'dostępne stanowisko pracy', 'niepełnosprawność wzroku']::text[], array['Chcemy zatrudnić osobę niewidomą w biurze obsługi klienta, jak dostosować stanowisko?', 'Czy niewidomy może obsługiwać klientów dzięki specjalnemu systemowi?']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025) (powiązanie „TonoBok” z „System do obsługi BOK-u…” wnioskuję po tym samym wnioskodawcy)', 'prawdopodobne', true),
  ('lokalny-doradca-ds-zadluzenia', 'Lokalny doradca ds. zadłużenia', 'inne', 'IWS 2.0', false, 'Model usługi lokalnego doradcy, który wspiera osoby zadłużone w sprawach długów. Szczegóły nie zostały opublikowane; w IWS 2.0 trwają testy.', 'Osoby zadłużone mają ograniczony dostęp do lokalnego, fachowego wsparcia w sprawach zadłużenia.', array['osoby zadłużone', 'osoby zagrożone ubóstwem']::text[], '{}'::text[], null, 'Stowarzyszenie Program Wsparcia Zadłużonych', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['zadłużenie', 'długi', 'doradca', 'poradnictwo', 'ubóstwo', 'komornik', 'windykacja', 'upadłość konsumencka', 'finanse osobiste', 'pomoc społeczna']::text[], array['Wielu klientów GOPS ma długi i komorników, a my nie mamy kogo do nich skierować.', 'Szukamy lokalnego doradcy, który pomoże osobom zadłużonym.']::text[], true, true, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'pewne', true),
  ('oddech-aplikacja-zwiekszajaca-samoswiadomosc-podczas-dlugotrwalego', 'ODDECH – aplikacja zwiększająca samoświadomość podczas długotrwałego scrollowania', 'inne', 'IWS 2.0', false, 'Aplikacja, która ma zwiększać świadomość użytkownika podczas długiego przewijania treści w telefonie. W IWS 2.0 trwają testy.', 'Długotrwałe, nieuważne przewijanie treści w telefonie (wniosek z tytułu).', array['użytkownicy smartfonów']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['scrollowanie', 'uzależnienie od telefonu', 'higiena cyfrowa', 'aplikacja', 'samoświadomość', 'uważność', 'media społecznościowe', 'czas przed ekranem', 'dobrostan psychiczny', 'nawyki']::text[], array['Nastolatki całymi godzinami przewijają telefon, szukamy narzędzia, które to uświadamia.', 'Jak ograniczyć bezmyślne scrollowanie w mediach społecznościowych?']::text[], true, true, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'pewne', true),
  ('innowacyjny-przewodnik-konstrukcji-odziezy-dla-kobiet-na-wozkach', 'Innowacyjny Przewodnik Konstrukcji Odzieży dla Kobiet na Wózkach', 'dla-osob-o-ograniczonej-mobilnosci', 'IWS 2.0', false, 'Przewodnik konstrukcji (kroju) odzieży dla kobiet poruszających się na wózkach. W IWS 2.0 trwają testy.', 'Kobiety na wózkach mają trudność ze znalezieniem odzieży dopasowanej do sylwetki w pozycji siedzącej (wniosek z tytułu).', array['kobiety poruszające się na wózkach', 'krawcy i projektanci odzieży']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['odzież', 'wózek inwalidzki', 'kobiety', 'krój', 'moda', 'szycie', 'przewodnik', 'niepełnosprawność ruchowa', 'ubranie', 'adaptacja odzieży']::text[], array['Nie mogę znaleźć ubrań, które dobrze leżą, gdy siedzę na wózku.', 'Jak uszyć wygodną odzież dla kobiety poruszającej się na wózku?']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'prawdopodobne', true),
  ('tansze-i-innowacyjne-ksiazki-dotykowe-dla-niewidomych-i-slabowidzacych', 'Tańsze i innowacyjne książki dotykowe dla niewidomych i słabowidzących', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS 2.0', false, 'Tańsze i nowatorskie książki dotykowe dla osób niewidomych i słabowidzących. W IWS 2.0 trwają testy.', 'Książki dotykowe dla osób niewidomych i słabowidzących są drogie (wniosek z tytułu).', array['osoby niewidome i słabowidzące', 'dzieci niewidome', 'biblioteki']::text[], '{}'::text[], null, 'Fundacja Kołobajki', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['książki dotykowe', 'niewidomi', 'słabowidzący', 'czytanie', 'dzieci', 'biblioteka', 'tańsze', 'edukacja', 'dotyk', 'książki tyflograficzne']::text[], array['Biblioteka chce kupić książki dotykowe dla niewidomych dzieci, ale są bardzo drogie.', 'Gdzie znaleźć tańsze książki dotykowe dla słabowidzących?']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'prawdopodobne', true),
  ('uniwersalne-krzeslo-stolowe-z-opcja-pionizacji', 'Uniwersalne krzesło stołowe z opcją pionizacji', 'dla-osob-o-ograniczonej-mobilnosci', 'IWS 2.0', false, 'Krzesło stołowe z funkcją pionizacji, czyli ustawiania użytkownika do pozycji stojącej. W IWS 2.0 trwają testy.', 'Brakuje uniwersalnego krzesła przy stole, które pozwala też na pionizację (wniosek z tytułu).', array['osoby z ograniczoną sprawnością ruchową', 'dzieci i dorośli wymagający pionizacji']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['krzesło', 'pionizacja', 'pionizator', 'niepełnosprawność ruchowa', 'wózek', 'stół', 'rehabilitacja', 'sprzęt rehabilitacyjny', 'meble dostosowane', 'uniwersalne projektowanie']::text[], array['Syn potrzebuje pionizacji, a przy stole siedzi na zwykłym wózku, szukamy rozwiązania.', 'Czy jest krzesło do jedzenia przy stole, które pozwala też ustawić dziecko pionowo?']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'prawdopodobne', true),
  ('dom-przyjazny-demencji-platforma-internetowa-z-wizualizacja', 'Dom przyjazny demencji – platforma internetowa z wizualizacją', 'dla-seniorow', 'IWS 2.0', false, 'Internetowa platforma oparta na wiedzy naukowej, z wizualizacją domu przyjaznego osobom z demencją. W IWS 2.0 trwają testy.', 'Dom osoby z demencją trzeba dostosować, a brakuje łatwo dostępnych wskazówek, jak to zrobić (wniosek z tytułu).', array['osoby z demencją', 'rodziny i opiekunowie']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['demencja', 'alzheimer', 'dom przyjazny', 'dostosowanie mieszkania', 'wizualizacja', 'platforma internetowa', 'opiekun', 'senior', 'bezpieczne mieszkanie', 'choroba otępienna']::text[], array['Tata ma demencję, jak urządzić mu mieszkanie, żeby było bezpieczne i zrozumiałe?', 'Szukamy wskazówek dla opiekunów, jak przystosować dom do osoby z Alzheimerem.']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025) (pełny tytuł: Lista rankingowa)', 'prawdopodobne', true),
  ('aplikacja-bezpieczny-swiat-cyfrowy', 'Aplikacja Bezpieczny Świat Cyfrowy', 'inne', 'IWS 2.0', false, 'Edukacyjna aplikacja na telefony symulująca zagrożenia cyfrowe, by uczyć użytkowników ich rozpoznawania. W IWS 2.0 trwają testy.', 'Użytkownicy telefonów nie mają okazji praktycznie przećwiczyć rozpoznawania zagrożeń cyfrowych.', array['użytkownicy smartfonów', 'osoby zagrożone wykluczeniem cyfrowym']::text[], '{}'::text[], null, null, '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['bezpieczeństwo cyfrowe', 'oszustwa internetowe', 'phishing', 'symulacja', 'edukacja cyfrowa', 'aplikacja', 'cyberbezpieczeństwo', 'senior', 'dzieci', 'zagrożenia w sieci']::text[], array['Chcemy nauczyć seniorów rozpoznawać oszustwa przez telefon i internet.', 'Szukamy aplikacji do ćwiczenia reakcji na zagrożenia w sieci.']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'prawdopodobne', true),
  ('dopracypjm-platforma-komunikacyjna-online-wspierajaca-osoby-gluche-w', 'DoPracyPJM – platforma komunikacyjna online wspierająca osoby głuche w środowisku pracy', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS 2.0', false, 'Platforma komunikacyjna online wspierająca osoby głuche w środowisku pracy (nazwa wskazuje na polski język migowy). W IWS 2.0 trwają testy.', 'Osoby głuche mają bariery komunikacyjne w miejscu pracy.', array['osoby głuche', 'pracodawcy']::text[], '{}'::text[], null, 'Sieć Badawcza Łukasiewicz – Instytut Technik Innowacyjnych EMAG', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['głusi', 'głuchota', 'pjm', 'język migowy', 'praca', 'zatrudnienie', 'komunikacja', 'tłumacz', 'platforma online', 'bariery w pracy', 'pracodawca']::text[], array['Zatrudniamy osobę głuchą i nie wiemy, jak z nią się komunikować w pracy.', 'Szukamy platformy, która pomoże głuchym w komunikacji z pracodawcą.']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'prawdopodobne', true),
  ('znowu-w-biegu-proces-rehabilitacji-po-zabiegu-osseointegracji', 'Znowu w Biegu – proces rehabilitacji po zabiegu osseointegracji', 'dla-osob-o-ograniczonej-mobilnosci', 'IWS 2.0', false, 'Proces rehabilitacji po zabiegu osseointegracji, czyli wszczepieniu protezy zakotwiczonej w kości. W IWS 2.0 trwają testy.', 'Osoby po zabiegu osseointegracji potrzebują wyspecjalizowanego procesu rehabilitacji (wniosek z tytułu).', array['osoby po amputacji', 'pacjenci po osseointegracji']::text[], '{}'::text[], null, 'Fundacja Centrum Rehabilitacji Znowu w Biegu', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['osseointegracja', 'amputacja', 'proteza', 'rehabilitacja', 'po amputacji', 'kończyna dolna', 'chodzenie', 'bieganie', 'fizjoterapia', 'niepełnosprawność ruchowa']::text[], array['Mąż po amputacji ma mieć zabieg osseointegracji, gdzie znaleźć rehabilitację po nim?', 'Szukamy sprawdzonego modelu rehabilitacji po wszczepieniu protezy kotwiczonej w kości.']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'prawdopodobne', true),
  ('abc-brd-pakiet-edukacyjny-o-bezpieczenstwie-ruchu-drogowego-dla', 'ABC BRD – pakiet edukacyjny o bezpieczeństwie ruchu drogowego dla uczniów z niepełnosprawnością wzrokową', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'IWS 2.0', false, 'Pakiet edukacyjny (w tytule wniosku: manual) wspierający naukę zasad bezpieczeństwa ruchu drogowego przez uczniów z niepełnosprawnością wzrokową. W IWS 2.0 trwają testy.', 'Uczniowie z niepełnosprawnością wzrokową mają mało dostosowanych materiałów do nauki bezpiecznego zachowania w ruchu drogowym.', array['uczniowie z niepełnosprawnością wzrokową', 'nauczyciele']::text[], '{}'::text[], null, 'Instytut Transportu Samochodowego', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['ruch drogowy', 'bezpieczeństwo', 'brd', 'niewidomi', 'słabowidzący', 'uczniowie', 'edukacja', 'przejście dla pieszych', 'szkoła', 'nauka']::text[], array['Uczę niewidome dziecko bezpiecznego przechodzenia przez ulicę, szukam materiałów.', 'Szkoła dla niewidomych potrzebuje pakietu o bezpieczeństwie w ruchu drogowym.']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025) (pełny tytuł: Lista rankingowa)', 'prawdopodobne', true),
  ('pierwsza-w-polsce-stacjonarna-szkola-higieny-cyfrowej-dla-rodzicow-i', 'Pierwsza w Polsce stacjonarna szkoła higieny cyfrowej dla rodziców i dzieci', 'dla-dzieci-mlodziezy-i-rodziny', 'IWS 2.0', false, 'Stacjonarna szkoła higieny cyfrowej dla rodziców i dzieci w wieku przedszkolnym i wczesnoszkolnym („Higiena cyfrowa w rodzinie. Coś wielkiego od małego!”). W IWS 2.0 trwają testy.', 'Małe dzieci i ich rodzice potrzebują nauki zdrowych nawyków korzystania z urządzeń cyfrowych.', array['rodzice', 'dzieci przedszkolne i w wieku wczesnoszkolnym']::text[], '{}'::text[], null, 'Fundacja Dbam o Mój Zasięg', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['higiena cyfrowa', 'dzieci', 'rodzice', 'ekrany', 'telefon', 'tablet', 'przedszkole', 'uzależnienie od ekranów', 'wychowanie', 'czas przed ekranem']::text[], array['Nasze przedszkolaki za dużo siedzą przed ekranem, szukamy zajęć dla rodziców i dzieci.', 'Jak nauczyć rodziców rozsądnego korzystania z urządzeń z małymi dziećmi?']::text[], true, true, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025) (pełny tytuł: Lista rankingowa)', 'pewne', true),
  ('krok-po-kroku-do-sprawnosci-personalizowany-przewodnik-ruchu-dla', 'Krok po kroku do sprawności – personalizowany przewodnik ruchu dla seniorów', 'dla-seniorow', 'IWS 2.0', false, 'Personalizowany przewodnik dotyczący ruchu dla seniorów. W IWS 2.0 trwają testy.', 'Seniorzy potrzebują aktywności ruchowej dopasowanej do własnej sprawności.', array['seniorzy']::text[], '{}'::text[], null, 'Fundacja Tarnowskiej Agencji Rozwoju Regionalnego', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['senior', 'ruch', 'ćwiczenia', 'sprawność', 'aktywność fizyczna', 'przewodnik', 'personalizacja', 'zdrowie seniora', 'gimnastyka', 'profilaktyka upadków']::text[], array['Chcemy w klubie seniora zachęcić starszych do ruchu, ale każdy ma inne możliwości.', 'Szukam indywidualnego planu ćwiczeń dla starszej osoby.']::text[], true, true, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'pewne', true),
  ('pastylki-wiedzy-cyfrowe-instrukcje-medyczne', 'Pastylki wiedzy – cyfrowe instrukcje medyczne', 'dla-zdrowia-i-medycyny', 'IWS 2.0', false, 'Cyfrowe instrukcje medyczne udostępniane w formie „pastylek wiedzy”. W IWS 2.0 trwają testy.', 'Pacjenci potrzebują łatwo dostępnych instrukcji medycznych w formie cyfrowej.', array['pacjenci', 'opiekunowie']::text[], '{}'::text[], null, 'Framica Polska Sp. z o.o.', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['instrukcje medyczne', 'pacjent', 'edukacja zdrowotna', 'cyfrowe', 'ulotka', 'zdrowie', 'instrukcja obsługi', 'wyroby medyczne', 'qr', 'zrozumiała informacja']::text[], array['Pacjenci nie rozumieją instrukcji do sprzętu medycznego, szukamy prostej wersji cyfrowej.', 'Jak przekazywać pacjentom krótkie, zrozumiałe instrukcje medyczne?']::text[], true, true, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025)', 'pewne', true),
  ('swiadoma-integracja-ozn', 'Świadoma Integracja OzN', 'inne', 'IWS 2.0', false, 'Model integracji osób z niepełnosprawnościami (OzN); w Liście rankingowej wniosek nosi tytuł „Model Integracji OZN”. W IWS 2.0 trwają testy.', 'Integracja osób z niepełnosprawnościami ze społecznością wymaga nowych modeli (wniosek z tytułu).', array['osoby z niepełnosprawnościami']::text[], '{}'::text[], null, 'Fundacja Fireflies', '{"opis_pdf":null,"film":null,"pakiet_zip":null,"zasady_wykorzystania":null,"inne":[]}'::jsonb, 'https://rops.krakow.pl/realizowane-projekty-i-zadania/inkubator-wlaczenia-spolecznego-20,udzielone-granty-1', array['integracja', 'niepełnosprawność', 'osoby z niepełnosprawnościami', 'włączenie społeczne', 'model', 'akceptacja', 'wspólne zajęcia', 'świadomość', 'społeczność', 'oz n']::text[], array['Chcemy lepiej zintegrować osoby z niepełnosprawnościami z resztą mieszkańców.', 'Szukamy gotowego modelu integracji w lokalnej społeczności.']::text[], true, false, 'Inkubator Włączenia Społecznego 2.0 (IWS 2.0), 2024–2028; innowacja w fazie testów (grant podpisany)', 'rops.krakow.pl: IWS 2.0 / Udzielone granty (lista grantobiorców) + Lista rankingowa (Zarządzenie IS-430-1/25 z 21.05.2025) (powiązanie „Świadoma Integracja OzN” z „Model Integracji OZN” wnioskuję po tym samym wnioskodawcy; rozwinięcie skrótu OzN domyślne)', 'prawdopodobne', true);
insert into public.challenge_areas (id, nr, nazwa, definicja, dane, slowa_kluczowe, kategorie_biblioteki, strony, zrodlo_url) values
  ('rodzina-piecza', 1, 'Rodzina i piecza zastępcza', 'Wsparcie rodzin, które mają trudność z opieką i wychowaniem dzieci, oraz piecza zastępcza, gdy dziecko nie może zostać z rodzicami biologicznymi.', array['W 2023 r. liczba dzieci w pieczy zastępczej wzrosła o 3,5% względem 2022 r. (GUS).', 'Za mało rodzin zastępczych spowalnia deinstytucjonalizację.', 'Do placówek trafiają też dzieci poniżej 10 lat, a placówki bywają przepełnione.', 'Duża część dzieci w pieczy to dzieci starsze, z licznego rodzeństwa lub z niepełnosprawnością (NIK 2022).']::text[], array['piecza zastępcza', 'rodzina zastępcza', 'adopcja', 'rodzeństwo', 'dom dziecka', 'placówka opiekuńczo-wychowawcza', 'dysfunkcyjna rodzina', 'kompetencje rodzicielskie', 'deinstytucjonalizacja', 'PCPR']::text[], array['dla-dzieci-mlodziezy-i-rodziny']::text[], '3–7', 'https://rops.krakow.pl/mpliki/IS/IWS_20/za._nr_2._Mapa_Wyzwa_Spoecznych.pdf'),
  ('bezdomnosc', 2, 'Bezdomność', 'Najostrzejsza forma wykluczenia: brak własnego schronienia spełniającego minimalne warunki. Zwykle ma wiele przyczyn naraz: ubóstwo, bezrobocie, uzależnienia, przemoc, eksmisje, rozpad rodziny, kryzysy psychiczne.', array['Rośnie liczba młodych osób w kryzysie bezdomności (0–25 lat).', 'Młodzi bezdomni są mało widoczni i trudni do policzenia.', 'Niepełnoletność utrudnia instytucjonalne wsparcie nastolatków.', 'Luka we wsparciu po opuszczeniu placówki opiekuńczo-wychowawczej.']::text[], array['bezdomność', 'kryzys bezdomności', 'noclegownia', 'schronisko', 'młodzi bezdomni', 'usamodzielnienie', 'mieszkanie wspierane', 'uzależnienie', 'eksmisja', 'streetworking']::text[], array['dla-osob-w-kryzysie-bezdomnosci']::text[], '8–11', 'https://rops.krakow.pl/mpliki/IS/IWS_20/za._nr_2._Mapa_Wyzwa_Spoecznych.pdf'),
  ('niepelnosprawnosc', 3, 'Niepełnosprawność', 'Trwałe ograniczenie sprawności, które utrudnia pracę i samodzielne życie; może być wrodzone albo nabyte. Trudności są nie tylko medyczne, ale też ekonomiczne, prawne, komunikacyjne, edukacyjne i technologiczne.', array['Wskaźnik zatrudnienia osób z niepełnosprawnością (16–64 lata) pod koniec 2023 r.: 30,1% (BDL GUS).', 'NSP 2021: 5,4 mln osób z niepełnosprawnością, 14,3% ludności.', 'Badanie PFRON 2024: najważniejsze potrzeby to mieszkalnictwo, czas wolny, rehabilitacja, praca i informacja; najmniej zaspokojony jest dostęp do informacji.', 'Krytyczny moment: przejście z edukacji do dorosłości i pracy.']::text[], array['niepełnosprawność', 'osoba z niepełnosprawnością', 'wózek', 'niewidomy', 'głuchy', 'dostępność', 'bariery architektoniczne', 'asystent osobisty', 'mieszkanie wspomagane', 'praca', 'rehabilitacja', 'komunikacja alternatywna']::text[], array['dla-osob-o-ograniczonej-mobilnosci', 'dla-osob-z-niepelnosprawnoscia-sensoryczna', 'dla-osob-z-niepelnosprawnoscia-intelektualna']::text[], '12–16', 'https://rops.krakow.pl/mpliki/IS/IWS_20/za._nr_2._Mapa_Wyzwa_Spoecznych.pdf'),
  ('ubostwo', 4, 'Ubóstwo', 'Brak środków na zaspokojenie podstawowych potrzeb; najczęściej dotyka odbiorców świadczeń, rolników i mieszkańców wsi poza aglomeracjami.', array['Ubóstwo skrajne w 2023 r.: 6,6% gospodarstw domowych, wzrost o 2 pp. (GUS).', 'Progi 2023 dla 1 osoby: ustawowe 776 zł, skrajne 913 zł, relatywne 1092 zł.', 'Ubóstwo skrajne wśród rolników 14,1%, wśród utrzymujących się z niezarobkowych źródeł 17,9%.', 'Zjawisko pracujących biednych (working poor).', '30% Polaków deklaruje lęk przed biedą, najwięcej od 2015 r. (Raport o biedzie 2023).']::text[], array['ubóstwo', 'bieda', 'niskie dochody', 'ubóstwo energetyczne', 'opał', 'niedożywienie', 'pomoc żywnościowa', 'bezrobocie', 'spółdzielnia socjalna', 'zasiłek', 'renta', 'wieś']::text[], array['dla-rynku-pracy', 'dla-osob-w-kryzysie-bezdomnosci']::text[], '17–21', 'https://rops.krakow.pl/mpliki/IS/IWS_20/za._nr_2._Mapa_Wyzwa_Spoecznych.pdf'),
  ('cudzoziemcy', 5, 'Integracja cudzoziemców', 'Polityki włączające, które dają migrantom równe szanse w życiu gospodarczym, społecznym, kulturalnym i politycznym gminy oraz równy dostęp do usług publicznych.', array['Integracja to proces wielostronny, nie asymilacja.', 'Model lokalny: partycypacja migrantów i organizacji, działania oparte na diagnozie, koordynacja przez wiodącą jednostkę samorządu, stabilne finansowanie zamiast krótkich projektów.']::text[], array['cudzoziemcy', 'migranci', 'uchodźcy', 'Ukraina', 'język polski', 'asystent międzykulturowy', 'tłumacz', 'integracja', 'szkoła', 'uznawanie kwalifikacji']::text[], array['dla-cudzoziemcow']::text[], '22–26', 'https://rops.krakow.pl/mpliki/IS/IWS_20/za._nr_2._Mapa_Wyzwa_Spoecznych.pdf'),
  ('zdrowie', 6, 'Zdrowie', 'Edukacja zdrowotna, dostęp do opieki medycznej, profilaktyka i zdrowe środowisko jako podstawa zdrowia fizycznego i psychicznego.', array['Choroba niedokrwienna serca pozostaje największym wyzwaniem systemu ochrony zdrowia; udary to druga przyczyna zgonów.', 'Rośnie zachorowalność na nowotwory oraz chorobę Alzheimera i inne otępienia.', 'Pandemia nasiliła samotność starszych osób mieszkających samotnie.', 'Palenie i zła dieta to główne przyczyny wyższej umieralności.']::text[], array['zdrowie', 'profilaktyka', 'opiekun rodzinny', 'opieka długoterminowa', 'choroba przewlekła', 'rehabilitacja', 'otyłość', 'serce', 'cukrzyca', 'dostęp do lekarza', 'telemedycyna']::text[], array['dla-zdrowia-i-medycyny']::text[], '27–31', 'https://rops.krakow.pl/mpliki/IS/IWS_20/za._nr_2._Mapa_Wyzwa_Spoecznych.pdf'),
  ('zdrowie-psychiczne', 7, 'Zdrowie psychiczne', 'Równowaga emocjonalna, psychiczna i społeczna: radzenie sobie ze stresem, dobre relacje, podejmowanie decyzji – a nie tylko brak choroby.', array['Rośnie liczba prób samobójczych wśród dzieci i młodzieży.', 'Nadmierne korzystanie z internetu wiąże się z depresją i zaburzeniami odżywiania; FOMO dotyczy co trzeciego młodego Polaka.', 'Psychiatria to ok. 3% wydatków NFZ.', 'Stygmatyzacja i słaby dostęp sprawiają, że problemy są niedoszacowane.']::text[], array['zdrowie psychiczne', 'depresja', 'kryzys psychiczny', 'samobójstwo', 'młodzież', 'stres', 'izolacja', 'uzależnienie od internetu', 'terapia', 'psycholog', 'CZP', 'stygmatyzacja']::text[], array['dla-zdrowia-i-medycyny', 'dla-dzieci-mlodziezy-i-rodziny']::text[], '32–38', 'https://rops.krakow.pl/mpliki/IS/IWS_20/za._nr_2._Mapa_Wyzwa_Spoecznych.pdf'),
  ('seniorzy', 8, 'Seniorzy', 'Dostosowanie się do starzejącego się społeczeństwa: opieka zdrowotna i opiekuńcza, godna, bezpieczna i możliwie samodzielna starość bez izolacji i dyskryminacji.', array['Największe problemy seniorów: zdrowie, samotność, finanse, cyfryzacja.', 'Wielu seniorów mieszka w budynkach z barierami architektonicznymi.', 'Wielolekowość (polipragmazja) to poważne ryzyko.', 'Samotność jest powiązana z gorszą sytuacją materialną.']::text[], array['senior', 'osoba starsza', 'samotność', 'demencja', 'opieka domowa', 'usługi opiekuńcze', 'wielolekowość', 'kompetencje cyfrowe', 'bariery architektoniczne', 'wdowa', 'DDP', 'klub seniora']::text[], array['dla-seniorow']::text[], '39–43', 'https://rops.krakow.pl/mpliki/IS/IWS_20/za._nr_2._Mapa_Wyzwa_Spoecznych.pdf');
insert into public.challenges (id, obszar_id, tekst, kolejnosc) values
  ('wiecej-rodzin-zastepczych', 'rodzina-piecza', 'Więcej pozytywnie zweryfikowanych kandydatów na rodziny zastępcze', 1),
  ('wspolpraca-powiatow', 'rodzina-piecza', 'Lepsza współpraca między powiatami w systemie pieczy', 2),
  ('nierozdzielanie-rodzenstwa', 'rodzina-piecza', 'Nierozdzielanie rodzeństwa przy umieszczaniu w pieczy', 3),
  ('krotszy-pobyt', 'rodzina-piecza', 'Krótszy pobyt w pieczy i szybsze przejście do docelowej formy opieki', 4),
  ('spojny-system-adopcyjny', 'rodzina-piecza', 'Spójne standardy pracy ośrodków adopcyjnych', 5),
  ('mlodzi-bezdomni', 'bezdomnosc', 'Oferta wsparcia dopasowana do młodych dorosłych i nastolatków', 1),
  ('niewidzialnosc', 'bezdomnosc', 'Docieranie do „niewidzialnych” młodych osób w kryzysie bezdomności', 2),
  ('przejscie-z-placowki', 'bezdomnosc', 'Ciągłość pomocy po opuszczeniu placówki opiekuńczo-wychowawczej', 3),
  ('wiezi', 'bezdomnosc', 'Budowanie więzi i sieci wsparcia osób bez rodziny', 4),
  ('rynek-pracy', 'niepelnosprawnosc', 'Większy dostęp do rynku pracy', 1),
  ('edukacja', 'niepelnosprawnosc', 'Wykształcenie dające samodzielność i rozwój zawodowy', 2),
  ('relacje', 'niepelnosprawnosc', 'Samodzielne relacje społeczne i towarzyskie', 3),
  ('wsparcie-emocjonalne', 'niepelnosprawnosc', 'Wsparcie emocjonalne', 4),
  ('dostepnosc', 'niepelnosprawnosc', 'Wsparcie techniczne, infrastruktura i dostępność', 5),
  ('mobilnosc', 'niepelnosprawnosc', 'Samodzielne przemieszczanie się i korzystanie z usług bez asysty', 6),
  ('opieka-medyczna', 'niepelnosprawnosc', 'Dostęp do opieki medycznej, fizjoterapii i pomocy w codziennych czynnościach', 7),
  ('zainteresowania', 'niepelnosprawnosc', 'Rozwój zainteresowań', 8),
  ('mieszkania', 'niepelnosprawnosc', 'Mieszkania dostosowane do ograniczeń funkcjonalnych', 9),
  ('ubostwo-dzieci', 'ubostwo', 'Ubóstwo dzieci – dobra wczesna opieka i edukacja', 1),
  ('ubostwo-seniorow', 'ubostwo', 'Ubóstwo seniorów', 2),
  ('ubostwo-onp', 'ubostwo', 'Ubóstwo osób z niepełnosprawnościami', 3),
  ('pracujacy-biedni', 'ubostwo', 'Ubóstwo osób pracujących, np. drobnych rolników', 4),
  ('bezrobotni-bezdomni', 'ubostwo', 'Bezrobotni i bezdomni – zatrudnienie socjalne, spółdzielnie socjalne', 5),
  ('uchodzcy', 'ubostwo', 'Ubóstwo uchodźców z Ukrainy', 6),
