insert into public.personas (id, obszar_id, imie, opis, cele, wyzwania, motywacje) values
  ('persona-rodzina-piecza', 'rodzina-piecza', 'Ania i Staś', 'Rodzeństwo z dysfunkcyjnej rodziny, 7 i 12 lat; Ania ma zespół Downa, Staś słabo słyszy; wielokrotnie zmieniali rodziny zastępcze i placówki.', array['zamieszkać razem w rodzinie zastępczej', 'dostać wsparcie specjalistyczne', 'nauczyć się budować relacje']::text[], array['niepełnosprawność obojga dzieci', 'trudne doświadczenia z domu', 'brak stabilnego miejsca']::text[], array['mieć prawdziwą rodzinę', 'nie być rozdzielonymi', 'być akceptowanym przez rówieśników']::text[]),
  ('persona-bezdomnosc', 'bezdomnosc', 'Kuba', '22 lata, były wychowanek placówki, nocuje rotacyjnie u znajomych, objawy uzależnienia, nie utrzymał mieszkania wspieranego.', array['nocleg i jedzenie na najbliższe dni', 'dostęp do prądu i telefonu', 'zachować schludny wygląd']::text[], array['znalezienie noclegu', 'brak osób wspierających w dorosłości']::text[], array['żeby nikt nie zauważył braku domu', 'zmienić swoje życie']::text[]),
  ('persona-niepelnosprawnosc', 'niepelnosprawnosc', 'Krystian', '38 lat, mieszka sam w małej miejscowości, porażenie czterokończynowe, nie mówi; pracuje zdalnie, obsługuje komputer wzrokiem.', array['robić codzienne rzeczy bez obciążania innych', 'mieć znajomych', 'rozwijać się zawodowo']::text[], array['samotność', 'samoobsługa i wyjście z domu', 'utrzymanie zdrowia']::text[], array['mieć w życiu coś więcej niż pracę', 'wychodzić z domu, kiedy chce', 'decydować o sobie']::text[]),
  ('persona-ubostwo', 'ubostwo', 'Tomek', '60 lat, renta rolnicza, wykształcenie techniczne, do niedawna mieszkał z matką; nie pracuje.', array['bezpieczeństwo finansowe i zdrowotne', 'praca dorywcza', 'opał na zimę']::text[], array['samotność i brak wsparcia', 'rezygnacja, beznadzieja', 'ryzyko alkoholizmu']::text[], array['spotkać ludzi', 'mieć pewność jedzenia i ciepła zimą']::text[]),
  ('persona-cudzoziemcy', 'cudzoziemcy', 'Swietłana', '37 lat, z Ukrainy, dwoje dzieci (4 i 9 lat), mąż został w Ukrainie; nauczycielka historii, w Polsce szuka pracy poza zawodem.', array['bezpieczeństwo rodziny', 'praca i mieszkanie', 'przedszkole i szkoła dla dzieci']::text[], array['wynajem mieszkania', 'adaptacja dzieci, które nie mówią po polsku', 'odnalezienie się w Polsce']::text[], array['duża wewnętrzna motywacja do zmiany']::text[]),
  ('persona-zdrowie', 'zdrowie', 'Stanisław', '56 lat, pracuje na etacie i opiekuje się chorą matką; zaniedbuje własne zdrowie (otyłość, choroba serca), wycofany społecznie.', array['pogodzić pracę z opieką nad matką', 'więcej energii i lepsze zdrowie', 'wzmocnić relacje']::text[], array['fizyczne i emocjonalne obciążenie opieką', 'niepokój o zdrowie']::text[], array['bezpieczeństwo matki', 'chwila dla siebie']::text[]),
  ('persona-zdrowie-psychiczne-1', 'zdrowie-psychiczne', 'Mateusz', '17 lat, liceum w dużym mieście, większość czasu w sieci, po rozstaniu odczuwa pustkę i stany depresyjne.', array['cele poza światem wirtualnym', 'wsparcie w emocjach', 'przynależność do grupy']::text[], array['mało kontaktów z rówieśnikami', 'dużo czasu przy komputerze', 'trudność z emocjami']::text[], array['poczucie bycia ważnym', 'akceptacja', 'bezpieczeństwo w kryzysie']::text[]),
  ('persona-zdrowie-psychiczne-2', 'zdrowie-psychiczne', 'Karina', '41 lat, duże miasto, niedawna diagnoza choroby afektywnej dwubiegunowej, pod opieką psychiatry, wraca na rynek pracy.', array['stabilne zatrudnienie', 'wsparcie w aktywizacji zawodowej']::text[], array['powrót po szpitalu', 'wstyd po diagnozie', 'lęk przed odrzuceniem']::text[], array['powrót do normalnego życia', 'odbudowa wiary w siebie']::text[]),
  ('persona-seniorzy', 'seniorzy', 'Janina', '73 lata, mieszka sama w małym mieście, niedawno owdowiała, rzadko wychodzi, wiele chorób i leków.', array['mniej samotności, więcej aktywności', 'poczucie wartości', 'świadome dbanie o zdrowie i leki']::text[], array['samotność', 'nadużywanie leków i suplementów', 'życie po stracie męża']::text[], array['radość z prostych rzeczy', 'organizacja dnia', 'wyjście do ludzi']::text[]);
